const items: CultureArticle[] = [{"id":"lng-058","version":2,"slug":"pan-and-pani-polish-politeness-that-speaks-about-you-not-to-you","contentType":"note","category":"communication","title":{"ar":"بان وباني: التهذيب البولندي الذي يتحدث عنك لا إليك","de":"Pan und Pani: Polnische Höflichkeit, die über dich spricht, nicht zu dir","en":"Pan and Pani: Polish politeness that speaks about you, not to you"},"deck":{"ar":"في بولندا، يستخدم الناس صيغة الغائب مع لقب 'بان' أو 'باني' للحفاظ على مسافة مهذبة، حتى عند الوقوف قريبين.","de":"In Polen verwendet man die dritte Person mit 'pan' oder 'pani', um eine höfliche Distanz zu wahren, selbst wenn man nahe beieinander steht.","en":"In Poland, people use third-person forms with 'pan' or 'pani' to maintain a polite distance, even when standing close together."},"teaser":{"ar":"اكتشف كيف يعكس نظام المخاطبة البولندي 'بان/باني' الاحترام والتحول الاجتماعي، وكيف يختلف استخدامه بين الأجيال والمناطق.","de":"Entdecke, wie das polnische Anredesystem 'pan/pani' Respekt und sozialen Wandel widerspiegelt und wie sich der Gebrauch je nach Generation und Region unterscheidet.","en":"Discover how the Polish address system 'pan/pani' reflects respect and social change, and how its use varies across generations and regions."},"readingMinutes":1,"sections":{"ar":[{"heading":"صيغة الغائب: مسافة حتى مع القرب","paragraphs":["في اللغة البولندية، يستخدم المخاطبة الرسمية 'بان' (سيدي) و'باني' (سيدتي) مع أفعال الغائب: 'Czy mógłby Pan powtórzyć؟' (هل يمكنك، سيدي، أن تعيد؟). هذا التركيب يحافظ على مسافة نحوية حتى عندما يقف الشخصان قريبين جدًا.","الضمير 'ty' (أنت) مخصص للأصدقاء والعائلة والأطفال، وأحيانًا الزملاء، والانتقال إليه خطوة تفاوضية."]},{"heading":"بين الرسمية والود: لمسة شخصية","paragraphs":["في المتاجر والمكاتب، أصبح استخدام 'بان' أو 'باني' مع الاسم الأول شائعًا بشكل متزايد، وهو حل وسط بين الرسمية والود.","يظهر نظام 'بان/باني' نفسه في التشيكية والسلوفاكية، لكن البولندية تستخدمه بشكل أكبر في لقاءات الخدمة وفي البريد الإلكتروني. يختلف الاستخدام بين الأجيال والمناطق: غرب بولندا والمدن الكبرى تنتقل إلى 'ty' بشكل أسرع، والعديد من أماكن العمل تستخدم الأسماء الأولى مع الحفاظ على 'بان' في التواصل مع العملاء."]}],"de":[{"heading":"Dritte Person: Distanz trotz Nähe","paragraphs":["Im Polnischen verwendet man die formelle Anrede 'pan' (Herr) und 'pani' (Frau) mit Verben in der dritten Person: 'Czy mógłby Pan powtórzyć?' (Könnten Sie, Herr, wiederholen?). Diese Konstruktion wahrt eine grammatische Distanz, auch wenn die beiden Personen nahe beieinander stehen.","Das Pronomen 'ty' (du) ist Freunden, Familie, Kindern und manchmal Kollegen vorbehalten, und der Wechsel dazu ist ein ausgehandelter Schritt."]},{"heading":"Zwischen Förmlichkeit und Freundlichkeit: eine persönliche Note","paragraphs":["In Geschäften und Büros wird 'pan' oder 'pani' zusammen mit dem Vornamen immer häufiger verwendet – ein Kompromiss zwischen Förmlichkeit und Freundlichkeit.","Dasselbe pan/pani-System gibt es auch im Tschechischen und Slowakischen, aber Polnisch verwendet es stärker in Service-Situationen und in E-Mails. Der Gebrauch unterscheidet sich zwischen Generationen und Regionen: Westpolen und Großstädte wechseln schneller zum 'ty', und viele Arbeitsplätze verwenden Vornamen, behalten aber 'pan' im Kundenkontakt bei."]}],"en":[{"heading":"Third person: distance even when close","paragraphs":["In Polish, formal address uses 'pan' (sir) and 'pani' (madam) with third-person verbs: 'Czy mógłby Pan powtórzyć?' (could you repeat, sir?). This construction keeps a grammatical distance even when the two people are standing close together.","The pronoun 'ty' (you) is reserved for friends, family, children and sometimes colleagues, and switching to it is a negotiated step."]},{"heading":"Between formality and friendliness: a personal touch","paragraphs":["In shops and offices, 'pan' or 'pani' plus a first name is increasingly common, a compromise between formality and friendliness.","The same pan/pani system appears in Czech and Slovak, but Polish uses it more heavily in service encounters and in email. Usage differs between generations and regions: western Poland and big cities switch to 'ty' faster, and many workplaces use first names while keeping 'pan' in customer contact."]}]},"context":{"countries":["PL"],"region":"Nationwide","continent":"europe","languages":["pl"],"period":"contemporary"},"tags":["communication","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"Polish language","de":"Polish language","en":"Polish language"},"url":"https://en.wikipedia.org/wiki/Polish_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Honorific","de":"Honorific","en":"Honorific"},"url":"https://en.wikipedia.org/wiki/Honorific","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالب من وارسو يرسل بريدًا إلكترونيًا إلى محاضر باستخدام 'Szanowny Panie' مع اللقب وأفعال الغائب، ثم يوقّع باسمه الأول، لأن الافتتاحية يجب أن تظل رسمية حتى عندما تكون الخاتمة ودية.","de":"Ein Warschauer Student schreibt einer Dozentin eine E-Mail mit 'Szanowny Panie' plus Titel und Verben in der dritten Person und unterschreibt mit dem Vornamen, weil die Anrede formell bleiben muss, auch wenn der Schluss herzlich ist.","en":"A Warsaw student emails a lecturer with 'Szanowny Panie' plus the title and third-person verbs, then signs off with a first name, because the opening must stay formal even when the closing is warm."},"misunderstanding":{"ar":"يعتقد البعض أن استخدام صيغة الغائب يعني البرود، لكنها في الواقع علامة احترام تحافظ على الحدود المناسبة.","de":"Manche halten die dritte Person für distanziert, aber sie ist ein Zeichen von Respekt, das angemessene Grenzen wahrt.","en":"Some think the third-person form is distant, but it is actually a sign of respect that maintains appropriate boundaries."},"comparison":{"ar":"على عكس اللغة الإنجليزية التي تستخدم 'you' للجميع، تميز البولندية بين الرسمي وغير الرسمي في كل جملة تقريبًا.","de":"Anders als im Englischen, wo 'you' für alle verwendet wird, unterscheidet das Polnische in fast jedem Satz zwischen formell und informell.","en":"Unlike English, which uses 'you' for everyone, Polish distinguishes between formal and informal in almost every sentence."},"expression":{"original":"Czy mógłby Pan...?","language":"Polski (Polish)","gloss":{"ar":"هل يمكنك، سيدي...؟","de":"Könnten Sie, Herr...?","en":"Could you, sir...?"},"usage":{"ar":"تستخدم لطلب مهذب من شخص غير معروف أو في موقف رسمي.","de":"Wird für eine höfliche Bitte an eine unbekannte Person oder in einer formellen Situation verwendet.","en":"Used to make a polite request to an unknown person or in a formal situation."},"transliteration":"Czy moglby Pan...?"}},{"id":"lng-059","version":2,"slug":"tegezes-and-magazas-hungarian-s-two-machines-for-the-same-sentence","contentType":"note","category":"communication","title":{"ar":"التِّغازيش والمَغازيش: آلتان لصياغة الجملة نفسها","de":"Tegezes und Magazas: zwei Maschinen für denselben Satz","en":"Tegezes and magazas: two machines for one sentence"},"deck":{"ar":"الهنغارية تغيّر نهايات الأفعال تبعاً للمسافة الاجتماعية، فيصبح الاحترام جزءاً من بنية الجملة لا مجرد كلمة إضافية.","de":"Im Ungarischen verändern sich die Verbendungen mit der sozialen Distanz. Höflichkeit steckt in der Grammatik, nicht nur in einem Wort.","en":"Hungarian changes verb endings with social distance, so politeness lives inside the grammar rather than in a single added word."},"teaser":{"ar":"في هنغاريا، اختيار صيغة المخاطبة ليس تفصيلاً صغيراً: نهاية الفعل وحدها تكشف المسافة بين المتكلم والمستمع.","de":"In Ungarn ist die Anrede keine Kleinigkeit: Die Endung des Verbs allein zeigt, wie nah oder fern sich zwei Menschen stehen.","en":"In Hungary, choosing how to address someone is no small matter: the verb ending alone shows how close or distant two people stand."},"readingMinutes":1,"sections":{"ar":[{"heading":"فعلٌ واحد ومسافتان","paragraphs":["تميّز الهنغارية بين التِّغازيش، أي صيغة المخاطبة المألوفة، والمَغازيش، أي الصيغة الرسمية التي تستخدم ماغا أو أون. ومع كل صيغة تتغير نهايات الأفعال، فلا يمكن الكلام دون حسم هذه المسافة.","تستخدم الصيغة الرسمية نهايات الغائب لمخاطبة الحاضر، فتحفظ في القواعد خطوةً من البعد. أما أون فهي الأقدم والأكثر تحفظاً، تُستعمل مع المسؤولين وفي الريف، بينما تشيع ماغا في المدن وقد تبدو باردة قليلاً.","يختلف الاستعمال بحسب المنطقة والجيل، فبعض كبار السن يعدّون ماغا مسيئة ويفضّلون أون، كما تحفظ هنغارية المهجر أنماطاً رسمية أقدم."]},{"heading":"من يفتح باب القرب؟","paragraphs":["الانتقال من ماغا إلى التِّغازيش يعرضه عادةً الشخص الأكبر أو الأعلى مكانة، وكثيراً ما يُصاغ بسؤال: هل تسمح لي باستخدام صيغة المخاطبة المألوفة؟","ولأن الهنغارية لاصقة، فإن نهاية التأدب لاحقة داخل الفعل لا ضمير منفصل، وحذفها يغيّر الجملة كلها.","في عيادة في بودابست يسأل طبيب مريضاً في الستينيات إن كان يسمح له بالتِّغازيش، فيوافق المريض، ويتابع اللقاء بنهايات أفعال مختلفة للطرفين."]}],"de":[{"heading":"Ein Verb, zwei Abstände","paragraphs":["Das Ungarische unterscheidet tegezes, die vertraute Anrede, von magazas, der förmlichen Form mit maga oder on. Mit jeder Form ändern sich die Verbendungen, man kann also nicht sprechen, ohne diese Distanz zu klären.","Die förmliche Form verwendet für den Angesprochenen Endungen der dritten Person und hält so einen Schritt Abstand in der Grammatik. On ist älter und distanzierter, üblich bei Behörden und auf dem Land; maga ist in Städten verbreitet und kann etwas kühl klingen.","Der Gebrauch variiert nach Region und Generation: Manche ältere Ungarn empfinden maga als kränkend und ziehen on, und die ungarische Diaspora bewahrt oft ältere förmliche Muster."]},{"heading":"Wer öffnet die Tür zur Nähe?","paragraphs":["Den Wechsel von maga zu te bietet meist die ältere oder ranghöhere Person an, oft mit der Frage, ob sie duzen dürfe.","Da das Ungarische agglutinierend ist, sitzt die Höflichkeitsendung als Suffix im Verb und nicht in einem eigenen Pronomen; fällt sie weg, ändert sich der ganze Satz.","In einer Budapester Praxis fragt ein Arzt einen Patienten in den Sechzigern, ob er duzen dürfe; der Patient stimmt zu, und das Gespräch läuft mit anderen Verbendungen für beide weiter."]}],"en":[{"heading":"One verb, two distances","paragraphs":["Hungarian distinguishes tegezes, the familiar te, from magazas, the formal maga or on, and the verb endings change with each. You cannot finish a sentence without settling that distance.","The formal form uses third-person verb endings for a second-person addressee, so the grammar keeps a step of distance. On is the older, more distant form used with officials and in rural settings, while maga is common in cities and can sound slightly cold.","Usage varies by region and generation: some older Hungarians find maga offensive and prefer on, and diaspora Hungarian often preserves older formal patterns."]},{"heading":"Who opens the door to closeness?","paragraphs":["Switching from maga to te is offered by the older or senior person, often with szabad tegezodnom?, may I use te.","Because Hungarian is agglutinative, the polite ending is a suffix inside the verb rather than a separate pronoun, and dropping it changes the whole sentence.","A Budapest doctor asks a patient in his sixties whether he may use te; the patient agrees, and the consultation continues with different verb endings for both of them."]}]},"context":{"countries":["HU"],"region":"Nationwide","continent":"europe","languages":["hu"],"period":"contemporary"},"tags":["communication","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"Hungarian language","de":"Hungarian language","en":"Hungarian language"},"url":"https://en.wikipedia.org/wiki/Hungarian_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Hungarian grammar","de":"Hungarian grammar","en":"Hungarian grammar"},"url":"https://en.wikipedia.org/wiki/Hungarian_grammar","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طبيب في بودابست يسأل مريضاً في الستينيات إن كان يسمح له بالتِّغازيش، فيوافق المريض، ويتابع اللقاء بنهايات أفعال مختلفة للطرفين.","de":"In einer Budapester Praxis fragt ein Arzt einen Patienten in den Sechzigern, ob er duzen dürfe; der Patient stimmt zu, und das Gespräch läuft mit anderen Verbendungen für beide weiter.","en":"A Budapest doctor asks a patient in his sixties whether he may use te; the patient agrees, and the consultation continues with different verb endings for both of them."},"misunderstanding":{"ar":"يعتقد بعض المتعلمين أن الأمر يتعلق باختيار ضمير، والحقيقة أن اللاحقة داخل الفعل هي التي تحمل التأدب، وحذفها يغيّر الجملة كلها.","de":"Viele Lernende glauben, es gehe um die Wahl eines Pronomens. Tatsächlich trägt das Suffix im Verb die Höflichkeit, und sein Wegfall verändert den ganzen Satz.","en":"Many learners think the choice is about which pronoun to pick. In fact the suffix inside the verb carries the politeness, and removing it changes the entire sentence."},"comparison":{"ar":"حيث تكتفي لغات كثيرة بضمير أو لقب، تضع الهنغارية المسافة الاجتماعية داخل تصريف الفعل نفسه.","de":"Wo viele Sprachen mit einem Pronomen oder Titel auskommen, legt das Ungarische die soziale Distanz in die Konjugation selbst.","en":"Where many languages manage with a pronoun or a title, Hungarian builds social distance into the conjugation itself."},"expression":{"original":"Jó napot kívánok","language":"Magyar (Hungarian)","gloss":{"ar":"تحية نهارية رسمية","de":"guten Tag (förmliche Begrüßung)","en":"good day (formal greeting)"},"usage":{"ar":"تُقال عند الدخول إلى مكتب أو عيادة أو متجر، وتناسب المخاطبة الرسمية.","de":"Beim Eintreten in ein Büro, eine Praxis oder ein Geschäft, passend zur förmlichen Anrede.","en":"Said on entering an office, a clinic or a shop, matching formal address."},"transliteration":"Jo napot kivanok"}},{"id":"lng-060","version":2,"slug":"one-language-four-names-how-serbo-croatian-split-into-standards","contentType":"note","category":"languages","title":{"ar":"لغة واحدة بأربعة أسماء: انقسام الصربية الكرواتية","de":"Eine Sprache, vier Namen: der Weg zum Vierfachstandard","en":"One language, four names: how Serbo-Croatian split"},"deck":{"ar":"كيف صارت لغة يوغوسلافيا المشتركة أربعة معايير وطنية، وما يعنيه ذلك لمن يعيشونها يومياً.","de":"Wie aus dem gemeinsamen Serbokroatisch vier nationale Standards wurden und was das im Alltag bedeutet.","en":"How the shared standard of Yugoslavia became four national standards, and what that means for the people who live with it."},"teaser":{"ar":"من بلغراد إلى زغرب، يفهم الناس بعضهم بلا مترجم، لكن اسم اللغة نفسه صار موقفاً سياسياً.","de":"Von Belgrad bis Zagreb verstehen sich die Menschen ohne Dolmetscher, doch der Name der Sprache ist zur politischen Frage geworden.","en":"From Belgrade to Zagreb people understand each other without interpreters, yet the name of the language has become a political statement."},"readingMinutes":1,"sections":{"ar":[{"heading":"معيار واحد صار أربعة","paragraphs":["كانت الصربية الكرواتية المعيار المشترك في يوغوسلافيا، ومنذ التسعينيات صارت كرواتيا وصربيا والبوسنة والجبل الأسود تُنمّي كلٌّ منها معياراً وطنياً خاصاً بها.","تختلف المعايير في المفردات وفي بعض الخيارات النحوية: الصربية تفضّل sta للسؤال عن «ماذا»، والكرواتية sto، والبوسنية تستخدم الاثنين.","يختلف النطق أيضاً: إيكافية (mleko، حليب) في صربيا، وإييكافية (mlijeko) في كرواتيا والبوسنة والجبل الأسود."]},{"heading":"الكتابة والسياسة","paragraphs":["الكتابة نفسها سياسية وعملية في آن: السيريلية تغلب في صربيا، واللاتينية في كرواتيا، والاثنتان مستخدمتان في البوسنة.","أكثر المتحدثين يفهمون بعضهم دون جهد، ولهذا يصف اللغويون هذا الانقسام بأنه توحيد معياري متعدد المراكز لا أربع لغات منفصلة.","يختلف الأمر بين الأجيال والمناطق أكثر مما توحي به فروق المعايير، فشاب من سراييفو قد يستخدم أشكالاً لا ترد في أي قاموس مدرسي."]}],"de":[{"heading":"Aus einem Standard wurden vier","paragraphs":["Serbokroatisch war der gemeinsame Standard Jugoslawiens; seit den 1990er Jahren pflegen Kroatien, Serbien, Bosnien und Montenegro je einen eigenen nationalen Standard.","Die Standards unterscheiden sich im Wortschatz und in einzelnen grammatischen Entscheidungen: Serbisch bevorzugt sta für „was“, Kroatisch sto, Bosnisch verwendet beides.","Auch die Aussprache differiert: Ekavisch (mleko, Milch) in Serbien, Ijekavisch (mlijeko) in Kroatien, Bosnien und Montenegro."]},{"heading":"Schrift und Politik","paragraphs":["Die Schrift ist ebenso politisch wie praktisch: Kyrillisch dominiert in Serbien, Latein in Kroatien, in Bosnien sind beide üblich.","Die meisten Sprecher verstehen einander mühelos, weshalb die Linguistik hier von plurizentrischer Standardisierung spricht und nicht von vier getrennten Sprachen.","Regional und zwischen den Generationen variiert der Gebrauch stärker als es die Standardunterschiede vermuten lassen; ein junger Mensch in Sarajevo gebraucht Formen, die in keinem Schulwörterbuch stehen."]}],"en":[{"heading":"One standard becomes four","paragraphs":["Serbo-Croatian was the common standard of Yugoslavia, and since the 1990s Croatia, Serbia, Bosnia and Montenegro have each cultivated a national standard.","The standards differ in vocabulary and in a few grammatical choices: Serbian prefers sta for what, Croatian sto, and Bosnian uses both.","Pronunciation differs too: ekavian (mleko, milk) in Serbia and ijekavian (mlijeko) in Croatia, Bosnia and Montenegro."]},{"heading":"Script as politics","paragraphs":["Scripts are political as well as practical: Cyrillic dominates in Serbia, Latin in Croatia, and both are used in Bosnia.","Most speakers understand each other without effort, which makes the division a case of what linguists call pluricentric standardisation rather than four separate languages.","Regional and generational variation runs deeper than the standard differences suggest; a young speaker in Sarajevo may use forms no school dictionary lists."]}]},"context":{"countries":["RS","HR","BA","ME"],"region":"Serbia, Croatia, Bosnia and Herzegovina, Montenegro","continent":"europe","languages":["sr","hr","bs"],"period":"contemporary"},"tags":["languages","Serbia, Croatia, Bosnia and Herzegovina, Montenegro"],"sources":[{"organization":"Wikipedia","title":{"ar":"Serbo-Croatian","de":"Serbo-Croatian","en":"Serbo-Croatian"},"url":"https://en.wikipedia.org/wiki/Serbo-Croatian","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Pluricentric language","de":"Pluricentric language","en":"Pluricentric language"},"url":"https://en.wikipedia.org/wiki/Pluricentric_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"صحفي من بلغراد وصحفية من زغرب يتقابلان بلا مترجم، ثم يتجادلان عشر دقائق حول ما إذا كانت كلمة «محطة القطار» صربية أم كرواتية.","de":"Ein Journalist aus Belgrad und eine Journalistin aus Zagreb interviewen sich ohne Dolmetscher und streiten danach zehn Minuten darüber, ob das Wort für Bahnhof serbisch oder kroatisch sei.","en":"A Belgrade journalist and a Zagreb journalist interview each other without interpreters, then argue for ten minutes about whether the word for train station is a Serbian or Croatian form."},"misunderstanding":{"ar":"الاعتقاد الشائع أن هذه لغات مختلفة لأن لها أسماء مختلفة، بينما الأسماء تعبّر عن ولاءات وطنية أكثر مما تعبّر عن عوائق فهم.","de":"Viele halten es für vier Sprachen, weil es vier Namen gibt; die Namen drücken jedoch eher nationale Zugehörigkeit aus als Verständigungsprobleme.","en":"The common assumption is that four names mean four separate languages, when the names signal national allegiance more than any barrier to understanding."},"comparison":{"ar":"كما لو أن النمساويين والسويسريين أصرّوا على تسمية الألمانية بأسماء مختلفة، مع قاموس ومنهج مدرسي لكل اسم.","de":"Ähnlich, als würden Österreicher und Schweizer darauf bestehen, ihr Deutsch jeweils anders zu nennen, mit eigenem Wörterbuch und Lehrplan.","en":"It is as if Austrians and Swiss Germans insisted on separate names for their German, each with its own dictionary and school curriculum."},"expression":{"original":"Šta ima?","language":"Srpskohrvatski (Serbo-Croatian)","gloss":{"ar":"ما الأخبار؟","de":"Was gibt's?","en":"What's up?"},"usage":{"ar":"تحية غير رسمية بين الأصدقاء، تُستخدم في صربيا والبوسنة والجبل الأسود، وقد تبدو غريبة في سياق كرواتي رسمي.","de":"Lockere Begrüßung unter Freunden, verbreitet in Serbien, Bosnien und Montenegro; im formellen kroatischen Kontext eher ungewöhnlich.","en":"An informal greeting among friends, common in Serbia, Bosnia and Montenegro; it sounds out of place in formal Croatian settings."},"transliteration":"Sta ima?"}},{"id":"lng-061","version":2,"slug":"surzhyk-the-ukrainian-russian-mix-that-has-no-official-name-on-a-form","contentType":"language","category":"languages","title":{"ar":"سورژيك: لغة الشارع بلا خانة في الاستمارة","de":"Surzhyk: der Mischklang ohne Feld im Formular","en":"Surzhyk: the mixed speech with no box on the form"},"deck":{"ar":"خليط أوكراني-روسي يتحدثه الملايين في وسط أوكرانيا وشرقها وجنوبها، وتغيّرت نظرة أهله إليه بعد 2022.","de":"Ein ukrainisch-russisches Gemisch, das Millionen in der Zentral-, Ost- und Südukraine sprechen, und dessen Ansehen sich nach 2022 verschoben hat.","en":"A Ukrainian-Russian blend spoken by millions across central, eastern and southern Ukraine, whose reputation has shifted sharply since 2022."},"teaser":{"ar":"وُلد من الهجرة إلى المدن والتسييس السوفييتي، واليوم صار علامة على جيل بعينه لا خياراً افتراضياً.","de":"Entstanden durch Landflucht und Sowjetisierung, gilt es heute als Merkmal einer bestimmten Generation statt als Normalfall.","en":"Born of migration to cities and Soviet-era language policy, it now marks a particular generation rather than serving as the default."},"readingMinutes":1,"sections":{"ar":[{"heading":"كيف يُصنع الكلام المخلوط","paragraphs":["سورژيك هو الكلام المخلوط بين الأوكرانية والروسية الشائع في وسط أوكرانيا وشرقها، بقواعد أوكرانية ومفردات روسية أو العكس.","كانت الكلمة تعني أصلاً طحيناً مخلوطاً من حبوب مختلفة، وما زالت تحمل شحنة ازدراء يتنازع عليها المتحدثون أنفسهم.","نشأ الخليط من التحضّر والتسييس الروسي في العهد السوفييتي، حين انتقل القرويون إلى مدن ناطقة بالروسية ونشأ أطفالهم بين اللغتين."]},{"heading":"جيل يتغيّر وخريطة تتبدّل","paragraphs":["ليس سورژيك تنويعاً واحداً: الخليط يختلف من كييف إلى خاركيف إلى أوديسا، ونسبه تتبدّل بحسب جيل المتحدث.","منذ 2014 وخاصة 2022 انتقل كثيرون عن قصد نحو الأوكرانية، فصار سورژيك علامة على جيل معيّن لا خياراً افتراضياً.","يتباين الموقف منه بين المدارس، ولا تلتقطه فئات الإحصاء، وقد تغيّرت المواقف بحدة بعد الغزو الواسع مع تفاوت إقليمي واضح."]}],"de":[{"heading":"Wie gemischte Rede entsteht","paragraphs":["Surzhyk ist die gemischte ukrainisch-russische Rede in der Zentral- und Ostukraine, mit ukrainischer Grammatik und russischem Wortschatz oder umgekehrt.","Ursprünglich bezeichnete das Wort Mehl aus verschiedenen Getreidesorten und trägt bis heute einen abwertenden Beiklang, den Sprecher bestreiten.","Entstanden ist es durch Urbanisierung und sowjetische Russifizierung, als Dorfbewohner in russischsprachige Städte zogen und Kinder zwischen beiden Sprachen aufwuchsen."]},{"heading":"Eine Generation, viele Schattierungen","paragraphs":["Surzhyk ist keine einheitliche Variante: Die Mischung unterscheidet sich von Kyjiw über Charkiw bis Odesa, und die Anteile ändern sich mit der Generation.","Seit 2014 und besonders 2022 wechseln viele bewusst zum Ukrainischen; Surzhyk wurde zum Kennzeichen einer Generation statt zum Standard.","Die Haltung dazu schwankt je nach Schule, und Volkszählungskategorien erfassen es nicht; seit dem Großangriff haben sich die Einstellungen stark gewandelt, mit deutlichen regionalen Unterschieden."]}],"en":[{"heading":"How mixed speech is made","paragraphs":["Surzhyk is the mixed Ukrainian-Russian speech common in central and eastern Ukraine, with Ukrainian grammar and Russian vocabulary, or the reverse.","The word originally meant flour mixed from different grains and carries a pejorative charge that speakers dispute.","It arose through urbanisation and Soviet-era Russification, when villagers moved to Russian-speaking cities and children grew up between the two languages."]},{"heading":"One generation, many shades","paragraphs":["It is not a single variety: the mix differs from Kyiv to Kharkiv to Odesa, and the proportions change with the speaker's generation.","Since 2014 and especially 2022, many speakers have deliberately shifted towards Ukrainian, and surzhyk has become a marker of a particular generation rather than a default.","Surzhyk is stigmatised in some schools and celebrated in others, and census categories do not capture it; attitudes have changed sharply since the full-scale invasion, with strong regional variation."]}]},"context":{"countries":["UA"],"region":"Central, eastern and southern Ukraine","continent":"europe","languages":["uk","ru"],"period":"contemporary"},"tags":["languages","Central, eastern and southern Ukraine"],"sources":[{"organization":"Wikipedia","title":{"ar":"Surzhyk","de":"Surzhyk","en":"Surzhyk"},"url":"https://en.wikipedia.org/wiki/Surzhyk","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Ukrainian language","de":"Ukrainian language","en":"Ukrainian language"},"url":"https://en.wikipedia.org/wiki/Ukrainian_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"بائعة في سوق كييف تنتقل من الأوكرانية إلى الروسية لذكر السعر ثم تعود إلى سورژيك لتروي طرفة، وزبونة من لفيف تفهم كل شيء وتلحظ كل تحوّل.","de":"Eine Marktfrau in Kyjiw wechselt für den Preis ins Russische und für einen Witz zurück ins Surzhyk, und eine Kundin aus Lwiw versteht alles und bemerkt jeden Wechsel.","en":"A Kyiv market seller switches from Ukrainian to Russian for a price and back to surzhyk for a joke, and a customer from Lviv understands everything while noticing each shift."},"misunderstanding":{"ar":"يظن كثيرون أن سورژيك مجرد أوكرانية رديئة أو روسية مشوّهة، لكنه في الواقع كلام يومي منظّم بقواعده الخاصة.","de":"Viele halten Surzhyk für schlechtes Ukrainisch oder verunstaltetes Russisch, dabei ist es eine geregelte Alltagssprache mit eigenen Mustern.","en":"Many assume surzhyk is simply bad Ukrainian or mangled Russian, when it is a rule-governed everyday speech with its own patterns."},"comparison":{"ar":"حيث تختار المؤسسات لغة واحدة رسمية، يبقى سورژيك في البيت والسوق والحافلة، أقرب إلى عادة عائلية منها إلى قرار سياسي.","de":"Wo Institutionen eine Amtssprache wählen, bleibt Surzhyk in Küche, Markt und Bus – eher Familiengewohnheit als politische Entscheidung.","en":"Where institutions pick one official language, surzhyk stays in kitchens, markets and buses, closer to a family habit than a political decision."},"expression":{"original":"Добрий день","language":"Українська (Ukrainian)","gloss":{"ar":"نهارك سعيد","de":"guten Tag","en":"good day"},"usage":{"ar":"تحية نهارية شائعة تُقال عند الدخول إلى متجر أو مكتب، ويجيب عليها الناس بسورژيك أو بأوكرانية فصيحة.","de":"Geläufiger Tagesgruß beim Betreten eines Ladens oder Büros, auf den mancher auf Surzhyk oder in gepflegtem Ukrainisch antwortet.","en":"A common daytime greeting on entering a shop or office, answered by some in surzhyk and by others in careful Ukrainian."},"transliteration":"dobryi den"}},{"id":"lng-062","version":2,"slug":"gruezi-the-swiss-greeting-that-marks-the-border-before-the-border-does","contentType":"scene","category":"communication","title":{"ar":"«غرويتسي»: تحية سويسرية ترسم الحدود قبل الحدود","de":"Grüezi: der Gruss, der die Grenze früher zieht","en":"Grüezi: the Swiss greeting that draws the border first"},"deck":{"ar":"في سويسرا الألمانية يبدأ التعامل بكلمة واحدة تكشف أين أنت ومن حولك، بينما تتغير التحية فوراً عند عبور الحدود اللغوية.","de":"In der Deutschschweiz entscheidet ein einziges Wort, wo man steht und wer um einen herum ist – bis die Sprachgrenze alles umdreht.","en":"In German-speaking Switzerland one word tells you where you are and who is around you – until the language border flips it in a step."},"teaser":{"ar":"تحية واحدة تفصل بين عالمين لغويين في سويسرا، وتتبدّل بين مدينة وأخرى، وبين جيل وآخر، من دون أن يتحرك أحد.","de":"Ein Gruss trennt in der Schweiz zwei Sprachwelten, wechselt von Stadt zu Stadt und von Generation zu Generation, ohne dass sich jemand bewegt.","en":"A single greeting separates two language worlds in Switzerland, shifting from town to town and between generations without anyone moving."},"readingMinutes":1,"sections":{"ar":[{"heading":"كلمة واحدة تفتح الباب","paragraphs":["«غرويتسي» هي التحية المعتادة في سويسرا الألمانية، تُقال للغرباء وفي المتاجر، وتُجمع بصيغة «غرويتسي ميتناند» أي تحية للجميع. أصلها اختصار لعبارة دينية تعني «ليُحيّكم الله»، وهي نادرة في ألمانيا حيث يسود «هالو» أو «غوتن تاغ».","يعيش السويسري الألماني بلغتين في يومه: dialect محلي للكلام ولغة معيارية للكتابة، فيقرأ الأخبار بلغة ويحيّي الخبّاز بأخرى.","تختلف عادات التحية بين الكانتونات وبين المدينة والقرية، ويستعمل الشباب «هالو» أكثر، والسويسرية الألمانية عائلة لهجات لا معيار منطوق واحد."]},{"heading":"حين تنقلب التحية عند الحدود","paragraphs":["الحدود اللغوية حادة: عبورك إلى سويسرا الفرنسية يستبدل «غرويتسي» بـ«بونجور»، ومدن ثنائية اللغة مثل بيال تتبدّل فيها التحية باستمرار.","تتباين اللهجات حتى يصعب التفاهم، فقد ينتقل متحدث من بازل وآخر من برن إلى الألمانية المعيارية كي يفهم أحدهما الآخر."]}],"de":[{"heading":"Ein Wort, das die Tür öffnet","paragraphs":["Grüezi, für Gruppen oft Grüezi mitenand, ist der übliche Schweizer Gruss gegenüber Fremden und im Laden. Es ist die Kurzform von «Gott gruezi», im Deutschen selten, wo Hallo oder Guten Tag vorherrschen.","Wer hier lebt, spricht Mundart und schreibt Standarddeutsch: dieselbe Person liest die Nachrichten in der einen und grüsst den Bäcker in der anderen Sprache.","Grussgewohnheiten unterscheiden sich je nach Kanton und zwischen Stadt und Dorf; jüngere Schweizer sagen häufiger Hallo, und Schweizerdeutsch ist eine Familie von Dialekten, kein gesprochener Standard."]},{"heading":"Wo der Gruss umschlägt","paragraphs":["Die Sprachgrenze ist scharf: In der Romandie ersetzt Bonjour das Grüezi, und zweisprachige Städte wie Biel wechseln ständig.","Die Dialekte liegen so weit auseinander, dass ein Basler und ein Berner auf Standarddeutsch wechseln, um sich zu verstehen."]}],"en":[{"heading":"One word that opens the door","paragraphs":["Grüezi, often Grüezi mitenand for a group, is the standard Swiss German greeting used with strangers and in shops. It shortens Gott gruezi, may God greet you, and is rare in Germany, where Hallo or Guten Tag dominate.","People here speak dialect and write Standard German: the same person reads the news in one language and greets the baker in another.","Greeting habits vary between cantons and between city and village; younger Swiss use Hallo more, and Swiss German is a family of dialects rather than a single spoken standard."]},{"heading":"Where the greeting flips","paragraphs":["The language border is sharp: crossing into French-speaking Switzerland replaces Grüezi with Bonjour, and bilingual cities such as Biel switch constantly.","Dialects differ enough that a Basel speaker and a Bern speaker may switch to Standard German to be understood."]}]},"context":{"countries":["CH"],"region":"German-speaking Switzerland (Zurich, Bern, Basel)","continent":"europe","languages":["de","gsw","fr","it"],"period":"contemporary"},"tags":["communication","German-speaking Switzerland (Zurich, Bern, Basel)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Swiss German","de":"Swiss German","en":"Swiss German"},"url":"https://en.wikipedia.org/wiki/Swiss_German","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Languages of Switzerland","de":"Languages of Switzerland","en":"Languages of Switzerland"},"url":"https://en.wikipedia.org/wiki/Languages_of_Switzerland","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"متسلّقة من زيوريخ تحيّي كل عابر بـ«غرويتسي»، وعندما تبلغ أوبرلاند البرنية تردّ على «غرويتسي» بمثلها وإن صار لهجتها عصياً على التحديد لدى السكان.","de":"Eine Wanderin aus Zürich grüsst jeden Passanten mit Grüezi, und im Berner Oberland antwortet sie auf Grüezi mit Grüezi, obwohl ihr eigener Dialekt für Einheimische kaum noch einzuordnen ist.","en":"A Zurich hiker greets every passer-by with a Grüezi, and by the time she reaches the Bernese Oberland she answers Grüezi with Grüezi even though locals can barely place her own dialect."},"misunderstanding":{"ar":"يظنّ زائر ألمانيا أن «غرويتسي» مجرد «هالو» مهذّبة، لكنها تحية لها ثقلها المحلي، وقد تبدو غريبة أو مصطنعة إن استعملها غير السويسري في سياق خاطئ.","de":"Deutsche Besucher halten Grüezi für ein höfliches Hallo; tatsächlich hat der Gruss lokales Gewicht und wirkt fremd oder aufgesetzt, wenn er im falschen Moment benutzt wird.","en":"Visitors from Germany hear Grüezi as a polite Hallo; in fact it carries local weight and can sound foreign or put on when used at the wrong moment."},"comparison":{"ar":"في ألمانيا يسود «هالو» و«غوتن تاغ»، وفي سويسرا الفرنسية «بونجور»؛ أما «غرويتسي» فتبقى علامة على الجهة الألمانية من البلاد.","de":"In Deutschland dominieren Hallo und Guten Tag, in der Westschweiz Bonjour; Grüezi bleibt das Erkennungszeichen der Deutschschweiz.","en":"Germany favours Hallo and Guten Tag, French-speaking Switzerland says Bonjour; Grüezi stays the marker of the German-speaking side."},"expression":{"original":"Grüezi mitenand","language":"Schwyzerdütsch (Swiss German)","gloss":{"ar":"تحية للجميع","de":"Hallo zusammen","en":"hello everyone"},"usage":{"ar":"تُقال عند دخول مكان فيه عدة أشخاص، كمتجر أو قاعة اجتماعات.","de":"Beim Eintreten in einen Raum mit mehreren Personen, etwa im Laden oder in einer Sitzung.","en":"Said when entering a place with several people, such as a shop or a meeting room."},"transliteration":"Gruezi mitenand"}},{"id":"lng-063","version":2,"slug":"besa-the-albanian-promise-that-outranks-a-written-contract","contentType":"note","category":"languages","title":{"ar":"البيسا: وعد يتجاوز العقد المكتوب","de":"Besa: Das Ehrenwort als stärkste Währung","en":"Besa: the Albanian promise stronger than paper"},"deck":{"ar":"في شمال ألبانيا وكوسوفو، تُبنى الثقة على كلمة الشرف لا على الأوراق، وتبقى العائلة كلها ضامنة لها.","de":"In Nordalbanien und im Kosovo zählt das gegebene Wort mehr als Papier, und eine ganze Familie haftet dafür mit.","en":"In northern Albania and Kosovo, a spoken word carries weight that contracts rarely match, and a whole family stands behind it."},"teaser":{"ar":"مفهوم البيسا يجعل الكلمة الم pledged أساس التعامل اليومي، من الأمانة في المال إلى حماية الضيف، ويختلف تطبيقه بين الأجيال والمدن.","de":"Besa verbindet Alltag, Gastfreundschaft und Sicherheit – ein mündliches Versprechen, das je nach Generation und Region unterschiedlich streng gelebt wird.","en":"Besa shapes trust, hospitality and daily dealings, and how strictly it is lived varies between generations, cities and the diaspora."},"readingMinutes":1,"sections":{"ar":[{"heading":"الكلمة التي تحمي الإنسان","paragraphs":["البيسا تعني كلمة الشرف والإيمان الم pledged، ومن يحفظها يُؤتمن على المال والسلامة والأسرار. وقد دخل المفهوم في قانون الكانونون العرفي الذي ينظّم الضيافة والثأر وحماية الضيف.","خلال الحرب العالمية الثانية استُدعيت البيسا لحماية اللاجئين اليهود في ألبانيا، وصارت القصة جزءاً من الذاكرة الوطنية والاحتفالات العامة.","البيسا قد تُلزم عائلة كاملة لا فرداً واحداً، ونقضها يضرّ بمكانة العائلة لا بمكانة المتكلم وحده. وتختلف اليوم بين الأجيال: كبار السن يعدّونها قاعدة، والشباب في المدن والمهجر يصفونها غالباً كقيمة عائلية."]},{"heading":"من الأخلاق إلى القواعد اللغوية","paragraphs":["الألبانية فيها فعل beboj وعبارات مثل e kam besa أي «أعطيت كلمتي»، فالمفهوم نحويّ وأخلاقي في الوقت نفسه.","البيسا مثال مستمد من العرف، أما ألبانيا وكوسوفو الحديثتان فتعتمدان على المحاكم والعقود المكتوبة في تعاملاتهما اليومية.","ومع ذلك يبقى أثرها في الحياة اليومية: صاحب دكان في كوسوفو يسلّم بضاعة لشخص غريب بالأجل لأنه أعطاه بيسا، وعند وصول المال بعد شهر لا إيصال ولا أحد انتظره."]}],"de":[{"heading":"Ein Wort, das Schutz gibt","paragraphs":["Besa bedeutet Ehrenwort und zugesagter Glaube; wer sie hält, dem vertraut man Geld, Sicherheit und Geheimnisse an. Der Begriff ist im Gewohnheitsrecht Kanun verankert, das Gastfreundschaft, Blutrache und den Schutz von Gästen regelt.","Im Zweiten Weltkrieg wurde Besa angerufen, um jüdische Flüchtlinge in Albanien zu schützen; die Geschichte gehört heute zum nationalen Gedächtnis und wird öffentlich gewürdigt.","Besa kann eine ganze Familie binden, nicht nur eine Person, und ein Bruch schadet dem Ansehen der Familie statt nur dem des Sprechers. Regional und generationell wird sie unterschiedlich gelebt: Ältere behandeln sie als Regel, Jüngere in Städten und der Diaspora oft als Familienwert."]},{"heading":"Vom Ethos zur Grammatik","paragraphs":["Albanisch kennt das Verb beboj und Wendungen wie e kam besa, „ich habe es versprochen“ – das Konzept ist also grammatisch wie moralisch verankert.","Besa ist ein Ideal aus dem Gewohnheitsrecht; das moderne Albanien und der Kosovo stützen sich im Alltag auf Gerichte und Verträge.","Trotzdem wirkt sie nach: Ein Ladenbesitzer im Kosovo gibt einem Fremden Waren auf Kredit, weil dieser ihm Besa gab; einen Monat später kommt das Geld, ohne Quittung, und niemand hatte eine erwartet."]}],"en":[{"heading":"A word that shelters people","paragraphs":["Besa means word of honour and pledged faith, and a person who keeps besa is trusted with money, safety and secrets. The concept is embedded in the Kanun customary code, which regulates hospitality, blood feuds and the protection of guests.","During the Second World War, besa was invoked to protect Jewish refugees in Albania, and the story is part of national memory and public commemoration.","Besa can bind a whole family, not just an individual, and breaking it damages the family's standing rather than the speaker's alone. It is lived differently across regions and generations: older villagers treat it as a rule, while younger urban and diaspora Albanians often call it a family value."]},{"heading":"From ethic to grammar","paragraphs":["Albanian has a verb, beboj, and phrases such as e kam besa (I have pledged it), which show that the concept is grammatical as well as moral.","Besa is an ideal drawn from customary law, and modern Albania and Kosovo rely on courts and contracts.","Still it lingers in ordinary life: a Kosovo shopkeeper lets a stranger take goods on credit because the man gave his besa; when the payment arrives a month later there is no receipt and nobody expected one."]}]},"context":{"countries":["AL","XK"],"region":"Northern Albania, Kosovo and North Macedonia","continent":"europe","languages":["sq","sr"],"period":"contemporary"},"tags":["languages","Northern Albania, Kosovo and North Macedonia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Besa (Albanian culture)","de":"Besa (Albanian culture)","en":"Besa (Albanian culture)"},"url":"https://en.wikipedia.org/wiki/Besa_(Albanian_culture)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Albanian language","de":"Albanian language","en":"Albanian language"},"url":"https://en.wikipedia.org/wiki/Albanian_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"صاحب دكان في كوسوفو يسلّم بضاعة لشخص غريب بالأجل لأنه أعطاه بيسا؛ وعند وصول المبلغ بعد شهر لا إيصال ولا أحد كان ينتظره.","de":"Ein Ladenbesitzer im Kosovo gibt einem Fremden Waren auf Kredit, weil dieser ihm Besa gab; einen Monat später kommt die Zahlung, ohne Quittung, und niemand hatte eine erwartet.","en":"A Kosovo shopkeeper lets a stranger take goods on credit because the man gave his besa; when the payment arrives a month later there is no receipt and nobody expected one."},"misunderstanding":{"ar":"يظن كثيرون أن البيسا مجرد وعد شفهي عابر، لكنها في الأصل التزام عائلي ثقيل الوزن.","de":"Viele halten Besa für ein flüchtiges mündliches Versprechen, doch sie ist eine gewichtige familiäre Verpflichtung.","en":"Many outsiders assume besa is a casual verbal promise, when it is in fact a heavy family obligation."},"comparison":{"ar":"تشبه البيسا العقد الشفهي في التجارة، لكنها تختلف بأن ضمانتها اجتماعية وعائلية لا قانونية.","de":"Besa ähnelt einem mündlichen Handelsvertrag, unterscheidet sich aber durch ihre soziale und familiäre statt rechtliche Absicherung.","en":"Besa resembles a spoken trade agreement, but its guarantee is social and familial rather than legal."},"expression":{"original":"Besa","language":"Shqip (Albanian)","gloss":{"ar":"كلمة شرف / إيمان م pledged","de":"Ehrenwort / zugesagter Glaube","en":"word of honour / pledged faith"},"usage":{"ar":"تُستخدم للتعبير عن التزام قطعته على نفسك، ويُقال e kam besa لمن أعطى كلمته.","de":"Man sagt e kam besa, um zu betonen, dass man sein Wort gegeben hat.","en":"Used to stress that you have given your word, as in e kam besa."},"transliteration":"besa"}},{"id":"lng-064","version":2,"slug":"romani-a-language-with-no-home-state-and-many-names-for-itself","contentType":"note","category":"languages","title":{"ar":"الرومانية: لغة بلا دولة وعدة أسماء","de":"Romani: Sprache ohne Staat, viele Namen","en":"Romani: a language with no home state"},"deck":{"ar":"اللغة الرومانية (rom) هي لغة هندوآرية منتشرة في أوروبا، لكن تنوع لهجاتها يجعل بعضها غير مفهوم للآخرين.","de":"Romani (rom) ist eine indoarische Sprache, die über Europa verbreitet ist, doch ihre Varietäten unterscheiden sich so stark, dass manche nicht gegenseitig verständlich sind.","en":"Romani (rom) is an Indo-Aryan language spoken across Europe, but its varieties differ enough that some are not mutually intelligible."},"teaser":{"ar":"يتحدث الرومانية مجتمعات Roma وSinti وKale وManouche، وتتعدد أسماؤها بتعدد الأماكن، لكنها تظل لغة حية في المنزل.","de":"Roma, Sinti, Kale und Manouche nennen sich je nach Region verschieden; die Sprache folgt der Gemeinschaft, nicht einem Land.","en":"Speakers call themselves Roma, Sinti, Kale or Manouche by region; the language follows the community, not a country."},"readingMinutes":1,"sections":{"ar":[{"heading":"تنوع اللهجات وغياب المعيار","paragraphs":["الرومانية لغة هندوآرية تنتشر في أوروبا والبلقان، وتختلف لهجاتها لدرجة أن بعضها غير مفهوم تبادليًا. لا توجد دولة رسمية للغة، والتوحيد القياسي محل خلاف لأن تقنين لهجة واحدة سيميز مجتمعًا على آخر.","كتبت الرومانية بالأبجدية اللاتينية والسيريلية وغيرها، لكن الأرثوغرافيا المشتركة تظل مشروعًا سياسيًا لا واقعًا. يختلف الاستخدام بين الأجيال والمناطق، فبعض المجتمعات تتبنى كتابة محلية بينما يتمسك آخرون بالتقاليد الشفوية."]},{"heading":"حياة متعددة اللغات","paragraphs":["كثير من الروم متعددو اللغات، يستخدمون لغة الأغلبية في المدرسة والرومانية في البيت، ما يعرض بعض اللهجات للخطر بسبب ضغوط الاندماج. يطلق المتحدثون على أنفسهم Roma أو Sinti أو Kale أو Manouche حسب المنطقة، ويتبع اسم اللغة المجتمع لا الدولة."]}],"de":[{"heading":"Vielfalt der Varietäten","paragraphs":["Romani ist eine indoarische Sprache, die in Europa und auf dem Balkan gesprochen wird. Die Varietäten unterscheiden sich erheblich, einige sind nicht gegenseitig verständlich. Es gibt keinen offiziellen Staat für die Sprache, und Standardisierung ist umstritten, weil die Kodifizierung einer Varietät eine Gemeinschaft privilegieren würde.","Romani wurde in lateinischer, kyrillischer und anderen Schriften geschrieben; eine gemeinsame Orthographie bleibt ein politisches Projekt. Die Nutzung variiert regional und generationell: Manche Gemeinschaften übernehmen lokale Schreibweisen, andere bleiben bei mündlicher Tradition."]},{"heading":"Leben in Mehrsprachigkeit","paragraphs":["Viele Roma sind mehrsprachig und verwenden die Mehrheitssprache in der Schule und Romani zu Hause, wodurch manche Varietäten durch Assimilationsdruck gefährdet sind. Sprecher nennen sich Roma, Sinti, Kale oder Manouche je nach Region, und der Sprachname folgt der Gemeinschaft, nicht einem Land."]}],"en":[{"heading":"Varieties and the standardisation debate","paragraphs":["Romani is an Indo-Aryan language spoken across Europe and the Balkans. Its varieties differ enough that some are not mutually intelligible. The language has no official state, and standardisation is contested because codifying one variety would privilege one community.","Romani has been written in Latin, Cyrillic and other scripts, and a common orthography remains a political project rather than a fact. Use varies by region and generation: some communities adopt local spellings, while others keep oral tradition."]},{"heading":"Living multilingually","paragraphs":["Many Roma are multilingual, using the majority language at school and Romani at home, and some varieties are now endangered by pressure to assimilate. Speakers call themselves Roma, Sinti, Kale or Manouche depending on region, and the language name follows the community rather than a country."]}]},"context":{"countries":[],"region":"Europe and the Balkans, with diaspora in the Americas","community":"Roma communities","continent":"europe","languages":["rom"],"period":"contemporary"},"tags":["languages","Europe and the Balkans, with diaspora in the Americas"],"sources":[{"organization":"Wikipedia","title":{"ar":"Romani language","de":"Romani language","en":"Romani language"},"url":"https://en.wikipedia.org/wiki/Romani_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Romani people","de":"Romani people","en":"Romani people"},"url":"https://en.wikipedia.org/wiki/Romani_people","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عائلة رومانية في ترانسيلفانيا تتحدث لهجة معينة في البيت، وتتحول إلى الرومانية في العيادة وإلى الهنغارية في السوق، ويجيب الأطفال جدتهم بالرومانية وهم يلعبون بالرومانية.","de":"Eine Roma-Familie in Transsylvanien spricht zu Hause eine Varietät, wechselt in der Klinik zu Rumänisch und auf dem Markt zu Ungarisch; die Kinder antworten der Großmutter auf Romani und spielen auf Rumänisch.","en":"A Romani family in Transylvania speaks one variety at home, switches to Romanian at the clinic and to Hungarian at the market, and the children answer their grandmother in Romani while playing in Romanian."},"misunderstanding":{"ar":"الاعتقاد بأن الرومانية لغة واحدة موحدة أو أن الروم مجتمع واحد؛ في الواقع، التقديرات تتفاوت، وبعض الجماعات تتجنب التصنيف بسبب التمييز.","de":"Die Annahme, Romani sei eine einheitliche Sprache oder Roma eine einzige Gemeinschaft; tatsächlich variieren Schätzungen der Sprecherzahl stark, und manche Gruppen vermeiden die Selbstbezeichnung wegen Diskriminierung.","en":"The belief that Romani is a single standard language or that Roma are one community; in fact, estimates of speakers vary widely, and some groups avoid identifying as Roma because of discrimination."},"comparison":{"ar":"مثل اللغات المهاجرة الأخرى، تعيش الرومانية في فضاء متعدد اللغات، لكن غياب دولة مرجعية يجعل التوحيد القياسي أكثر تعقيدًا.","de":"Wie andere Migrationssprachen lebt Romani in einem mehrsprachigen Raum, doch das Fehlen eines Referenzstaates macht Standardisierung komplizierter.","en":"Like other migrant languages, Romani lives in a multilingual space, but the absence of a reference state makes standardisation more complex."},"expression":{"original":"Sar san?","language":"Romani (Romanes)","gloss":{"ar":"كيف حالك؟","de":"Wie geht es dir?","en":"how are you?"},"usage":{"ar":"تحية شائعة عند اللقاء، تُستخدم بين المتحدثين بالرومانية في سياقات غير رسمية.","de":"Häufige Begrüßung unter Romani-Sprechern in informellen Kontexten.","en":"A common greeting among Romani speakers in informal contexts."},"transliteration":"sar san?"}},{"id":"lng-065","version":2,"slug":"how-are-you-the-american-greeting-that-is-really-a-handshake","contentType":"scene","category":"communication","title":{"ar":"كيف حالك: تحية أمريكية هي في الحقيقة مصافحة","de":"How are you: Der amerikanische Gruß als Handschlag","en":"How Are You: The American Greeting That's Really a Handshake"},"deck":{"ar":"عبارة 'كيف حالك؟' في الولايات المتحدة ليست سؤالاً طبياً، بل طقس اجتماعي سريع لتبادل الاعتراف.","de":"In den USA ist 'How are you?' keine medizinische Frage, sondern ein schnelles Ritual der gegenseitigen Anerkennung.","en":"In the US, 'How are you?' is not a medical question but a quick social ritual of mutual recognition."},"teaser":{"ar":"عندما يسأل أمريكي 'كيف حالك؟'، فهو لا يطلب تشخيصاً، بل يمد يده بكلمات. إليك كيف يعمل هذا الطقس.","de":"Wenn Amerikaner 'How are you?' fragen, erwarten sie keine Diagnose, sondern reichen Worte. So funktioniert das Ritual.","en":"When Americans ask 'How are you?', they don't want a diagnosis—they're extending words. Here's how the ritual works."},"readingMinutes":1,"sections":{"ar":[{"heading":"التحية كطقس اجتماعي","paragraphs":["في الولايات المتحدة، تُستخدم عبارة 'كيف حالك؟' كتحية وليست سؤالاً طبياً. الإجابة المتوقعة هي 'جيد، وأنت؟' أو صيغة قصيرة مماثلة. من يسأل في الشارع قد لا يريد إجابة حقيقية، والرد الطويل الصادق يمكن أن يكسر الطقس ويحوله إلى محادثة.","تختلف الصيغ حسب المنطقة: 'كيف تسير الأمور؟'، 'ما الأخبار؟' في نيويورك، 'هاودي' في تكساس، و'هل أنت بخير؟' في أجزاء من الجنوب. لكنها كلها تؤدي نفس الوظيفة: الاعتراف بالآخر في لمحة."]},{"heading":"الإجابة والتوقعات","paragraphs":["الإجابة 'جيد جداً' تتحفظ أكثر من 'جيد'، بينما 'بخير' قد تشير إلى أن شيئاً ما خطأ دون قوله. عمال الخدمة مدربون على السؤال والمضي قدماً، لذا يحدث التبادل غالباً أثناء سير الشخصين في اتجاهين متعاكسين."]}],"de":[{"heading":"Der Gruß als Ritual","paragraphs":["In den USA funktioniert 'How are you?' als Begrüßung, nicht als medizinische Frage. Die erwartete Antwort ist 'Good, how are you?' oder eine andere kurze Formel. Ein Fremder auf der Straße will oft keine echte Antwort, und eine lange ehrliche Antwort kann das Ritual brechen und in ein Gespräch verwandeln.","Regionale Varianten erfüllen denselben Zweck: 'How's it going?', 'What's up?' in New York, 'Howdy' in Texas und 'You all right?' in Teilen des Südens. Sie alle signalisieren Anerkennung in einem kurzen Moment."]},{"heading":"Antworten und Erwartungen","paragraphs":["Die Antwort 'pretty good' ist vorsichtiger als 'good', während 'fine' signalisieren kann, dass etwas nicht stimmt, ohne es auszusprechen. Servicekräfte sind darauf trainiert, zu fragen und weiterzugehen, sodass der Austausch oft im Gehen in entgegengesetzte Richtungen stattfindet."]}],"en":[{"heading":"The Greeting as Ritual","paragraphs":["In the US, 'How are you?' functions as a greeting rather than a medical question, and the expected answer is 'Good, how are you?' or another short formula. A stranger asking on the street may not want an answer, and a long honest reply can break the ritual by turning it into a conversation.","Regional variants do the same work: 'How's it going?', 'What's up?' in New York, 'Howdy' in Texas, and 'You all right?' in parts of the South. They all signal recognition in a brief moment."]},{"heading":"Answers and Expectations","paragraphs":["The answer 'pretty good' hedges more than 'good', while 'fine' can signal that something is wrong without saying so. Service workers are trained to ask and keep moving, so the exchange often happens while both people are walking in opposite directions."]}]},"context":{"countries":["US"],"region":"Nationwide","continent":"north-america","languages":["en"],"period":"contemporary"},"tags":["communication","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"How are you?","de":"How are you?","en":"How are you?"},"url":"https://en.wikipedia.org/wiki/How_are_you%3F","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"American English","de":"American English","en":"American English"},"url":"https://en.wikipedia.org/wiki/American_English","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يسأل نيويوركي زميله 'كيف حالك' وهو يستدير نحو المصعد، فيجيب الزميل 'جيد، شكراً' دون أن يتوقف عن السير؛ كلاهما تبادل الاعتراف، لا المعلومات.","de":"Ein New Yorker fragt einen Kollegen 'how are you', während er sich schon zum Aufzug dreht, und der Kollege antwortet 'good, thanks', ohne stehen zu bleiben; beide haben Anerkennung ausgetauscht, keine Informationen.","en":"A New Yorker asks a colleague 'how are you' while already turning towards the lift, and the colleague answers 'good, thanks' without breaking stride; both have exchanged recognition, not information."},"misunderstanding":{"ar":"قد يعتقد الزائر أن السؤال دعوة للحديث عن المشاكل، لكن الرد الطويل يمكن أن يربك الموقف لأنه يحول التحية إلى محادثة.","de":"Besucher könnten denken, die Frage sei eine Einladung, über Probleme zu sprechen, aber eine lange Antwort kann die Situation verwirren, weil sie den Gruß in ein Gespräch verwandelt.","en":"A visitor might think the question invites a discussion of problems, but a long reply can confuse the situation because it turns the greeting into a conversation."},"comparison":{"ar":"في أجزاء من الجنوب الأمريكي، قد يفتح التبادل باباً لأخبار العائلة، بينما في غرفة انتظار الطبيب يعود السؤال حرفياً.","de":"Im Süden der USA kann der Austausch tatsächlich zu Familienneuigkeiten führen, während die Frage im Wartezimmer eines Arztes wieder wörtlich gemeint ist.","en":"In the US South the exchange may genuinely open into family news, while in a doctor's waiting room the question is literal again."},"expression":{"original":"How are you?","language":"English","gloss":{"ar":"مرحباً (سؤال طقسي)","de":"Hallo (rituelle Erkundigung)","en":"hello (ritual enquiry)"},"usage":{"ar":"تحية سريعة تُتبادل عند اللقاء، والإجابة المتوقعة قصيرة وإيجابية.","de":"Ein schneller Gruß beim Treffen; die erwartete Antwort ist kurz und positiv.","en":"A quick greeting exchanged when meeting; the expected answer is short and positive."},"transliteration":"how are you"}},{"id":"lng-066","version":2,"slug":"bless-your-heart-the-southern-phrase-that-can-be-sympathy-or-the-opposite","contentType":"detail","category":"communication","title":{"ar":"عبارة تبارك قلبك في الجنوب الأميركي","de":"Bless your heart: Trost oder leise Kritik","en":"Bless your heart: sympathy or a polite verdict"},"deck":{"ar":"عبارة تبدو بركة صافية، لكنها قد تكون مواساة صادقة أو حكماً مهذباً على من لا يعرف الحكمة.","de":"Der Südausdruck klingt nach reinem Segen, kann aber ehrliches Mitgefühl oder höfliche Verurteilung bedeuten.","en":"The Southern phrase sounds like a pure blessing, yet it can offer real comfort or quietly mark someone as foolish."},"teaser":{"ar":"في الجنوب الأميركي تحمل عبارة واحدة مواساة صادقة أحياناً، وحكماً صامتاً أحياناً أخرى، من دون أن تفقد المتحدث لباقته.","de":"Im Süden der USA trägt ein einziger Satz manchmal echtes Mitgefühl und manchmal ein stilles Urteil, ohne dass jemand die guten Manieren verliert.","en":"In the Southern United States one phrase can carry genuine sympathy or a silent judgement, all while the speaker keeps perfect manners."},"readingMinutes":1,"sections":{"ar":[{"heading":"بركة صادقة في الأصل","paragraphs":["العبارة بركة حرفية، وفي الاستعمال الريفي القديم تعبير صادق عن المواساة بعد مرض أو فقد أو سوء حظ.","تقول عمة في جورجيا إن ابن أخيها اشترى قارباً لا يقدر على ثمنه، فتقول تبارك قلبه، فيفهم الجميع الحكم، ولم يُنتقد أحد بصوت عال.","تختلف العادة بين الأجيال والمناطق: بعض الشيوخ لا يقولونها إلا بصدق، بينما يلتقط الشباب في المدن النبرة الساخرة بسرعة."]},{"heading":"حكم لا يُنطق","paragraphs":["بنبرة معينة تصف العبارة صاحبها بالسذاجة أو الطيبة الزائدة، مع الحفاظ على آداب الحديث كاملة.","وكثيراً ما تختم حديثاً عن قرار سيئ اتخذه شخص غائب، فتدع المتكلم يحكم من دون أن يعلن حكماً صريحاً.","انتشرت العبارة وطنياً عبر التلفزيون والإنترنت، وصارت اليوم تُستعمل بوعي ذاتي كصورة ساخرة متداولة."]}],"de":[{"heading":"Ein Segen, wörtlich genommen","paragraphs":["Der Satz ist wörtlich ein Segen und in älterem ländlichem Gebrauch aufrichtiges Mitgefühl nach Krankheit, Trauer oder Pech.","Eine Tante in Georgia hört, ihr Neffe habe ein Boot gekauft, das er sich nicht leisten kann, und sagt bless his heart; alle am Tisch verstehen das Urteil, und niemand wurde laut kritisiert.","Der Gebrauch variiert nach Region und Generation: Manche Ältere meinen es nur ernst, jüngere Städter erkennen den ironischen Ton schnell."]},{"heading":"Ein Urteil, das nicht ausgesprochen wird","paragraphs":["Mit einem bestimmten Ton markiert der Satz jemanden als töricht oder naiv, während die Höflichkeit des Sprechers völlig intakt bleibt.","Oft beendet er ein Gespräch über die schlechte Entscheidung einer dritten Person und erlaubt ein Urteil, ohne es auszusprechen.","Durch Fernsehen und Internet verbreitete sich der Ausdruck landesweit, wo er heute meist selbstbewusst als Meme benutzt wird."]}],"en":[{"heading":"A blessing in the literal sense","paragraphs":["The phrase is literally a blessing, and in older rural usage it is sincere sympathy after illness, bereavement or bad luck.","A Georgia aunt hears that a nephew has bought a boat he cannot afford and says bless his heart; everyone at the table understands the verdict, and nobody has been criticised out loud.","Usage shifts with region and generation: some older rural speakers mean it only sincerely, while younger city dwellers catch the ironic tone quickly."]},{"heading":"A judgement left unspoken","paragraphs":["Said with a certain tone, it can mark someone as foolish or naive while keeping the speaker's manners intact.","It often closes a conversation about a third person's bad decision, letting the speaker judge without stating a judgement.","The expression spread nationally through television and the internet, where it is now usually used self-consciously as a meme."]}]},"context":{"countries":["US"],"region":"Southern United States","continent":"north-america","languages":["en"],"period":"contemporary"},"tags":["communication","Southern United States"],"sources":[{"organization":"Wikipedia","title":{"ar":"Bless your heart","de":"Bless your heart","en":"Bless your heart"},"url":"https://en.wikipedia.org/wiki/Bless_your_heart","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Southern American English","de":"Southern American English","en":"Southern American English"},"url":"https://en.wikipedia.org/wiki/Southern_American_English","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تسمع عمة في جورجيا أن ابن أخيها اشترى قارباً لا يستطيع تحمّل تكلفته، فتقول: تبارك قلبه. يفهم كل من حول الطاولة الحكم، ولم يُنتقد أحد بصوت عال.","de":"Eine Tante in Georgia hört, ihr Neffe habe ein Boot gekauft, das er sich nicht leisten kann, und sagt: bless his heart. Alle am Tisch verstehen das Urteil, und niemand wurde laut getadelt.","en":"A Georgia aunt hears that a nephew has bought a boat he cannot afford and says bless his heart; everyone at the table understands the verdict, and nobody has been criticised out loud."},"misunderstanding":{"ar":"يتوقف المعنى على النبرة والعلاقة والمنطقة، وكثير من أبناء الجنوب لا يستعملونها إلا بصدق؛ أما خارج الجنوب فتغلب القراءة الساخرة، ولهذا يسيء الوافدون فهمها.","de":"Die Bedeutung hängt von Ton, Beziehung und Region ab, und viele Südstaatler verwenden sie nur aufrichtig; außerhalb des Südens überwiegt die ironische Lesart, weshalb Zugezogene sie oft falsch verstehen.","en":"Meaning depends on tone, relationship and region, and many Southerners use it only sincerely; outside the South the ironic reading often dominates, which is why transplants misread it."},"comparison":{"ar":"في ثقافات أخرى تُقال الأحكام الصريحة أو تُترك للصمت، أما هنا فتُغلَّف في بركة، ويبقى الغموض نفسه هو ما يجعلها نافعة.","de":"Andernorts sagt man Urteile direkt oder schweigt; hier werden sie in einen Segen verpackt, und gerade diese Mehrdeutigkeit macht den Satz brauchbar.","en":"Elsewhere people state judgements outright or stay silent; here the verdict arrives wrapped in a blessing, and that ambiguity is exactly what makes it useful."},"expression":{"original":"Bless your heart","language":"English (Southern US)","gloss":{"ar":"مواساة أو حكم مهذب","de":"Mitgefühl oder höfliches Urteil","en":"sympathy or polite judgement"},"usage":{"ar":"تُقال بعد خبر سيئ أو قرار متعجل، وتُفهم بحسب النبرة مواساةً أو حكماً لطيفاً.","de":"Nach schlechten Nachrichten oder einer voreiligen Entscheidung gesagt; je nach Ton als Trost oder freundliche Kritik verstanden.","en":"Said after bad news or a hasty decision; read as comfort or gentle criticism depending on tone."},"transliteration":"bless your heart"}},{"id":"lng-067","version":2,"slug":"he-be-working-the-habitual-be-that-english-usually-lacks","contentType":"language","category":"languages","title":{"ar":"قاعدة be التي تختفي من الإنجليزية المعيارية","de":"Das kleine be, das Standardenglisch fehlt","en":"The habitual be English usually lacks"},"deck":{"ar":"في الإنجليزية الأمريكية الأفريقية، كلمة be الصغيرة تصنع فرقًا كبيرًا بين ما يحدث الآن وما يحدث دائمًا.","de":"Im African-American Vernacular English trennt eine einzige Form zwischen Gewohnheit und Augenblick.","en":"In African-American Vernacular English, one small word separates what happens now from what happens always."},"teaser":{"ar":"متحدثو الإنجليزية الأمريكية الأفريقية يميّزون بين العادة واللحظة بكلمة واحدة، وهذا التمييز ينتشر اليوم عبر الموسيقى والإنترنت.","de":"Wer he be working sagt, meint keine laufende Handlung, sondern eine Regelmäßigkeit. Diese Unterscheidung wandert heute über Musik ins Netz.","en":"He be working means he works regularly, not that he is working at this moment. The distinction is spreading through music and the internet."},"readingMinutes":1,"sections":{"ar":[{"heading":"فرق بين العادة واللحظة","paragraphs":["في الإنجليزية الأمريكية الأفريقية، عبارة he be working لا تعني أنه يعمل الآن، بل أنه يعمل بانتظام. هذه صيغة تُسمّى الجانب العادي، وهي تمييز منهجي لا نقص في الكلام.","تضيف اللهجة أيضًا been للماضي البعيد، كما في I been knew، وتسمح بحذف فعل الكينونة في جمل مثل she nice. هذه اختيارات نحوية داخل نظام كامل، لا أخطاء عابرة.","يتبدّل المتحدثون بين هذه اللهجة والإنجليزية المعيارية حسب الموقف، في المدرسة أو العمل أو البيت. وتختلف كثافة هذه السمات بحسب المنطقة والعمر والطبقة، إذ تزداد في الجنوب وفي المدن الكبرى."]},{"heading":"صوت ينتقل بين الأجيال","paragraphs":["تعود كثير من هذه السمات إلى الإنجليزية الجنوبية وإلى احتكاك مع لغات غرب أفريقيا خلال العبودية، ولللهجة تقليد سردي خاص بها.","اليوم تنتقل صيغة be العادية إلى لغة الإنترنت وإلى لهجات أخرى عبر الموسيقى، ويرصد اللغويون ذلك كاستعارة لا كخطأ.","في الصف، حين تسمع معلمة في ديترويت طالبًا يقول he be late، تفهم أنه يتأخر عادةً، فتسأل عن النمط لا عن صباح ذلك اليوم."]}],"de":[{"heading":"Gewohnheit statt Augenblick","paragraphs":["Im African-American Vernacular English markiert be eine gewohnheitsmäßige Handlung: he be working heißt, dass jemand regelmäßig arbeitet, nicht gerade jetzt. Das ist eine systematische Aspektform, keine Auslassung.","Die Varietät kennzeichnet außerdem ferne Vergangenheit mit been, etwa in I been knew, und erlaubt in Sätzen wie she nice das Fehlen der Kopula. Solche Formen folgen einer eigenen Grammatik.","Sprecher wechseln je nach Situation zwischen dieser Varietät und Standardenglisch, zu Hause, in der Schule oder bei der Arbeit. Wie stark die Merkmale auftreten, hängt von Region, Alter und Schicht ab und ist im Süden und in großen Städten besonders hörbar."]},{"heading":"Ein Muster wandert weiter","paragraphs":["Viele Züge stammen aus dem Südenglischen und aus dem Kontakt mit westafrikanischen Sprachen während der Sklaverei; die Varietät hat eine eigene Erzähltradition.","Heute verbreitet sich das habituelle be über Musik in Internetenglisch und andere Dialekte. Linguisten erfassen das als Entlehnung, nicht als Fehler.","Hört eine Lehrerin in Detroit einen Schüler sagen he be late, versteht sie: Er kommt regelmäßig zu spät, nicht nur heute, und fragt nach dem Muster statt nach dem Morgen."]}],"en":[{"heading":"Habit versus moment","paragraphs":["In African-American Vernacular English, he be working does not mean he is working now; it means he works regularly. This is a systematic aspect marker, not a missing word.","The variety also marks remote past with been, as in I been knew, and allows zero copula in sentences such as she nice. These are grammatical choices within a full system.","Speakers switch between this variety and Standard English depending on setting, at home, in class or at work. How densely the features appear varies by region, age and class, and is strongest in the South and in big cities."]},{"heading":"A pattern on the move","paragraphs":["Many features come from Southern English and from contact with West African languages during slavery, and the variety has its own narrative tradition.","Today the habitual be is spreading into internet English and other dialects through music, which linguists track as borrowing rather than error.","When a Detroit teacher hears a student say he be late, she understands that the boy is routinely late, not late today, so she asks about the pattern rather than the morning."]}]},"context":{"countries":["US"],"region":"Nationwide, strongest in the South and in cities","community":"African American communities","continent":"north-america","languages":["en"],"period":"contemporary"},"tags":["languages","Nationwide, strongest in the South and in cities"],"sources":[{"organization":"Wikipedia","title":{"ar":"African-American Vernacular English","de":"African-American Vernacular English","en":"African-American Vernacular English"},"url":"https://en.wikipedia.org/wiki/African-American_Vernacular_English","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Habitual be","de":"Habitual be","en":"Habitual be"},"url":"https://en.wikipedia.org/wiki/Habitual_be","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"معلمة في ديترويت تسمع طالبًا يقول he be late، فتفهم أنه يتأخر بانتظام لا اليوم فقط، وتسأله عن النمط.","de":"Eine Lehrerin in Detroit hört he be late und fragt nicht, warum der Schüler heute zu spät kam, sondern wie oft das vorkommt.","en":"A Detroit teacher hears a student say he be late and asks how often it happens, not why he was late that morning."},"misunderstanding":{"ar":"كثيرون يظنون أن be هنا خطأ أو كلام ناقص، لكنها علامة نحوية تحمل معنى العادة بوضوح.","de":"Viele halten be für einen Fehler oder für unvollständiges Englisch, dabei ist es eine klare grammatische Markierung.","en":"Many hear be as a mistake or broken English, when it is a precise grammatical signal of habit."},"comparison":{"ar":"الإنجليزية المعيارية تحتاج إلى ظرف مثل usually لقول الشيء نفسه، بينما تكفي be وحدها في هذه اللهجة.","de":"Standardenglisch braucht ein Wort wie usually, um dasselbe zu sagen; hier genügt die Form be.","en":"Standard English needs an adverb like usually to say the same thing; here the form be carries it alone."},"expression":{"original":"He be working","language":"African-American Vernacular English","gloss":{"ar":"هو يعمل بانتظام (عادةً)","de":"er arbeitet regelmäßig (habituell)","en":"he works regularly (habitual)"},"usage":{"ar":"تُقال لوصف عمل متكرر، لا لعمل يجري في هذه اللحظة.","de":"Beschreibt eine wiederkehrende Tätigkeit, nicht was gerade geschieht.","en":"Describes a recurring activity, not something happening right now."},"transliteration":"he be working"}},{"id":"lng-068","version":2,"slug":"eh-the-canadian-tag-that-asks-you-to-agree-without-arguing","contentType":"detail","category":"communication","title":{"ar":"إيه: علامة كندية تطلب الموافقة دون جدال","de":"Eh: Kanadas Tag, der Zustimmung ohne Streit sucht","en":"Eh: the Canadian tag that asks you to agree without arguing"},"deck":{"ar":"في كندا، تُستخدم 'إيه' في نهاية الجملة لدعوة الآخرين إلى الموافقة أو تأكيد الفهم، وهي سمة بارزة في المحادثة اليومية.","de":"In Kanada beendet man Sätze oft mit 'eh', um Zustimmung zu signalisieren oder Gemeinsamkeit zu betonen – ein alltägliches Kommunikationsmittel.","en":"In Canada, ending a sentence with 'eh' invites agreement or shared understanding—a small but telling feature of everyday talk."},"teaser":{"ar":"كيف تحولت 'إيه' إلى أداة تواصل كندية تعكس أسلوب الحياة المتفاهم؟","de":"Warum 'eh' mehr ist als ein Klischee: Ein Blick auf Kanadas entspannte Gesprächskultur.","en":"How a two-letter particle became a Canadian communication habit, and why it's more than a stereotype."},"readingMinutes":1,"sections":{"ar":[{"heading":"أداة صغيرة بمعانٍ كبيرة","paragraphs":["في كندا، ينهي المتحدثون جملهم بـ 'إيه' لدعوة المستمع إلى الموافقة، كما في 'يوم جميل، إيه؟' أو 'أنت قادم، إيه؟'. هذه الأداة لا تقتصر على السؤال، بل تمتد لتشير إلى المعرفة المشتركة أو لطلب إعادة ما قيل.","توجد هذه الأداة في لهجات إنجليزية أخرى كالنيوزيلندية وبعض البريطانية، لكن الكنديين يستخدمونها بتكرار ووظائف مميزة. ومع ذلك، يعتبرها الكنديون أنفسهم صورة نمطية خفيفة، ويقل استخدامها بين الشباب في المدن."]},{"heading":"بين الواقع والصورة النمطية","paragraphs":["يختلف تكرار 'إيه' ووظيفتها حسب المنطقة والعمر واللغة الأم. الناطقون بالفرنسية في كندا يستخدمون أدوات مختلفة، كما أن الصورة النمطية عن 'إيه' تُصدَّر أكثر مما تُمارس فعليًا. وتبرز سمات لفظية أخرى، مثل رفع الصوت في 'about' و'house'، وهي أصعب في التقليد من 'إيه'."]}],"de":[{"heading":"Kleine Partikel, große Wirkung","paragraphs":["Kanadier hängen 'eh' an Aussagen, um Zustimmung einzuladen, etwa in 'schöner Tag, eh?' oder 'du kommst, eh?'. Die Partikel markiert auch Erzählungen und geteiltes Wissen oder bittet um Wiederholung.","Sie existiert auch in anderen englischen Varietäten, doch im Kanadischen hat sie eine besondere Häufigkeit und Funktion. Viele junge Städter verwenden sie seltener als das Klischee vermuten lässt."]},{"heading":"Klischee und gelebte Realität","paragraphs":["Häufigkeit und Funktion variieren je nach Region, Alter und Muttersprache. Frankophone Kanadier nutzen andere Partikeln, und das 'eh'-Klischee wird eher exportiert als gelebt. Zudem prägen Vokalbesonderheiten wie die kanadische Anhebung in 'about' und 'house' den Klang – schwerer nachzuahmen als 'eh'."]}],"en":[{"heading":"A tiny particle with big jobs","paragraphs":["Canadians tack 'eh' onto statements to invite agreement, as in 'nice day, eh?' or 'you're coming, eh?'. It also marks narrative and shared knowledge, and can stand alone as a request to repeat something.","The particle exists in other Englishes, including New Zealand and parts of Britain, but Canadian English uses it with distinctive frequency and function. Canadians themselves treat 'eh' as a mild stereotype, and many younger urban speakers use it less than the stereotype suggests."]},{"heading":"Between stereotype and real life","paragraphs":["Frequency and function vary by region, age and first language; francophone Canadians use a different set of tags, and the 'eh' stereotype is exported more than it is performed. Canadian English also has recognisable vowel patterns, such as Canadian raising in 'about' and 'house', which are harder to parody than 'eh'."]}]},"context":{"countries":["CA"],"region":"Nationwide","continent":"north-america","languages":["en","fr"],"period":"contemporary"},"tags":["communication","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"Canadian English","de":"Canadian English","en":"Canadian English"},"url":"https://en.wikipedia.org/wiki/Canadian_English","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Eh","de":"Eh","en":"Eh"},"url":"https://en.wikipedia.org/wiki/Eh","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في تورونتو، ينهي زميل اجتماعًا بجملة 'إذن نحن متفقون، إيه؟'، فيرد الحاضرون بإيماءات بدل الكلمات، لأن الأداة قامت بالمهمة.","de":"Eine Kollegin in Toronto beendet die Besprechung mit 'also sind wir uns einig, eh?', und der Raum nickt, weil die Partikel die Frage bereits gestellt hat.","en":"A Toronto colleague ends a meeting summary with 'so we're agreed, eh?', and the room answers with nods rather than words, because the particle has already done the asking."},"misunderstanding":{"ar":"يعتقد البعض أن 'إيه' تعني 'ماذا؟' فقط، لكنها غالبًا دعوة للموافقة أو تأكيد مشترك.","de":"Manche halten 'eh' für ein bloßes 'was?', doch meist lädt es zur Zustimmung ein oder betont Gemeinsames.","en":"Some think 'eh' just means 'what?', but it usually invites agreement or highlights shared knowledge."},"comparison":{"ar":"بينما تستخدم الإنجليزية النيوزيلندية 'إيه' أيضًا، فإن الكنديين يكثرون منها في سياقات ودّية وغير رسمية.","de":"Auch im neuseeländischen Englisch gibt es 'eh', aber Kanadier verwenden es häufiger in freundlichen, ungezwungenen Kontexten.","en":"While New Zealand English also uses 'eh', Canadians deploy it more often in friendly, informal contexts."},"expression":{"original":"Eh?","language":"English (Canadian)","gloss":{"ar":"صحيح؟ (أداة تطلب الموافقة)","de":"nicht wahr? (Zustimmungs-Tag)","en":"right? (tag asking agreement)"},"usage":{"ar":"تُستخدم في نهاية الجملة لدعوة المستمع إلى الموافقة أو تأكيد الفهم.","de":"Wird am Satzende verwendet, um Zustimmung oder Bestätigung einzuholen.","en":"Used at the end of a statement to invite agreement or confirmation."},"transliteration":"eh"}},{"id":"lng-069","version":2,"slug":"bonjour-hi-the-montreal-greeting-that-refuses-to-guess-your-language","contentType":"scene","category":"communication","title":{"ar":"بونجور هاي: تحية مونتريال التي ترفض التخمين","de":"Bonjour, hi: der Gruß, der nicht raten will","en":"Bonjour, hi: the greeting that refuses to guess"},"deck":{"ar":"في متاجر مونتريال يفتتح العاملون بالتحية المزدوجة لغةً، فلا يضطرون إلى تخمين لغة الزبون ولا إلى إحراجه بسؤال مباشر.","de":"In Montrealer Läden eröffnen Angestellte zweisprachig, damit niemand die Sprache des Gegenübers erraten oder danach fragen muss.","en":"In Montreal shops, staff open in two languages at once so nobody has to guess a customer's language or ask outright."},"teaser":{"ar":"تحية واحدة بلغتين تحلّ مشكلة سياسية: كيف ترحّب بزبون دون أن تخمّن لغته فتخطئ في حقه؟","de":"Ein Gruß in zwei Sprachen löst ein politisches Problem: Wie begrüßt man Kundschaft, ohne mit der Sprache danebenzuliegen?","en":"One greeting in two languages solves a political problem: how do you welcome a customer without guessing wrong?"},"readingMinutes":1,"sections":{"ar":[{"heading":"تحية تتجاوز السؤال","paragraphs":["يفتتح العاملون في متاجر مونتريال غالباً بعبارة «بونجور، هاي!» ليشيروا إلى أن الخدمة متاحة بالفرنسية والإنجليزية دون سؤال الزبون عن تفضيله.","التحية حلّ عملي لمشكلة لغوية سياسية، لأن التخمين الخاطئ قد يسيء إلى الزبون في أي من الاتجاهين.","في الفرنسية الكيبيكية تؤدي كلمة «بونجور» وظيفة الوداع أيضاً، خلافاً لفرنسا، فالكلمة نفسها تفتح المعاملة وتغلقها."]},{"heading":"بين القانون والعادة","paragraphs":["يشترط ميثاق اللغة الفرنسية في كيبيك أن تكون الفرنسية اللغة العادية للتجارة، والتحية المزدوجة تقف عند حدود هذه القاعدة.","في عام 2017 أقرّت الجمعية الوطنية اقتراحاً يحثّ التجار على الاكتفاء بـ«بونجور» وحدها، فتحوّل النقاش إلى جدل وطني صغير.","تسود التحية في مونتريال أكثر من مدينة كيبيك والمناطق الريفية، وبعض الناطقين بالفرنسية يسمعونها رفضاً للالتزام بالفرنسية، بينما يستخدمها الشباب ثنائيو اللغة بعفوية."]}],"de":[{"heading":"Ein Gruß statt einer Frage","paragraphs":["Verkäuferinnen und Verkäufer in Montreal beginnen oft mit „Bonjour, hi!“, um zu zeigen, dass der Service auf Französisch und Englisch möglich ist, ohne nach der bevorzugten Sprache zu fragen.","Der Gruß ist eine praktische Antwort auf ein sprachpolitisches Problem, denn ein falscher Rat könnte Kundschaft in beide Richtungen beleidigen.","Im Quebecer Französisch dient „bonjour“ auch als Abschied, anders als in Frankreich, sodass dasselbe Wort das Geschäft eröffnet und beschließt."]},{"heading":"Zwischen Charta und Gewohnheit","paragraphs":["Die Charta der französischen Sprache verlangt, dass Französisch die normale Sprache des Handels ist; der zweisprachige Gruß bewegt sich am Rand dieser Regel.","2017 verabschiedete die Nationalversammlung einen Antrag, Händler sollten nur mit „bonjour“ grüßen, und die Debatte wurde zu einer kleinen nationalen Kontroverse.","In Montreal ist der Gruß verbreiteter als in Quebec-Stadt und auf dem Land; manche Frankophone hören darin eine Weigerung, sich zum Französischen zu bekennen, während jüngere Zweisprachige ihn locker verwenden."]}],"en":[{"heading":"A greeting instead of a question","paragraphs":["Montreal shop staff often open with “Bonjour, hi!” to signal that service is available in French and English without asking which one a customer prefers.","The greeting is a practical solution to a language-political problem, because guessing wrong can insult a customer in either direction.","In Quebec French, bonjour also serves as goodbye, unlike in France, so the same word opens and closes the transaction."]},{"heading":"Between the charter and habit","paragraphs":["Quebec's Charter of the French Language requires French to be the normal language of commerce, and the bilingual greeting sits at the edge of that rule.","In 2017 the National Assembly passed a motion urging merchants to greet with bonjour alone, and the debate became a small national controversy.","Bonjour, hi is common in Montreal but less so in Quebec City and rural regions, and some francophones hear it as a refusal to commit to French, while younger bilinguals use it casually."]}]},"context":{"countries":["CA"],"region":"Montreal and bilingual Quebec","continent":"north-america","languages":["fr","en"],"period":"contemporary"},"tags":["communication","Montreal and bilingual Quebec"],"sources":[{"organization":"Wikipedia","title":{"ar":"Quebec French","de":"Quebec French","en":"Quebec French"},"url":"https://en.wikipedia.org/wiki/Quebec_French","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"French language in Canada","de":"French language in Canada","en":"French language in Canada"},"url":"https://en.wikipedia.org/wiki/French_language_in_Canada","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يقول بائع في متجر بحي بلاتو «بونجور، هاي» لكل من يدخل، ثم يكمل باللغة التي يجيب بها الزبون، متنقلاً بين اللغتين مرتين في دقيقة دون تعليق.","de":"Eine Angestellte in einem Laden im Plateau sagt zu jedem Eintretenden „bonjour, hi“ und fährt in der Sprache fort, in der die Kundschaft antwortet – zweimal pro Minute, ohne Kommentar.","en":"A clerk in a Plateau shop says bonjour, hi to everyone who enters, then continues in whichever language the customer answers, switching twice in a minute without comment."},"misunderstanding":{"ar":"يظن بعض الزوار أن التحية المزدوجة مجرد لياقة تجارية، بينما يقرأها آخرون موقفاً في جدل لغوي وسياسي أوسع.","de":"Manche Besucher halten den doppelten Gruß für reine Höflichkeit, andere lesen darin eine Haltung in einer größeren sprachpolitischen Debatte.","en":"Some visitors take the double greeting as mere retail politeness, while others read it as a stance in a wider language-politics debate."},"comparison":{"ar":"في فرنسا تبقى «بونجور» تحية نهارية، أما في كيبيك فهي تحية ووداع في آن، والتحية المزدوجة إضافة مونتريالية خاصة.","de":"In Frankreich bleibt „bonjour“ ein Tagesgruß, in Quebec ist es Gruß und Abschied zugleich; der doppelte Gruß ist eine Montrealer Besonderheit.","en":"In France bonjour stays a daytime hello, in Quebec it is hello and goodbye at once, and the double greeting is a Montreal particularity."},"expression":{"original":"Bonjour, hi!","language":"Français (Quebec)","gloss":{"ar":"مرحباً (تحية ثنائية اللغة)","de":"Hallo (zweisprachiger Gruß)","en":"hello (bilingual greeting)"},"usage":{"ar":"تُقال عند دخول المتجر، ويُكمل الحوار باللغة التي يختارها الزبون.","de":"Beim Betreten eines Ladens gesagt; das Gespräch geht in der Sprache weiter, die die Kundschaft wählt.","en":"Said when entering a shop; the exchange continues in whichever language the customer chooses."},"transliteration":"bonjour, hi"}},{"id":"lng-070","version":2,"slug":"mande-the-mexican-pardon-that-literally-means-command-me","contentType":"note","category":"communication","title":{"ar":"ماندي: عفوًا المكسيكية التي تعني أمرني","de":"Mande: die mexikanische Entschuldigung, die „befiehl mir“ bedeutet","en":"Mande: the Mexican pardon that literally means command me"},"deck":{"ar":"كلمة واحدة تجمع بين الأدب والطاعة في الحديث اليومي، خاصة مع كبار السن.","de":"Ein einziges Wort vereint Höflichkeit und Unterordnung im Alltag, besonders gegenüber Älteren.","en":"One word blends courtesy and deference in everyday speech, especially toward elders."},"teaser":{"ar":"في المكسيك، كلمة «ماندي» ليست مجرد طلب تكرار، بل انحناءة لفظية تحمل احترامًا مضاعفًا.","de":"In Mexiko ist „mande“ nicht nur eine Bitte um Wiederholung, sondern eine verbale Verbeugung mit doppelter Ehrerbietung.","en":"In Mexico, “mande” is more than a request to repeat—it’s a verbal bow that doubles respect."},"readingMinutes":1,"sections":{"ar":[{"heading":"أصل الكلمة ومعناها المزدوج","paragraphs":["تأتي كلمة «ماندي» من الفعل الإسباني «ماندار» أي «يأمر»، وتُستخدم كاعتذار أو استفهام «ماذا قلت؟» أو «في خدمتك»، خاصة عند مخاطبة شخص أكبر سنًا.","عادةً ما تصاحب «ماندي» ضمير المخاطبة الرسمي «أوستيد»، فيتضاعف التوقير: المتحدث الأصغر يخضع نحويًا ومعجميًا في آن واحد."]},{"heading":"التعليم والاستخدام اليومي","paragraphs":["يعلّم الآباء أطفالهم أن يجيبوا بـ«ماندي» بدلًا من «كيه؟» وحدها، لأن «كيه» تُعتبر فظة ومفاجئة. في إسبانيا، الموقف نفسه يتطلب «كومو؟» أو «بيردوني»، أما «ماندي» فتبدو قديمة الطراز أو أمريكية لاتينية.","تنتشر «ماندي» بقوة في وسط وجنوب المكسيك وفي المجتمعات المكسيكية الأمريكية. وتختلف حسب المنطقة والجيل: ففي شمال المكسيك يُستخدم أقل، والشباب في المدن يتبادلون بين «كومو؟» و«ماندي؟»."]}],"de":[{"heading":"Herkunft und doppelte Bedeutung","paragraphs":["„Mande“ stammt vom spanischen Verb „mandar“ (befehlen) und dient als Entschuldigung, Frage („Wie bitte?“) oder als „zu Ihren Diensten“, besonders wenn man mit einer älteren Person spricht.","Meist begleitet „mande“ das formelle „usted“, sodass die Ehrerbietung verdoppelt wird: Der jüngere Sprecher unterwirft sich gleichzeitig grammatikalisch und lexikalisch."]},{"heading":"Erziehung und Alltagsgebrauch","paragraphs":["Eltern bringen Kindern bei, mit „mande“ statt nur mit „qué?“ zu antworten, da „qué?“ allein als schroff gilt. In Spanien verlangt dieselbe Situation „como?“ oder „perdone“, während „mande“ dort altmodisch oder lateinamerikanisch klingt.","„Mande“ ist im zentralen und südlichen Mexiko sowie in mexikanisch-amerikanischen Gemeinschaften stark verbreitet. Die Verwendung variiert regional und generationell: Im Norden Mexikos wird es seltener gebraucht, junge Stadtbewohner wechseln oft zwischen „como?“ und „mande?“."]}],"en":[{"heading":"Origin and double meaning","paragraphs":["Mande comes from the Spanish verb mandar (to command) and works as “pardon?”, “what did you say?” or “at your service,” especially when speaking to an elder.","It usually accompanies usted, so the deference is doubled: the younger speaker submits grammatically and lexically at once."]},{"heading":"Upbringing and daily use","paragraphs":["Parents teach children to answer mande rather than qué? because qué? alone is considered abrupt. In Spain the same situation calls for como? or perdone, and mande there sounds old-fashioned or Latin American.","The form survives strongly in central and southern Mexico and in Mexican-American communities in the United States. Usage varies by region and generation: northern Mexican speech uses it less, and urban young people often say como? or mande? interchangeably."]}]},"context":{"countries":["MX"],"region":"Central and southern Mexico","continent":"north-america","languages":["es"],"period":"contemporary"},"tags":["communication","Central and southern Mexico"],"sources":[{"organization":"Wikipedia","title":{"ar":"Mexican Spanish","de":"Mexican Spanish","en":"Mexican Spanish"},"url":"https://en.wikipedia.org/wiki/Mexican_Spanish","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Spanish language","de":"Spanish language","en":"Spanish language"},"url":"https://en.wikipedia.org/wiki/Spanish_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"جدة في بويبلا تقول شيئًا من المطبخ، فيجيبها حفيدها «ماندي؟» قبل أن يستدير، لأن الكلمة رد فعل تلقائي للاحترام وليست طلبًا للتكرار.","de":"Eine Großmutter in Puebla sagt etwas aus der Küche, und ihr Enkel antwortet „mande?“, bevor er sich umdreht, weil das Wort ein Reflex der Achtung ist und keine Bitte um Wiederholung.","en":"A grandmother in Puebla says something from the kitchen, and her grandson answers mande? before he has even turned around, because the word is the reflex of respect rather than a request to repeat."},"misunderstanding":{"ar":"قد يظن البعض أن «ماندي» تعني حرفيًا «أمرني» كطلب مباشر، لكنها في السياق اليومي تعبير مهذب عن الاستفسار أو الاستعداد للخدمة.","de":"Manche könnten glauben, „mande“ bedeute wörtlich „befiehl mir“ als direkte Aufforderung, doch im Alltag ist es ein höflicher Ausdruck der Nachfrage oder Dienstbereitschaft.","en":"Some might think mande literally means “command me” as a direct order, but in everyday context it’s a polite way to ask for repetition or offer service."},"comparison":{"ar":"في إسبانيا يُستخدم «كومو؟» أو «بيردوني» في الموقف نفسه، بينما «ماندي» نادرة هناك وتبدو قديمة أو أمريكية لاتينية.","de":"In Spanien verwendet man in derselben Situation „como?“ oder „perdone“, während „mande“ dort selten ist und altmodisch oder lateinamerikanisch wirkt.","en":"In Spain, the same situation calls for como? or perdone, while mande is rare there and sounds old-fashioned or Latin American."},"expression":{"original":"¿Mande?","language":"Español (mexicano)","gloss":{"ar":"عفوًا؟ / في خدمتك؟","de":"Wie bitte? / Zu Ihren Diensten?","en":"Pardon? / At your service?"},"usage":{"ar":"تُستخدم عند عدم سماع المتحدث أو عند مخاطبة كبير السن بأدب.","de":"Wird verwendet, wenn man den Sprecher nicht verstanden hat oder eine ältere Person höflich anspricht.","en":"Used when you didn’t hear the speaker or to address an elder politely."},"transliteration":"mande?"}},{"id":"lng-071","version":2,"slug":"ahorita-the-mexican-word-that-means-now-soon-or-never","contentType":"detail","category":"communication","title":{"ar":"أوريتا: كلمة مكسيكية تعني الآن أو لاحقًا أو أبدًا","de":"Ahorita: Das mexikanische Wort für jetzt, gleich oder nie","en":"Ahorita: The Mexican Word for Now, Soon or Never"},"deck":{"ar":"كيف تصبح تصغير كلمة 'الآن' أداة يومية للمكسيكيين للتخفيف من الالتزامات وتأجيل الوعود دون رفض صريح.","de":"Wie die Verkleinerungsform von 'jetzt' im Mexikanischen zu einem alltäglichen Werkzeug wird, um Verpflichtungen abzuschwächen und Versprechen aufzuschieben.","en":"How the diminutive of 'now' becomes a daily tool for softening commitments and postponing promises without ever saying no."},"teaser":{"ar":"في المكسيك، 'أوريتا' ليست مجرد 'الآن'. إنها كلمة تصنع مساحة بين القول والفعل، وتحددها نبرة الصوت والإيماءات.","de":"In Mexiko ist 'ahorita' nicht einfach 'jetzt'. Es ist ein Wort, das Raum zwischen Gesagtem und Getanem schafft – Tonfall und Gestik entscheiden.","en":"In Mexico, 'ahorita' isn't just 'now'. It's a word that creates space between saying and doing, with tone and gesture deciding which."},"readingMinutes":1,"sections":{"ar":[{"heading":"معنى يتشكل حسب النبرة","paragraphs":["أوريتا هي تصغير كلمة 'أهورا' (الآن)، والتصغير يجعل التوقيت أصغر وأكثر ليونة وأقل التزامًا. يمكن أن تعني هذه اللحظة، أو بعد بضع دقائق، أو في نقطة مستقبلية غير محددة، والنبرة والإيماءات هي التي تحدد المعنى.","عندما يقول صاحب متجر 'أوريتا فينغو' (سأعود حالًا)، فقد يعود بعد دقيقتين أو عشرين. الكلمة تلطف الرفض أو التأخير دون الإفصاح عن أي منهما، مما يجعلها مفيدة في مواقف الخدمة والنقاشات العائلية."]},{"heading":"أداة تواصل شاملة","paragraphs":["تستخدم دول أخرى ناطقة بالإسبانية 'أوريتا' أيضًا، لكن الإسبانية المكسيكية جعلتها أداة محادثة شبه عالمية. يختلف استخدامها بين الشمال والجنوب في المدى الذي يمتد إليه التأخير، كما يتفاوت بين الأجيال في تكرار اللجوء إليها."]}],"de":[{"heading":"Bedeutung nach Tonfall","paragraphs":["Ahorita ist die Verkleinerungsform von 'ahora' (jetzt), und der Diminutiv macht den Zeitpunkt kleiner, weicher und unverbindlicher. Es kann diesen Augenblick, in ein paar Minuten oder zu einem unbestimmten zukünftigen Zeitpunkt bedeuten – Tonfall und Gestik entscheiden.","Wenn ein Ladenbesitzer 'Ahorita vengo' (ich komme gleich wieder) sagt, kann er in zwei oder zwanzig Minuten zurück sein. Das Wort mildert eine Ablehnung oder Verzögerung, ohne eine von beiden auszusprechen, was es in Service-Situationen und Familienstreitigkeiten nützlich macht."]},{"heading":"Ein universelles Gesprächswerkzeug","paragraphs":["Andere spanischsprachige Länder verwenden ahorita ebenfalls, aber im mexikanischen Spanisch ist es zu einem nahezu universellen Gesprächswerkzeug geworden. Die Verwendung unterscheidet sich regional – im Norden und Süden Mexikos wird die Zeitspanne unterschiedlich weit gedehnt – und auch zwischen Generationen gibt es Unterschiede in der Häufigkeit."]}],"en":[{"heading":"Meaning Shaped by Tone","paragraphs":["Ahorita is the diminutive of ahora (now), and the diminutive makes the timing smaller, softer and less committal. It can mean this instant, in a few minutes or at some unspecified future point, and tone plus gesture decide which.","When a shopkeeper says 'Ahorita vengo' (I'll be right back), they may return in two minutes or twenty. The word softens a refusal or a delay without stating either, which makes it useful in service encounters and family arguments."]},{"heading":"A Near-Universal Conversational Tool","paragraphs":["Other Spanish-speaking countries use ahorita too, but Mexican Spanish has made it a near-universal conversational tool. Usage varies regionally—northern and southern Mexico differ in how far the delay stretches—and generationally in how often it's reached for."]}]},"context":{"countries":["MX"],"region":"Nationwide","continent":"north-america","languages":["es"],"period":"contemporary"},"tags":["communication","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"Mexican Spanish","de":"Mexican Spanish","en":"Mexican Spanish"},"url":"https://en.wikipedia.org/wiki/Mexican_Spanish","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Spanish language","de":"Spanish language","en":"Spanish language"},"url":"https://en.wikipedia.org/wiki/Spanish_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"سباك في مكسيكو سيتي يقول 'أوريتا' لثلاثة عملاء في صباح واحد: بالنسبة للأول تعني خلال ساعة، وللثاني بعد الظهر، وللثالث يعرف أنها تعني الأسبوع القادم.","de":"Ein Klempner in Mexiko-Stadt sagt an einem Morgen zu drei verschiedenen Kunden 'ahorita': Beim ersten bedeutet es innerhalb einer Stunde, beim zweiten am Nachmittag, und beim dritten weiß er, dass es nächste Woche heißt.","en":"A Mexico City plumber says ahorita to three different customers in one morning: for the first it means within the hour, for the second this afternoon, and for the third he knows it means next week."},"misunderstanding":{"ar":"يعتمد المعنى كليًا على السياق والعلاقة، والأجانب الذين يفهمون 'أوريتا' على أنها 'الآن' يصابون بخيبة أمل routinely.","de":"Die Bedeutung hängt völlig von Kontext und Beziehung ab, und Ausländer, die ahorita als 'jetzt' verstehen, werden regelmäßig enttäuscht.","en":"Meaning depends entirely on context and relationship, and foreigners who take ahorita as now are routinely disappointed."},"comparison":{"ar":"في بلدان أخرى، 'أوريتا' تعني حرفيًا 'الآن حالًا'، بينما في المكسيك أصبحت كلمة مطاطة تمتد من اللحظة إلى الأبد.","de":"In anderen Ländern bedeutet ahorita wörtlich 'sofort', während es in Mexiko zu einem dehnbaren Wort geworden ist, das vom Augenblick bis zur Ewigkeit reicht.","en":"In other countries, ahorita means literally 'right now', while in Mexico it has become a stretchable word that ranges from the instant to the indefinite future."},"expression":{"original":"Ahorita vengo","language":"Español (mexicano)","gloss":{"ar":"سأعود حالًا (أو متى شئت)","de":"Ich bin gleich wieder da (oder wann auch immer)","en":"I'll be right back (or whenever)"},"usage":{"ar":"يقولها أصحاب المتاجر عند مغادرة الطاولة لفترة قصيرة، أو عندما يريدون تأجيل أمر ما دون تحديد وقت.","de":"Wird von Ladenbesitzern gesagt, wenn sie den Tresen kurz verlassen, oder wenn sie etwas aufschieben wollen, ohne eine Zeit zu nennen.","en":"Said by shopkeepers stepping away from the counter, or when someone wants to postpone something without naming a time."},"transliteration":"ahorita vengo"}},{"id":"lng-072","version":2,"slug":"la-utz-awach-the-k-iche-greeting-that-asks-about-your-face","contentType":"scene","category":"communication","title":{"ar":"تحية كيتشيه التي تسأل عن وجهك","de":"Der K'iche'-Gruß, der nach dem Gesicht fragt","en":"The K'iche' greeting that asks about your face"},"deck":{"ar":"في مرتفعات غواتيمالا، يبدأ الناس يومهم بسؤال عن حال الوجه قبل أي شيء آخر، ثم ينتقلون إلى العائلة والحصاد.","de":"Im guatemaltekischen Hochland beginnt der Tag mit einer Frage nach dem Gesicht, gefolgt von Fragen nach Familie und Ernte.","en":"In the Guatemalan highlands, people open a conversation by asking about your face, then move on to family and harvest."},"teaser":{"ar":"تحية يومية في كيتشيه تسأل إن كان وجهك بخير، ويأتي الجواب قصيراً: بخير، شكراً.","de":"Ein alltäglicher Gruß auf K'iche' fragt, ob das Gesicht gut ist. Die Antwort ist kurz: gut, danke.","en":"An everyday K'iche' greeting asks whether your face is good. The expected reply is short: good, thank you."},"readingMinutes":1,"sections":{"ar":[{"heading":"سؤال عن الوجه لا عن الحال","paragraphs":["في مرتفعات غواتيمالا، يحيّي الناس بعضهم بعبارة «لا أوتس أواتش؟» التي تسأل حرفياً إن كان وجهك جيداً. وهي تحية عادية يومية لا صيغة رسمية، والجواب المتوقع قصير: «أوتس، مالتْيوش»، أي بخير وشكراً.","بعد هذا التبادل غالباً ما يأتي سؤال عن العائلة أو الحصاد، فيتحول اللقاء السريع إلى خبر صغير عن البيت والحقل.","تختلف العادة بين المجتمعات وبين بلدات المرتفعات والساحل، كما تختلف بين الأجيال، فالشباب في المدن قد يبدؤون بالإسبانية ثم يعودون إلى كيتشيه."]},{"heading":"لغة حيّة في السوق","paragraphs":["كيتشيه لغة مايانية بقواعد تصرّف خاصة، فهي تميّز فاعل الفعل المتعدي عن فاعل الفعل اللازم بصيغ مختلفة.","تعترف غواتيمالا باثنتين وعشرين لغة مايانية، وكيتشيه من أكبرها بنحو مليون متحدث وبتقليد مكتوب يعود إلى «بوبول فوه».","كثير من المتحدثين ثنائيو اللغة بالإسبانية، وفي الأسواق تختلط الأرقام والأسعار الإسبانية داخل جمل كيتشيه، خاصة فوق العشرين."]}],"de":[{"heading":"Eine Frage nach dem Gesicht","paragraphs":["Im Hochland Guatemalas begrüßen sich Menschen mit „La utz awach?“, wörtlich die Frage, ob das Gesicht gut ist. Das ist kein feierlicher Ausdruck, sondern der gewöhnliche Gruß, und die erwartete Antwort lautet kurz „utz, maltyox“ – gut, danke.","Danach folgt oft eine Frage nach der Familie oder der Ernte, sodass aus einer kurzen Begegnung ein kleines Gespräch über Haus und Feld wird.","Die Gewohnheit unterscheidet sich zwischen Gemeinden und zwischen Hochland und Küstenstädten, und auch zwischen Generationen: Jüngere in den Städten beginnen manchmal auf Spanisch und wechseln dann ins K'iche'."]},{"heading":"Eine lebendige Sprache im Markt","paragraphs":["K'iche' ist eine Maya-Sprache mit ergativer Grammatik: Das Subjekt transitiver und intransitiver Verben wird unterschiedlich markiert.","Guatemala erkennt 22 Maya-Sprachen an, und K'iche' ist mit rund einer Million Sprecherinnen und Sprechern eine der größten, mit einer Schrifttradition bis zum Popol Vuh.","Viele Sprecher sind zweisprachig mit Spanisch, und auf Märkten mischen sich spanische Zahlen und Preise in K'iche'-Sätze, besonders oberhalb von zwanzig."]}],"en":[{"heading":"A question about the face","paragraphs":["In the Guatemalan highlands people greet each other with la utz awach?, which literally asks whether your face is good. It is the ordinary K'iche' greeting rather than a formal formula, and the expected answer is utz, maltyox – good, thank you.","The exchange is often followed by a question about family or the harvest, so a quick meeting turns into small news about home and field.","The habit varies between communities and between highland and coastal towns, and between generations: younger people in cities may start in Spanish and switch back to K'iche'."]},{"heading":"A living language in the market","paragraphs":["K'iche' is a Mayan language with ergative grammar, marking the subject of transitive and intransitive verbs differently.","Guatemala recognises 22 Mayan languages, and K'iche' is one of the largest, with roughly a million speakers and a written tradition going back to the Popol Vuh.","Many speakers are bilingual in Spanish, and in markets Spanish numbers and prices mix into K'iche' sentences, especially above twenty."]}]},"context":{"countries":["GT"],"region":"Guatemalan highlands (Quiche, Totonicapan, Solola)","community":"K'iche' Maya communities","continent":"north-america","languages":["quc","es"],"period":"contemporary"},"tags":["communication","Guatemalan highlands (Quiche, Totonicapan, Solola)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kʼicheʼ language","de":"Kʼicheʼ language","en":"Kʼicheʼ language"},"url":"https://en.wikipedia.org/wiki/K%CA%BCiche%CA%BC_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Mayan languages","de":"Mayan languages","en":"Mayan languages"},"url":"https://en.wikipedia.org/wiki/Mayan_languages","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"امرأة تبيع الأقمشة في تشيتشيكاستينانغو تحيّي زبوناً معتاداً بعبارة «لا أوتس أواتش؟»، ثم تذكر الأسعار بالإسبانية لأن الأرقام فوق العشرين تُقترض عادة.","de":"Eine Frau, die in Chichicastenango Stoffe verkauft, begrüßt eine Stammkundin mit „La utz awach?“ und nennt die Preise dann auf Spanisch, weil Zahlen über zwanzig meist entlehnt werden.","en":"A woman selling textiles in Chichicastenango greets a regular customer with la utz awach? and then quotes prices in Spanish, because numbers above twenty are usually borrowed."},"misunderstanding":{"ar":"قد يظن السامع أن السؤال عن الوجه فضول شخصي أو مزاح، لكنه في الحقيقة تحية مهذبة ومألوفة تماماً كالسؤال عن الحال.","de":"Man könnte den Gruß für Neugier oder Scherz halten, doch er ist eine höfliche, völlig übliche Begrüßung, vergleichbar mit einer Frage nach dem Befinden.","en":"A listener may take the question about the face as personal curiosity or a joke, but it is a polite, entirely ordinary greeting, much like asking how someone is."},"comparison":{"ar":"يشبه الأمر تحية «كيف حالك» العربية، لكن الصورة هنا جسدية ومحددة: الوجه هو ما يُسأل عنه أولاً.","de":"Ähnlich wie ein deutsches „Wie geht's?“ ist der Gruß alltäglich, doch das Bild ist konkreter: Gefragt wird zuerst nach dem Gesicht.","en":"It works like an English “how are you?”, except the image is concrete: the face is what gets asked about first."},"expression":{"original":"La utz awach?","language":"K'iche' (Mayan)","gloss":{"ar":"كيف حالك؟ (هل وجهك بخير؟)","de":"Wie geht es dir? (Ist dein Gesicht gut?)","en":"How are you? (is your face good?)"},"usage":{"ar":"تحية يومية عادية بين الجيران والزبائن والأقارب، ويُجاب عليها عادة بـ«أوتس، مالتْيوش».","de":"Alltäglicher Gruß unter Nachbarn, Kundschaft und Verwandten; die übliche Antwort ist „utz, maltyox“.","en":"An everyday greeting between neighbours, customers and relatives; the usual reply is utz, maltyox."},"transliteration":"la utz awach?"}},{"id":"lng-073","version":2,"slug":"qanuippit-inuktitut-polysynthesis-and-the-snow-words-hoax","contentType":"note","category":"languages","title":{"ar":"قانويبيت: لغة الإنوكتيتوت وتحديات التعددية","de":"Qanuippit: Inuktitut, Polysynthese und der Schneewörter-Schwindel","en":"Qanuippit: Inuktitut, polysynthesis and the snow-words hoax"},"deck":{"ar":"كيف تبني لغة الإنوكتيتوت كلمات طويلة من جذور ولاحقات، ولماذا تحول مثال لغوي إلى خرافة.","de":"Wie Inuktitut lange Wörter aus einer Wurzel und vielen Suffixen bildet und warum ein linguistisches Beispiel zum Schwindel wurde.","en":"How Inuktitut builds long words from a root and many suffixes, and why a linguistic example became a hoax."},"teaser":{"ar":"لغة الإنوكتيتوت تجمع الكلمات في وحدات طويلة، مما يجعل عدّ كلمات الثلج أمرًا بلا معنى. تعرف على كيفية عملها.","de":"Inuktitut packt ganze Sätze in ein Wort. Der Mythos von den hunderten Schneewörtern zeigt, wie Missverständnisse entstehen.","en":"Inuktitut packs a sentence into one word. The snow-words myth shows how a linguistic example can drift into a hoax."},"readingMinutes":1,"sections":{"ar":[{"heading":"بناء الكلمات في الإنوكتيتوت","paragraphs":["تبني لغة الإنوكتيتوت كلمات طويلة من جذر واحد والعديد من اللاحقات، بحيث يمكن لكلمة واحدة أن تحمل ما يوزعه الإنجليزية على جملة كاملة. هذا النظام، المعروف بالتركيب المتعدد، يسمح بتكوين مفردات دقيقة تعبر عن حالات وظروف دقيقة.","نشأ الادعاء بأن لغات الإنويت لديها عشرات أو مئات الكلمات للثلج كمثال لغوي، ثم انحرف إلى خدعة من خلال الاستشهاد المتكرر. ينشأ الارتباك لأن اللغات التركيبية تدمج جذر الثلج بشكل منتج مع لاحقات مختلفة، مما يجعل عدّ الكلمات للثلج بلا معنى."]},{"heading":"الكتابة والاعتراف الرسمي","paragraphs":["تُكتب الإنوكتيتوت بالمقاطع الصوتية في نونافوت وبالحروف اللاتينية في أجزاء من لابرادور وغرينلاند، وقد تم تكييف النظام المقطعي من قبل المبشرين في القرن التاسع عشر. تعترف نونافوت بالإنوكتيتوت والإنويناقتون كلغتين رسميتين إلى جانب الإنجليزية والفرنسية، والغرينلاندية هي اللغة الرسمية في غرينلاند.","تختلف اللغات الإنويتية إقليميًا وجيليًا: فما ينطبق على الإنوكتيتوت في نونافوت قد لا ينطبق في غرينلاند أو ألاسكا، كما يختلف عدد المتحدثين بطلاقة بشكل حاد حسب المجتمع."]}],"de":[{"heading":"Wortbildung im Inuktitut","paragraphs":["Inuktitut bildet lange Wörter aus einer Wurzel und vielen Suffixen, sodass ein einziges Wort ausdrücken kann, wofür Englisch einen ganzen Satz braucht. Dieses polysynthetische System ermöglicht präzise Begriffe für Zustände und Handlungen.","Die Behauptung, Inuit-Sprachen hätten Dutzende oder Hunderte von Wörtern für Schnee, begann als linguistisches Beispiel und wurde durch wiederholte Zitierung zum Schwindel. Die Verwirrung entsteht, weil polysynthetische Sprachen eine Schneewurzel produktiv mit verschiedenen Suffixen kombinieren, was das Zählen von Schneewörtern sinnlos macht."]},{"heading":"Schrift und offizieller Status","paragraphs":["Inuktitut wird in Nunavut in Silbenschrift und in Teilen Labradors und Grönlands in lateinischen Buchstaben geschrieben; das Silbensystem wurde im 19. Jahrhundert von Missionaren angepasst. Nunavut erkennt Inuktitut und Inuinnaqtun neben Englisch und Französisch als offizielle Sprachen an, und Grönländisch ist die Amtssprache Grönlands.","Inuit-Sprachen variieren regional und generationell: Was für Inuktitut in Nunavut gilt, muss nicht in Grönland oder Alaska gelten; die Zahl fließender Sprecher variiert stark je nach Gemeinde."]}],"en":[{"heading":"Building words in Inuktitut","paragraphs":["Inuktitut builds long words from a root plus many suffixes, so one word can carry what English spreads across a sentence. This polysynthetic system allows precise terms for states and actions.","The claim that Inuit languages have dozens or hundreds of words for snow began as a linguistic example and drifted into a hoax through repeated citation. The confusion arises because polysynthetic languages productively combine a snow root with different suffixes, which makes counting words for snow meaningless."]},{"heading":"Writing and official status","paragraphs":["Inuktitut is written in syllabics in Nunavut and in Latin letters in parts of Labrador and Greenland, and the syllabic system was adapted by missionaries in the nineteenth century. Nunavut recognises Inuktitut and Inuinnaqtun as official languages alongside English and French, and Greenlandic is the official language of Greenland.","Inuit languages vary regionally and generationally: what is true of Inuktitut in Nunavut may not hold in Greenland or Alaska, and the number of fluent speakers varies sharply by community."]}]},"context":{"countries":["GL","CA"],"region":"Nunavut, Nunavik and Greenland","community":"Inuit communities","continent":"north-america","languages":["iu","kl","en","da"],"period":"contemporary"},"tags":["languages","Nunavut, Nunavik and Greenland"],"sources":[{"organization":"Wikipedia","title":{"ar":"Eskimo words for snow","de":"Eskimo words for snow","en":"Eskimo words for snow"},"url":"https://en.wikipedia.org/wiki/Eskimo_words_for_snow","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Inuktitut","de":"Inuktitut","en":"Inuktitut"},"url":"https://en.wikipedia.org/wiki/Inuktitut","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يسأل شيخ من نونافوت عن عدد الكلمات التي تمتلكها الإنوكتيتوت للثلج، فيجيب بوصف الفرق بين الثلج الطازج والثلج المتطاير والثلج الجيد للبناء، ثم يقول إن السؤال يفترض أن الكلمات تعمل بالطريقة نفسها التي تعمل بها الكلمات الإنجليزية.","de":"Ein Ältester aus Nunavut antwortet auf die Frage, wie viele Wörter Inuktitut für Schnee hat, indem er den Unterschied zwischen frischem Schnee, treibendem Schnee und gutem Bauschnee beschreibt und dann sagt, die Frage setze voraus, dass Wörter so funktionieren wie englische Wörter.","en":"A Nunavut elder asked how many words Inuktitut has for snow answers by describing the difference between fresh snow, drifting snow and snow good for building, then says the question assumes words work the way English words do."},"misunderstanding":{"ar":"الاعتقاد بأن للإنويت مئات الكلمات للثلج هو سوء فهم ناتج عن طبيعة اللغات التركيبية التي تدمج الجذور واللواحق بشكل منتج، وليس عن وجود مفردات منفصلة.","de":"Der Glaube, Inuit hätten hunderte Wörter für Schnee, ist ein Missverständnis, das aus der produktiven Kombination von Wurzeln und Suffixen in polysynthetischen Sprachen resultiert, nicht aus separaten Vokabeln.","en":"The belief that Inuit have hundreds of words for snow is a misunderstanding stemming from the productive combination of roots and suffixes in polysynthetic languages, not from separate vocabulary items."},"comparison":{"ar":"بينما تعبر الإنجليزية عن الأفكار بكلمات منفصلة، تجمع الإنوكتيتوت المعاني في كلمة واحدة طويلة، مما يعكس طريقة مختلفة لتنظيم المعلومات.","de":"Während Englisch Ideen mit separaten Wörtern ausdrückt, bündelt Inuktitut Bedeutungen in einem langen Wort – eine andere Art, Informationen zu organisieren.","en":"While English expresses ideas with separate words, Inuktitut bundles meanings into one long word—a different way of organizing information."},"expression":{"original":"ᖃᓄᐃᑉᐱᑦ?","language":"ᐃᓄᒃᑎᑐᑦ (Inuktitut)","gloss":{"ar":"كيف حالك؟","de":"Wie geht es dir?","en":"how are you?"},"usage":{"ar":"تحية شائعة تُستخدم عند لقاء شخص ما، وتعني حرفيًا 'كيف أنت؟'.","de":"Ein häufiger Gruß bei der Begrüßung, wörtlich 'Wie bist du?'.","en":"A common greeting used when meeting someone, literally 'how are you?'."},"transliteration":"qanuippit?"}},{"id":"lng-074","version":2,"slug":"wah-gwaan-the-jamaican-greeting-built-on-west-african-grammar","contentType":"language","category":"languages","title":{"ar":"تحية جامايكية بقواعد غرب أفريقية","de":"Wah gwaan: Gruß mit westafrikanischer Grammatik","en":"Wah gwaan: a greeting built on African grammar"},"deck":{"ar":"في جامايكا، تحمل لغة الشارع اليومية بنيةً أفريقية راسخة، وتُستخدم إلى جانب الإنجليزية الرسمية في حياة الناس.","de":"Auf Jamaika trägt die Alltagssprache der Straße westafrikanische Muster in sich und lebt neben dem offiziellen Englisch.","en":"In Jamaica the everyday street language carries West African patterns and lives alongside formal English in the same day."},"teaser":{"ar":"كيف تصبح تحية الصباح جملةً بقواعد أفريقية؟ نظرة على الباتوا الجامايكية كما يعيشها الناس.","de":"Wie wird aus einem Gruß ein Satz mit afrikanischer Grammatik? Ein Blick auf das jamaikanische Patwa im Alltag.","en":"How does a morning greeting become a sentence with African grammar? A look at Jamaican Patwa as people actually speak it."},"readingMinutes":1,"sections":{"ar":[{"heading":"لغة البيت والشارع","paragraphs":["الباتوا الجامايكية كريول قائم على الإنجليزية، لكن قواعدها تحتفظ بأنماط غرب أفريقية من متحدثي الأكان والإيبو الذين جُلبوا إلى الجزيرة. لهذا تبدو الجملة مألوفة في الشارع وغريبة عن قواعد الإنجليزية المدرسية.","تختلف الضمائر عن الإنجليزية: mi تشمل «أنا» و«إياي»، وyu تعني «أنت»، وdem تعلّم الجمع كما في di pikni dem أي الأطفال. والأداة a تدل على الحدوث المستمر، فيقال mi a go أي أنا ذاهب، بينما يحمل السياق الزمن الماضي بدل نهاية الفعل."]},{"heading":"يومٌ بلغتين","paragraphs":["تُستخدم الباتوا في الموسيقى والكنيسة والحياة العائلية، بينما تهيمن الإنجليزية الجامايكية المعيارية على الكتابة الرسمية، وهو ازدواج لغوي يتنقل فيه الجامايكيون يوميًا. ويختلف هذا التنقل بين الأجيال وفي المدن والأرياف، كما يتباين بين الجزيرة والمهجر في بريطانيا وكندا والولايات المتحدة."]}],"de":[{"heading":"Sprache für Haus und Straße","paragraphs":["Jamaikanisches Patois, kurz Patwa, ist ein englischbasiertes Kreol, dessen Grammatik westafrikanische Muster von Akan- und Igbo-Sprechern bewahrt, die auf die Insel gebracht wurden. Deshalb klingt der Satz auf der Straße vertraut und widerspricht doch der Schulgrammatik des Englischen.","Die Pronomen weichen vom Englischen ab: mi steht für „ich“ und „mich“, yu für „du“, und dem markiert den Plural, etwa di pikni dem, die Kinder. Die Partikel a zeigt fortschreitende Handlung an, wie in mi a go, ich gehe gerade, während die Vergangenheit oft im Kontext liegt statt in einer Verbendung."]},{"heading":"Ein Tag in zwei Sprachen","paragraphs":["Patwa wird in Musik, Kirche und Familienleben gesprochen, während Standard-Jamaikanisch-Englisch die formelle Schrift beherrscht, eine klassische Diglossie, die Jamaikaner täglich aushandeln. Diese Balance verschiebt sich je nach Generation und zwischen Stadt und Land, und sie unterscheidet sich auch zwischen der Insel und der Diaspora in Großbritannien, Kanada und den USA."]}],"en":[{"heading":"The language of home and street","paragraphs":["Jamaican Patois, or Patwa, is an English-based creole whose grammar retains West African patterns from Akan and Igbo speakers brought to the island. That is why a street sentence sounds familiar yet breaks the rules of schoolroom English.","Pronouns differ from English: mi covers I and me, yu covers you, and dem marks the plural, as in di pikni dem, the children. The particle a marks progressive action, as in mi a go, I am going, while past tense is often carried by context rather than a verb ending."]},{"heading":"A day in two languages","paragraphs":["Patwa is used in music, church and family life while Standard Jamaican English dominates formal writing, a classic diglossia that Jamaicans navigate daily. That balance shifts with age and between town and country, and it also differs between the island and the diaspora in Britain, Canada and the US."]}]},"context":{"countries":["JM"],"region":"Jamaica, with diaspora in Britain, Canada and the US","continent":"north-america","languages":["jam","en"],"period":"contemporary"},"tags":["languages","Jamaica, with diaspora in Britain, Canada and the US"],"sources":[{"organization":"Wikipedia","title":{"ar":"Jamaican Patois","de":"Jamaican Patois","en":"Jamaican Patois"},"url":"https://en.wikipedia.org/wiki/Jamaican_Patois","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Jamaican English","de":"Jamaican English","en":"Jamaican English"},"url":"https://en.wikipedia.org/wiki/Jamaican_English","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"ينادي سائق حافلة في كينغستون على راكب معتاد بـ wah gwaan فيأتيه الجواب mi de yah، وبعد ساعة يكتب الرجل نفسه طلب وظيفة بالإنجليزية المعيارية دون أن يلاحظ التحول.","de":"Ein Busfahrer in Kingston ruft einem Stammgast wah gwaan zu und hört mi de yah zurück; eine Stunde später schreibt derselbe Mann eine Bewerbung in Standardenglisch, ohne den Wechsel zu bemerken.","en":"A Kingston bus conductor calls wah gwaan to a regular and gets mi de yah in reply, while the same man writes a job application in Standard English an hour later without noticing the switch."},"misunderstanding":{"ar":"يظن كثيرون أن الباتوا إنجليزية مكسورة أو عامية مهملة، لكنها نظام قواعد متماسك بقواعده الخاصة في الضمائر والزمن.","de":"Viele halten Patwa für gebrochenes Englisch oder nachlässigen Slang, doch es ist ein eigenständiges Regelsystem mit eigenen Formen für Pronomen und Zeit.","en":"Many assume Patwa is broken English or careless slang, but it is a coherent system with its own rules for pronouns and tense."},"comparison":{"ar":"حيث تضع الإنجليزية نهاية للفعل الماضي، يعتمد الباتوا على السياق، وحيث تقول الإنجليزية I am going تقول الباتوا mi a go.","de":"Wo das Englische eine Vergangenheitsendung setzt, verlässt sich Patwa auf den Kontext; wo das Englische I am going sagt, sagt Patwa mi a go.","en":"Where English adds a past ending, Patwa leans on context; where English says I am going, Patwa says mi a go."},"expression":{"original":"Wah gwaan?","language":"Jamaican Patois (Patwa)","gloss":{"ar":"ماذا يجري؟ / كيف حالك؟","de":"Was geht? / Wie geht es dir?","en":"what's going on? / how are you?"},"usage":{"ar":"تحية يومية يتبادلها الناس في الشارع والسوق، ويُجاب عنها بـ mi de yah أي أنا هنا.","de":"Alltagsgruß auf Straße und Markt, beantwortet mit mi de yah, ich bin hier.","en":"An everyday greeting in street and market talk, answered with mi de yah, I am here."},"transliteration":"wah gwaan?"}},{"id":"lng-075","version":2,"slug":"jeitinho-the-brazilian-workaround-that-is-admired-and-criticised-at-once","contentType":"detail","category":"languages","title":{"ar":"جيتينيو: الحلول الالتفافية في البرازيل","de":"Jeitinho: der brasilianische Umweg zwischen Lob und Kritik","en":"Jeitinho: the Brazilian workaround admired and criticised"},"deck":{"ar":"كلمة واحدة تصف الإبداع والفساد معًا، وتكشف كيف يتعامل البرازيليون مع البيروقراطية وعدم المساواة في حياتهم اليومية.","de":"Ein einziges Wort beschreibt harmlose Kreativität und Korruption zugleich und zeigt, wie Brasilianer mit Bürokratie und Ungleichheit umgehen.","en":"One word describes harmless creativity and corruption at once, and it shows how Brazilians deal with bureaucracy and inequality in daily life."},"teaser":{"ar":"عبارة برازيلية تصف إيجاد طريق حول قاعدة أو عقبة، وغالبًا عبر معارف شخصية أو حلول مبتكرة، وتثير إعجابًا ونقدًا في آن واحد.","de":"Dar um jeitinho bedeutet, eine Regel oder ein Hindernis zu umgehen, oft über persönliche Kontakte oder improvisierte Lösungen – bewundert und kritisiert zugleich.","en":"Dar um jeitinho means finding a way around a rule or obstacle, often through a personal contact or an improvised solution, and it is admired and criticised at once."},"readingMinutes":1,"sections":{"ar":[{"heading":"طريق صغير حول العقبات","paragraphs":["تعني عبارة «دار أوم جيتينيو» إيجاد مخرج من قاعدة أو عقبة، غالبًا عبر معارف شخصية أو حل مبتكر. والكلمة نفسها تصف إبداعًا غير ضار، كإصلاح استمارة في اللحظة الأخيرة، وفسادًا كتجاوز طابور عبر صديق.","تستخدم البرتغالية البرازيلية كلمة «جيتو» بمعنى المهارة أو الأسلوب، لذا يعني «جيتينيو» حرفيًا طريقة صغيرة لفعل شيء ما. وتختلف النظرة إليه بين الأجيال والمناطق، إذ يبدو أكثر حضورًا في المدن الكبرى حيث تتعقد الإجراءات.","يعالج علماء الاجتماع «جيتينيو» كردّ على البيروقراطية وعدم المساواة: عندما تكون القواعد بطيئة وغير عادلة، تصبح المسارات الشخصية خيارًا عقلانيًا."]},{"heading":"إعجاب ونقد في آن","paragraphs":["غالبًا ما تقترن الفكرة بعبارة «فوce سابي كوم كيم إستا فالاندو؟» أي «هل تعرف من تخاطب؟»، وهي تستدعي التسلسل الهرمي بدلًا من الارتجال.","يعد «جيتينيو» وصفًا ذاتيًا وطنيًا ومثيرًا للجدل: كثير من البرازيليين يدينونه كفساد، ويتوقف قبوله على ما إذا كان الحل يضر بشخص آخر."]}],"de":[{"heading":"Ein kleiner Weg um das Hindernis","paragraphs":["Dar um jeitinho bedeutet, einen Weg um eine Regel oder ein Hindernis zu finden, oft über persönliche Kontakte oder eine improvisierte Lösung. Dasselbe Wort beschreibt harmlose Kreativität, etwa ein Formular in letzter Minute zu retten, und Korruption, etwa eine Warteschlange über einen Freund zu überspringen.","Das brasilianische Portugiesisch verwendet jeito für Geschick oder Art, jeitinho heißt wörtlich also eine kleine Art, etwas zu tun. Je nach Region und Generation wird der Begriff unterschiedlich bewertet, besonders präsent ist er in den großen Städten.","Soziologen verstehen jeitinho als Antwort auf Bürokratie und Ungleichheit: Wenn Regeln langsam und ungerecht sind, werden persönliche Wege rational."]},{"heading":"Bewunderung und Kritik zugleich","paragraphs":["Oft wird der Begriff mit dem Satz você sabe com quem está falando? verbunden – „Wissen Sie, mit wem Sie sprechen?“ –, der Hierarchie statt Improvisation beschwört.","Jeitinho ist eine nationale Selbstbeschreibung und umstritten: Viele Brasilianer verurteilen es als Korruption, und die Zustimmung hängt davon ab, ob der Umweg jemand anderem schadet."]}],"en":[{"heading":"A little way around the obstacle","paragraphs":["Dar um jeitinho means finding a way around a rule or an obstacle, often through a personal contact or an improvised solution. The same word describes harmless creativity, such as fixing a form at the last minute, and corruption, such as skipping a queue through a friend.","Brazilian Portuguese uses jeito for a knack or manner, so jeitinho literally means a little way of doing something. The term is judged differently across regions and generations, and it is strongest in urban Brazil.","Sociologists treat jeitinho as a response to bureaucracy and inequality: when rules are slow and unequal, personal routes become rational."]},{"heading":"Admired and criticised at once","paragraphs":["The concept is often paired with the phrase você sabe com quem está falando? (do you know who you are talking to?), which invokes hierarchy instead of improvisation.","Jeitinho is a national self-description and contested: many Brazilians condemn it as corruption, and the term's approval depends on whether the workaround harms someone else."]}]},"context":{"countries":["BR"],"region":"Nationwide, strongest in urban Brazil","continent":"south-america","languages":["pt"],"period":"contemporary"},"tags":["languages","Nationwide, strongest in urban Brazil"],"sources":[{"organization":"Wikipedia","title":{"ar":"Jeitinho","de":"Jeitinho","en":"Jeitinho"},"url":"https://en.wikipedia.org/wiki/Jeitinho","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Brazilian Portuguese","de":"Brazilian Portuguese","en":"Brazilian Portuguese"},"url":"https://en.wikipedia.org/wiki/Brazilian_Portuguese","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"موظف في مكتب في ساو باولو ينقصه مستند، فيطلب من زميل الاتصال بالسجل لإخراجه في اليوم نفسه، ثم يصف النتيجة بأنها «جيتينيو» ويفخر بها.","de":"Ein Büroangestellter in São Paulo, dem ein Dokument fehlt, lässt einen Kollegen beim Standesamt anrufen, damit es noch am selben Tag freigegeben wird, und nennt das Ergebnis stolz ein jeitinho.","en":"A São Paulo office worker missing a document gets a colleague to phone the registry and have it released the same day, then calls the result a jeitinho and is proud of it."},"misunderstanding":{"ar":"ليس كل «جيتينيو» احتيالًا؛ فالكلمة تشمل حلولًا بريئة، لكنها قد تصبح فسادًا حين تستخدم لتفضيل شخص على آخر.","de":"Nicht jedes jeitinho ist Betrug; das Wort umfasst harmlose Lösungen, wird aber zur Korruption, wenn es jemanden bevorzugt.","en":"Not every jeitinho is cheating; the word covers innocent fixes, but it turns into corruption when it gives one person an unfair advantage over another."},"comparison":{"ar":"يشبه «جيتينيو» فن «الواسطة» في مجتمعات عربية، لكنه في البرازيل مفهوم يُناقش علنًا كسمة وطنية بين الإبداع والفساد.","de":"Jeitinho ähnelt der arabischen Wasita, doch in Brasilien wird es offen als nationale Eigenschaft zwischen Kreativität und Korruption diskutiert.","en":"Jeitinho resembles the Arabic wasita, but in Brazil it is openly debated as a national trait somewhere between creativity and corruption."},"expression":{"original":"Dar um jeitinho","language":"Português (brasileiro)","gloss":{"ar":"إيجاد حل التفافي","de":"einen Umweg finden","en":"to find a workaround"},"usage":{"ar":"تقال عند إيجاد مخرج سريع من قاعدة أو عقبة، غالبًا بمساعدة معارف.","de":"Sagt man, wenn man schnell eine Regel oder ein Hindernis umgeht, oft mit Hilfe von Bekannten.","en":"Said when someone quickly gets around a rule or obstacle, often with a contact's help."},"transliteration":"dar um jeitinho"}},{"id":"lng-076","version":2,"slug":"vos-sos-how-the-rio-de-la-plata-replaced-tu-with-vos","contentType":"note","category":"communication","title":{"ar":"فوس سوس: كيف استبدلت منطقة ريو دي لا بلاتا الضمير تو بـ فوس","de":"Vos sos: Wie der Río de la Plata „tú“ durch „vos“ ersetzte","en":"Vos sos: How the Río de la Plata replaced tú with vos"},"deck":{"ar":"في بوينس آيرس ومونتيفيديو، أصبح ضمير فوس هو القاعدة في المخاطبة غير الرسمية، مع تصريفات فعلية خاصة به.","de":"In Buenos Aires und Montevideo ist „vos“ die nahezu universelle Anrede für die informelle Einzahl – mit eigenen Verbformen.","en":"In Buenos Aires and Montevideo, vos is the near-universal informal singular pronoun, with its own verb forms and imperatives."},"teaser":{"ar":"لماذا يقول الأرجنتينيون 'فوس سوس' بدلاً من 'تو إيريس'؟ رحلة عبر الضمير الذي يعيد رسم خريطة اللغة الإسبانية في أمريكا الجنوبية.","de":"Warum sagen Argentinier „vos sos“ statt „tú eres“? Eine Reise durch das Pronomen, das die spanische Sprachlandschaft Südamerikas prägt.","en":"Why do Argentines say 'vos sos' instead of 'tú eres'? A journey through the pronoun that reshapes Spanish in South America."},"readingMinutes":1,"sections":{"ar":[{"heading":"جذور قديمة وحاضر يومي","paragraphs":["يستخدم المتحدثون بالإسبانية في ريو دي لا بلاتا ضمير 'فوس' بدلاً من 'تو' للمفرد المخاطب غير الرسمي، مع تصريفات فعلية خاصة: فوس سوس، فوس تينيس، فوس بوديس. هذا النمط ليس ابتكاراً حديثاً، بل يعود إلى صيغ إسبانية قديمة ظلت حية في المنطقة بينما استانداردت إسبانيا الحديثة على 'تو'.","في بوينس آيرس ومونتيفيديو، 'فوس' شبه عالمي بين جميع الطبقات الاجتماعية. استخدام 'تو' قد يبدو أجنبياً أو متكلفاً عن قصد. هذا الانتشار الواسع يجعل الضمير جزءاً من الهوية اللغوية المحلية، وليس مجرد خيار أسلوبي."]},{"heading":"أوامر خاصة وتباين إقليمي","paragraphs":["يحمل 'فوس' صيغ أمر خاصة به، لذا تحل 'فيني' (تعال) و'ديسيمي' (أخبرني) محل 'فين' و'ديمي'. هذه الصيغ متجذرة في الكلام اليومي وتنعكس في الإعلانات والأغاني والحوارات العابرة.","يوجد 'فوس' أيضاً في مناطق أخرى من العالم الناطق بالإسبانية، بما في ذلك أجزاء من كولومبيا وأمريكا الوسطى وباراغواي، لكن بصيغ ومعانٍ اجتماعية مختلفة عن ريو دي لا بلاتا. يختلف استخدامه حسب البلد والجيل، فالشباب في المدن الكبرى قد يدمجون صيغاً من 'تو' في سياقات معينة، بينما يظل 'فوس' هو الخيار الطبيعي في الحياة اليومية."]}],"de":[{"heading":"Alte Wurzeln im Alltag","paragraphs":["Im Rioplatense-Spanisch verwenden Sprecher „vos“ statt „tú“ für die informelle Einzahl, mit eigenen Verbformen: vos sos, vos tenés, vos podés. Dieses Paradigma stammt aus älterem Spanisch und überlebte in der Region, während sich in Spanien „tú“ standardisierte.","In Buenos Aires und Montevideo ist „vos“ unter allen Klassen nahezu universell. Wer „tú“ benutzt, klingt fremd oder bewusst affektiert. Die Vertrautheit mit „vos“ ist Teil der lokalen sprachlichen Identität und kein bloßer Stilunterschied."]},{"heading":"Eigene Imperative und regionale Unterschiede","paragraphs":["„Vos“ hat eigene Imperativformen: „vení“ (komm) und „decime“ (sag mir) ersetzen „ven“ und „dime“. Diese Formen sind im Alltag tief verankert und begegnen einem in Werbung, Liedern und beiläufigen Gesprächen.","Auch in anderen spanischsprachigen Regionen gibt es „vos“, etwa in Teilen Kolumbiens, Mittelamerikas und Paraguays, jedoch mit anderen Formen und sozialen Bedeutungen als am Río de la Plata. Der Gebrauch variiert je nach Land und Generation: Junge Stadtbewohner mischen mitunter „tú“-Formen ein, während „vos“ im Alltag der Standard bleibt."]}],"en":[{"heading":"Old roots in everyday speech","paragraphs":["Rioplatense Spanish uses vos instead of tú for the familiar singular, with its own verb forms: vos sos, vos tenés, vos podés. The vos paradigm comes from older Spanish and survived in the region while peninsular Spanish standardised tú.","In Buenos Aires and Montevideo, vos is near-universal among all classes. Using tú can sound foreign or deliberately affected. This widespread use makes the pronoun part of local linguistic identity, not just a stylistic choice."]},{"heading":"Special imperatives and regional variation","paragraphs":["Voseo carries its own imperatives, so vení (come) and decime (tell me) replace ven and dime. These forms are deeply embedded in daily speech and appear in ads, songs, and casual conversations.","Other Spanish-speaking regions also use vos, including parts of Colombia, Central America, and Paraguay, but with different forms and social meanings from the Río de la Plata. Usage varies by country and generation: young city dwellers may mix in tú forms in certain contexts, while vos remains the everyday default."]}]},"context":{"countries":["AR","UY"],"region":"Buenos Aires, Montevideo and the Pampas","continent":"south-america","languages":["es"],"period":"contemporary"},"tags":["communication","Buenos Aires, Montevideo and the Pampas"],"sources":[{"organization":"Wikipedia","title":{"ar":"Voseo","de":"Voseo","en":"Voseo"},"url":"https://en.wikipedia.org/wiki/Voseo","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Rioplatense Spanish","de":"Rioplatense Spanish","en":"Rioplatense Spanish"},"url":"https://en.wikipedia.org/wiki/Rioplatense_Spanish","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"مدرس أرجنتيني يسأل طالب تبادل إسباني 'فوس سابيس؟' فيجيب الطالب باستخدام 'تو'، والتباين ليس سوء فهم بل خريطة صغيرة لمكان تعلم كل منهما الإسبانية.","de":"Ein argentinischer Lehrer fragt einen spanischen Austauschschüler „¿vos sabés?“, und der Schüler antwortet mit „tú“. Die Diskrepanz ist kein Missverständnis, sondern eine kleine Landkarte davon, wo jeder sein Spanisch gelernt hat.","en":"An Argentine teacher asks a Spanish exchange student '¿vos sabés?' and the student answers in tú. The mismatch is not a misunderstanding but a small map of where each of them learned Spanish."},"misunderstanding":{"ar":"يعتقد بعض دارسي الإسبانية أن 'فوس' خطأ أو لهجة غير مهذبة، لكنه في ريو دي لا بلاتا هو الصيغة القياسية للخطاب غير الرسمي بين جميع الفئات.","de":"Manche Spanischlernende halten „vos“ für einen Fehler oder unhöflichen Dialekt, doch am Río de la Plata ist es die Standardform der informellen Anrede in allen Schichten.","en":"Some Spanish learners think vos is a mistake or a rude dialect, but in the Río de la Plata it is the standard form of informal address across all social classes."},"comparison":{"ar":"في إسبانيا، 'تو' هو القاعدة في الخطاب غير الرسمي، بينما في الأرجنتين وأوروغواي، 'فوس' هو الخيار اليومي، و'تو' قد يبدو غريباً أو متكلفاً.","de":"In Spanien ist „tú“ die Norm in der informellen Anrede, während in Argentinien und Uruguay „vos“ die alltägliche Wahl ist und „tú“ fremd oder affektiert wirken kann.","en":"In Spain, tú is the norm for informal address, while in Argentina and Uruguay, vos is the everyday choice and tú can sound foreign or affected."},"expression":{"original":"¿Vos sabés?","language":"Español rioplatense","gloss":{"ar":"هل تعرف؟ (بصيغة فوس)","de":"Weißt du? (vos-Form)","en":"Do you know? (vos form)"},"usage":{"ar":"تعبير شائع في بوينس آيرس ومونتيفيديو للسؤال غير الرسمي، يعكس استخدام فوس بدلاً من تو.","de":"Geläufiger Ausdruck in Buenos Aires und Montevideo für informelle Fragen, der den Gebrauch von „vos“ statt „tú“ zeigt.","en":"A common expression in Buenos Aires and Montevideo for informal questions, reflecting the use of vos instead of tú."},"transliteration":"vos sabes?"}},{"id":"lng-077","version":2,"slug":"che-the-two-letter-argentine-word-that-starts-half-the-sentences-in-buenos-aires","contentType":"note","category":"communication","title":{"ar":"تشي: كلمة الأرجنتين التي تبدأ نصف الجمل","de":"Che: das argentinianische Wort für halbe Sätze","en":"Che: the two-letter word that opens Buenos Aires talk"},"deck":{"ar":"في بوينس آيرس، كلمة من حرفين تنادي الناس وتلفت الانتباه، وتظهر في منتصف الحديث أكثر مما تظهر في بدايته.","de":"In Buenos Aires ruft man mit zwei Buchstaben Menschen an und lenkt Aufmerksamkeit – mitten im Satz häufiger als am Anfang.","en":"In Buenos Aires, two letters call people over and pull attention, appearing mid-sentence more often than at the start."},"teaser":{"ar":"كلمة «تشي» تعني تقريباً «يا» أو «صاحبي»، لكنها في بوينس آيرس أداة يومية لشد الانتباه أكثر منها نداءً.","de":"„Che“ heißt ungefähr „hey“ oder „Kumpel“, doch in Buenos Aires ist es vor allem ein täglicher Aufmerksamkeitsmarker.","en":"Che roughly means hey or mate, but in Buenos Aires it works above all as an everyday attention marker in conversation."},"readingMinutes":1,"sections":{"ar":[{"heading":"كيف يستخدمها الناس في الشارع","paragraphs":["«تشي» كلمة نداء تخاطب بها شخصاً، بمعنى «يا» أو «صاحبي»، كما في «تشي، ماذا تفعل؟». لكنها تظهر أيضاً في وسط الجملة كعلامة لفت انتباه، فيقول سائق الباص «تشي، اصعد من الخلف» دون أن ينظر إلى أحد.","يختلف الاستخدام بحسب المنطقة والجيل: الشباب في المدن يكثرون منها، بينما يقلّلها بعض الكبار أو يستخدمونها بنبرة أمّر.","يربط كثيرون الكلمة بضمير الغواراني «تشي» بمعنى «أنا»، لكن اللغويين يختلفون حول طريقها إلى الإسبانية الأرجنتينية."]},{"heading":"من الحي إلى العالم","paragraphs":["ارتبط اللقب «تشي» بإرنستو غيفارا لأن رفاقه الكوبيين وغيرهم من أمريكا اللاتينية سمعوه يتكلم كالأرجنتينيين، فصار الاسم عالمياً.","الكلمة موجودة أيضاً في الفالنسية كتعبير شكوى، لكن أصلها هناك مختلف ونطقها عادةً مختلف."]}],"de":[{"heading":"Wie es auf der Straße klingt","paragraphs":["Che ist ein Ausruf, mit dem man jemanden anspricht, etwa „hey“ oder „Kumpel“, wie in „che, ¿qué hacés?“. Es steht aber auch mitten im Satz als Signal für Aufmerksamkeit: Ein Busfahrer sagt „che, steig hinten ein“, ohne jemanden anzusehen.","Regional und Generationen unterscheiden sich: Junge Leute in den Städten nutzen es oft, manche Ältere seltener oder mit strengerem Ton.","Viele bringen das Wort mit dem Guaraní-Pronomen che (ich) zusammen, doch der Weg ins argentinische Spanisch ist unter Linguisten umstritten."]},{"heading":"Vom Viertel in die Welt","paragraphs":["Ernesto Guevara wurde von kubanischen und anderen lateinamerikanischen Genossen Che genannt, weil er argentinisch sprach; so wurde der Name weltweit bekannt.","Im Valencianischen gibt es che ebenfalls als Klageausruf, doch Herkunft und Aussprache sind dort anders."]}],"en":[{"heading":"How it sounds on the street","paragraphs":["Che is an interjection used to call or address someone, roughly hey or mate, as in che, ¿qué hacés?. It also appears mid-sentence as an attention marker, so a bus driver can say che, subí at the back without looking at anyone.","Usage varies by region and generation: young people in the cities use it often, while some older speakers use it less or with a sharper tone.","Many link the word to the Guaraní pronoun che (I, me), though linguists debate its path into Argentine Spanish."]},{"heading":"From the neighbourhood to the world","paragraphs":["Ernesto Guevara was nicknamed Che by Cuban and other Latin American comrades because of his Argentine speech, and the name became global.","Che also exists as a Valencian interjection of complaint, unrelated in origin and usually pronounced differently."]}]},"context":{"countries":["AR"],"region":"Buenos Aires and the Pampas","continent":"south-america","languages":["es"],"period":"contemporary"},"tags":["communication","Buenos Aires and the Pampas"],"sources":[{"organization":"Wikipedia","title":{"ar":"Che (interjection)","de":"Che (interjection)","en":"Che (interjection)"},"url":"https://en.wikipedia.org/wiki/Che_(interjection)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Rioplatense Spanish","de":"Rioplatense Spanish","en":"Rioplatense Spanish"},"url":"https://en.wikipedia.org/wiki/Rioplatense_Spanish","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يتحاور صديقان في بوينس آيرس ويبدآن بـ«تشي»، ثم تعود الكلمة ثلاث مرات في دقيقتين، وهي هنا تلفت الانتباه أكثر مما تنادي.","de":"Zwei Freunde in Buenos Aires begrüßen sich mit che und verwenden es in zwei Minuten noch dreimal – es markiert Aufmerksamkeit, nicht nur Anrede.","en":"Two Buenos Aires friends greet each other with che and use it three more times in a two-minute talk; the word marks attention rather than address."},"misunderstanding":{"ar":"يظن كثيرون أن «تشي» تعني الثوري أو الأرجنتيني عموماً، لكنها في الأصل أداة خطاب يومية بسيطة.","de":"Viele halten Che für ein politisches Etikett, dabei ist es zuerst ein alltäglicher Gesprächsmarker.","en":"Many assume che is a political label, but it is first a plain everyday marker of speech."},"comparison":{"ar":"تنتشر «تشي» في الأرجنتين والأوروغواي، لكنها تُعدّ أرجنتينية خارجها؛ وفي الباراغواي تُفهم دون أن تكون أصلية، والإكثار منها بلسان أجنبي يبدو تقليداً.","de":"Che ist in Argentinien und Uruguay verbreitet, außerhalb gilt es als argentinisch; in Paraguay versteht man es, aber es ist nicht heimisch, und zu häufiger Gebrauch durch Fremde wirkt wie Nachahmung.","en":"Che is widespread in Argentina and Uruguay but marked as Argentine elsewhere; in Paraguay it is understood but not native, and overusing it as a foreigner sounds like imitation."},"expression":{"original":"Che, ¿qué hacés?","language":"Español rioplatense","gloss":{"ar":"يا، ماذا تفعل؟","de":"Hey, was machst du?","en":"Hey, what are you doing?"},"usage":{"ar":"تحية غير رسمية بين الأصدقاء في بوينس آيرس، تُقال عند اللقاء أو لبدء حديث.","de":"Lockere Begrüßung unter Freunden in Buenos Aires, beim Treffen oder zum Gesprächsbeginn.","en":"An informal greeting among friends in Buenos Aires, used on meeting or to open a conversation."},"transliteration":"che, que haces?"}},{"id":"lng-078","version":2,"slug":"si-po-the-chilean-particle-that-ends-arguments-and-sentences","contentType":"note","category":"communication","title":{"ar":"«سي بو»: جزيء تشيلي ينهي الجمل والجدال","de":"„Si po“: Chiles Partikel für Antworten und Streit","en":"Si po: the Chilean particle that ends sentences"},"deck":{"ar":"كيف يختصر التشيليون كلامهم ويضيفون نبرة شخصية بكلمة صغيرة واحدة.","de":"Wie Chilenen mit einer kleinen Silbe Sätze beenden und Haltung zeigen.","en":"How a two-letter word lets Chileans agree, insist and sound unmistakably local."},"teaser":{"ar":"في تشيلي تتحول «سي» المجردة إلى إجابة لا تُخطئها الأذن بفضل «بو»، فتصبح الكلمة الصغيرة علامة انتماء ونبرة.","de":"In Chile wird aus einem einfachen „sí“ eine unverkennbar chilenische Antwort: Die Partikel „po“ macht Zustimmung hörbar und persönlich.","en":"In Chile a bare sí becomes an unmistakably Chilean answer once po is attached, carrying emphasis, warmth or a hint of impatience."},"readingMinutes":1,"sections":{"ar":[{"heading":"من «بويس» إلى «بو»","paragraphs":["«بو» جزيء تشيلي مختصر من «بويس»، يلتصق بـ«سي» و«نو» وغيرها: «سي بو»، «نو بو»، «يا بو». يضيف توكيدًا أو نفاد صبر أو دفئًا بحسب النبرة، ويحوّل «سي» المجردة إلى إجابة تشيلية واضحة.","يتحدث التشيليون بسرعة ويحذفون الأصوات الأخيرة، فتصير «كومو إستاس؟» إلى «كومو إستاي؟» و«بارا» إلى «با». هذا الاختصار نفسه يجعل «بو» طبيعيًا في الكلام اليومي."]},{"heading":"كلمة في الشارع والمدرسة","paragraphs":["«بو» مرفوض في الكتابة الرسمية وفي المدرسة، لكنه عادي في الكلام بين كل الطبقات، ويظهر في إعلانات موجهة إلى الشباب.","كلمة «كاتشار» بمعنى «يفهم» وصلت من الإنكليزية «كاتش»، واكتسبت معاني تشيلية خاصة بها. وتختلف كثافة استخدام «بو» بحسب الطبقة والمنطقة والجيل، فيكثر عند الشباب في سانتياغو وفالبارايسو."]}],"de":[{"heading":"Von „pues“ zu „po“","paragraphs":["„Po“ ist eine chilenische Partikel, verkürzt aus „pues“, die an „sí“, „no“ und andere Wörter andockt: „sí po“, „no po“, „ya po“. Je nach Ton fügt sie Nachdruck, Ungeduld oder Wärme hinzu und macht aus einem kahlen „sí“ eine klar chilenische Antwort.","Chilenen sprechen schnell und lassen Endungen weg: „¿cómo estás?“ wird zu „¿cómo estai?“, „para“ zu „pa“. Dieselbe Kürzung macht „po“ im Alltag selbstverständlich."]},{"heading":"Im Laden und in der Schule","paragraphs":["In formeller Schrift und in der Schule gilt „po“ als stigmatisiert, im Gespräch ist es jedoch über alle Klassen hinweg normal und erscheint in Werbung für junge Chilenen.","Das Wort „cachar“ für „verstehen“ kam über englisch „catch“ ins chilenische Spanisch und entwickelte eigene Bedeutungen. Wie stark „po“ fällt, hängt von Klasse, Region und Generation ab, besonders häufig ist es bei Jüngeren in Santiago und Valparaíso."]}],"en":[{"heading":"From pues to po","paragraphs":["Po is a Chilean particle shortened from pues, and it attaches to yes, no and other words: si po, no po, ya po. It adds emphasis, impatience or warmth depending on tone, and it can turn a bare si into an unmistakably Chilean answer.","Chilean Spanish also drops final s and consonant clusters, so como estas? becomes como estai? and para becomes pa. That same habit of trimming sounds makes po feel natural in everyday speech."]},{"heading":"In shops and in school","paragraphs":["Po is stigmatised in formal writing and school, but it is normal in speech across classes and appears in advertising aimed at young Chileans.","The word cachar, to get it or understand, came into Chilean Spanish from English catch and now has its own Chilean meanings. How heavily po is used varies by class, region and generation, and it is especially common among younger speakers in Santiago and Valparaiso."]}]},"context":{"countries":["CL"],"region":"Central Chile (Santiago, Valparaiso)","continent":"south-america","languages":["es"],"period":"contemporary"},"tags":["communication","Central Chile (Santiago, Valparaiso)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Chilean Spanish","de":"Chilean Spanish","en":"Chilean Spanish"},"url":"https://en.wikipedia.org/wiki/Chilean_Spanish","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Spanish language","de":"Spanish language","en":"Spanish language"},"url":"https://en.wikipedia.org/wiki/Spanish_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يجيب بائع في سانتياغو «سي بو» على زبون يسأل إن كان المتجر مفتوحًا، فيحمل الجزيء معنى «نعم» ومعنى المفاجأة الخفيفة من طرح السؤال.","de":"Ein Händler in Santiago antwortet einer Kundin, die fragt, ob der Laden offen sei, mit „sí po“ – das bedeutet Ja und zugleich leichte Verwunderung, dass man überhaupt fragen musste.","en":"A Santiago shopkeeper answers si po to a customer who asks whether the shop is open, and the particle conveys both yes and mild surprise that the question needed asking."},"misunderstanding":{"ar":"يعتقد بعض الدارسين أن «بو» مجرد حشو، لكنه يحمل نبرة اجتماعية دقيقة، وحذفه قد يجعل الإجابة جافة أو غريبة.","de":"Manche halten „po“ für bloßes Füllwort, doch es trägt eine feine soziale Nuance; ohne es wirkt eine Antwort leicht kühl.","en":"Some learners treat po as mere filler, but it carries a precise social tone; leaving it out can make an answer sound oddly flat."},"comparison":{"ar":"يشبه «بو» أدوات توكيد محلية في لغات أخرى، لكنه نادر خارج تشيلي، لذا لا يلتقي به المتعلم إلا في الكلام ووسائل التواصل.","de":"Ähnliche Betonungspartikeln gibt es in vielen Sprachen, doch „po“ ist außerhalb Chiles selten, sodass Lernende es fast nur im Gespräch und in sozialen Medien hören.","en":"Po is general in Chile but rare elsewhere in Latin America, and its intensity varies by class and region; formal writing removes it, so learners meet it only in speech and social media."},"expression":{"original":"Sí po","language":"Español chileno","gloss":{"ar":"نعم، بالطبع","de":"ja, klar","en":"yeah, of course"},"usage":{"ar":"تُقال ردًا سريعًا على سؤال واضح، بنبرة ودّية أو بقليل من نفاد الصبر.","de":"Schnelle Antwort auf eine eindeutige Frage, freundlich oder mit leichter Ungeduld.","en":"A quick reply to an obvious question, friendly or faintly impatient depending on tone."},"transliteration":"si po"}},{"id":"lng-079","version":2,"slug":"allillanchu-quechua-and-the-evidence-suffixes-that-say-how-you-know","contentType":"note","category":"languages","title":{"ar":"كيف تقول الكيتشوا ما تعرفه","de":"Wie Quechua sagt, woher man es weiß","en":"How Quechua Says How You Know"},"deck":{"ar":"في مرتفعات الأنديز، تحمل اللغة أدلة على مصدر المعرفة، فيميّز المتحدث بين ما رآه وما سمع به.","de":"Im Andenhochland trägt die Sprache den Beleg in sich: Sprecher unterscheiden, was sie sahen und was ihnen berichtet wurde.","en":"In the Andean highlands the language carries its evidence along: speakers mark whether they saw something or only heard about it."},"teaser":{"ar":"عائلة لغات الكيتشوا يتحدثها الملايين في بيرو وبوليفيا والإكوادور، وفيها لواحق تحدّد هل رأيت الأمر أم نُقل إليك.","de":"Quechua ist eine Sprachfamilie mit mehreren Millionen Sprechern in Peru, Bolivien und Ecuador, deren Suffixe die Wissensquelle markieren.","en":"Quechua is a family of languages spoken by millions in Peru, Bolivia and Ecuador, with suffixes that show where knowledge comes from."},"readingMinutes":1,"sections":{"ar":[{"heading":"لغة تُبنى باللواحق","paragraphs":["الكيتشوا عائلة من لغات مترابطة يتحدثها عدة ملايين في بيرو وبوليفيا والإكوادور، وهي رسمية في الدول الثلاث. تُركّب الكلمات بإضافة لواحق تدل على من فعل ماذا بمن، فترتيب الكلمات أقل أهمية مما هو في الإسبانية.","تختلف اللهجات بين كوسكو وأياكوتشو والإكوادور اختلافاً كبيراً، ويبقى كثير من المتحدثين ثنائيي اللغة مع الإسبانية. كما تتباين المفردات بين الأجيال، إذ يمزج الشباب في المدن الإسبانية بكيتشوا الأجداد."]},{"heading":"دليل على المعرفة","paragraphs":["تسجّل الكيتشوا مصدر المعلومة: لاحقة تقول إن المتحدث رأى الشيء بنفسه، وأخرى تقول إن الخبر نُقل إليه أو استُنتج.","سؤال Allillanchu? يعني هل أنت بخير، وجوابه allillanmi يحمل لاحقة الدليل المباشر، أي إن المتحدث يعرف من تجربته.","تظل ثلاثية الإنكا الأخلاقية ama sua, ama llulla, ama quella تُقتبس بالكيتشوا والإسبانية في أنحاء الأنديز."]}],"de":[{"heading":"Eine Sprache aus Suffixen","paragraphs":["Quechua ist eine Familie verwandter Sprachen, die mehrere Millionen Menschen in Peru, Bolivien und Ecuador sprechen; in allen drei Staaten ist sie offiziell. Sie ist agglutinierend und fügt Suffixe für wer, was und wem hinzu, sodass die Wortstellung weniger wiegt als im Spanischen.","Die Varianten von Cusco, Ayacucho und Ecuador unterscheiden sich erheblich, und viele Sprecher sind zweisprachig mit Spanisch. Auch zwischen Generationen verschiebt sich der Wortschatz, wenn jüngere Städter spanische Wörter einmischen."]},{"heading":"Der Beleg im Satz","paragraphs":["Quechua markiert die Informationsquelle: Ein Suffix sagt, dass der Sprecher etwas direkt gesehen hat, ein anderes, dass es berichtet oder erschlossen wurde.","Allillanchu? fragt, ob jemand wohlauf ist, und die Antwort allillanmi enthält das Direktbeleg-Suffix, also den Anspruch, aus Erfahrung zu wissen.","Die inkaische Moralformel ama sua, ama llulla, ama quella – nicht stehlen, nicht lügen, nicht faul sein – wird in den Anden bis heute auf Quechua und Spanisch zitiert."]}],"en":[{"heading":"A language built from suffixes","paragraphs":["Quechua is a family of related languages spoken by several million people in Peru, Bolivia and Ecuador and is official in all three states. It is agglutinative and adds suffixes for who did what to whom, so word order carries less weight than in Spanish.","Cusco, Ayacucho and Ecuadorian varieties differ substantially, and many speakers are bilingual in Spanish. Vocabulary also shifts between generations, as younger city dwellers mix Spanish into the Quechua of their grandparents."]},{"heading":"Evidence inside the sentence","paragraphs":["Quechua marks information source: one suffix says the speaker saw something directly, another that it was reported or inferred.","Allillanchu? asks whether someone is well, and the answer allillanmi includes the direct-evidence suffix, claiming knowledge from experience.","The Inca moral triad ama sua, ama llulla, ama quella — do not steal, do not lie, do not be lazy — is still quoted in Quechua and Spanish across the Andes."]}]},"context":{"countries":["PE","BO","EC"],"region":"Andean highlands (Cusco, Puno, La Paz, Otavalo)","continent":"south-america","languages":["qu","es"],"period":"contemporary"},"tags":["languages","Andean highlands (Cusco, Puno, La Paz, Otavalo)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Quechua","de":"Quechua","en":"Quechua"},"url":"https://en.wikipedia.org/wiki/Quechua","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Quechuan languages","de":"Quechuan languages","en":"Quechuan languages"},"url":"https://en.wikipedia.org/wiki/Quechuan_languages","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"بائعة في سوق كوسكو تصف شائعة ف تضيف لاحقة الخبر المنقول، فيفهم الزبون المحلي أنها لم تشهد الحادثة، مع أن ترجمتها الإسبانية لا تحمل هذا التحذير.","de":"Eine Marktverkäuferin in Cusco schildert ein Gerücht und setzt das Berichtet-Suffix; die einheimische Kundin versteht, dass sie nicht dabei war, obwohl ihre spanische Übersetzung keine solche Warnung enthält.","en":"A Cusco market seller describing a rumour adds the reported-evidence suffix, and a local customer understands that she did not witness the event although the Spanish translation she gives contains no such warning."},"misunderstanding":{"ar":"قد يظن المستمع الإسباني أن الجملة مجرد خبر محايد، بينما اللاحقة تنبّهه إلى أن المتحدث لم يرَ الأمر بنفسه.","de":"Ein spanischsprachiger Zuhörer hält den Satz für eine neutrale Aussage, während das Suffix signalisiert, dass der Sprecher es nicht selbst gesehen hat.","en":"A Spanish-speaking listener may take the sentence as a neutral report, while the suffix warns that the speaker did not see the event personally."},"comparison":{"ar":"حيث تكتفي الإسبانية بفعل واحد، تضيف الكيتشوا لواحق تحدد الفاعل والمفعول ومصدر المعلومة معاً.","de":"Wo das Spanische mit einem Verb auskommt, fügt Quechua Suffixe an, die Handelnde, Betroffene und Wissensquelle zugleich kennzeichnen.","en":"Where Spanish uses a single verb, Quechua stacks suffixes that mark agent, object and the source of knowledge at once."},"expression":{"original":"Allillanchu?","language":"Runa Simi (Quechua)","gloss":{"ar":"هل أنت بخير؟","de":"Geht es dir gut?","en":"are you well?"},"usage":{"ar":"تحية تُقال عند اللقاء، ويُجاب عنها بـ allillanmi مع لاحقة الدليل المباشر.","de":"Gruß beim Zusammentreffen; geantwortet wird mit allillanmi samt Direktbeleg-Suffix.","en":"A greeting on meeting someone; the reply allillanmi carries the direct-evidence suffix."},"transliteration":"allillanchu?"}},{"id":"lng-080","version":2,"slug":"kamisaraki-aymara-the-language-where-the-past-may-be-in-front-of-you","contentType":"note","category":"languages","title":{"ar":"أيمارا: لغة يعيش فيها الماضي أمامك","de":"Aymara: eine Sprache, in der die Vergangenheit vorn liegt","en":"Aymara: the language where the past sits ahead"},"deck":{"ar":"على هضبة الألتيبلانو يتحدث الناس الأيمارا كل يوم، ويربطون الزمن بما يرونه ويسمعونه ويستنتجونه من الكلام نفسه.","de":"Im Altiplano sprechen Menschen täglich Aymara und verbinden Zeit mit dem, was sie sehen, hören oder aus dem Gesagten schließen.","en":"On the Altiplano people greet each other daily in Aymara and tie time to what they see, hear or infer from the words themselves."},"teaser":{"ar":"تحية واحدة تكفي لبدء الحديث في لاباز وبونو: كاميساراكي؟ ثم واليكي. لكن تحت هذه البساطة تقف قواعد دقيقة عن مصدر المعرفة.","de":"Ein Wort genügt, um ins Gespräch zu kommen: Kamisaraki? Und die Antwort waliki. Doch hinter dieser Schlichtheit stehen genaue Regeln über die Quelle des Wissens.","en":"One word opens a conversation: Kamisaraki? And the answer waliki. Behind that simplicity sit precise rules about where knowledge comes from."},"readingMinutes":1,"sections":{"ar":[{"heading":"تحية تفتح اليوم","paragraphs":["في حافلات إل ألتو وأسواق بونو يبدأ الناس الحديث بكاميساراكي؟ أي كيف حالك، ويجيب الطرف الآخر واليكي أي بخير. هذه التحية اليومية تعبر حدود بوليفيا وبيرو، ويستخدمها الجيران في أريكا التشيلية أيضاً.","الأيمارا لغة رسمية في بوليفيا إلى جانب الإسبانية ولغات السكان الأصليين الأخرى المعترف بها في دستور 2009. ومع ذلك يخلط كثير من المتحدثين الحضريين بينها وبين الإسبانية في الجملة الواحدة.","يختلف الاستخدام بين الأجيال والمناطق: فقد يفتح كبار السن الحوار بالأيمارا في السوق، بينما يكتفي الشباب في المدن بتحية قصيرة ثم يتحولون إلى الإسبانية."]},{"heading":"ما يقوله الفعل عن مصدر الخبر","paragraphs":["مثل الكيتشوا، تحمل لغة الأيمارا علامات على الفعل تبين هل رأى المتحدث الحدث أم سمعه أم استنتجه. فالجملة نفسها تتغير بحسب مصدر المعرفة لا بحسب الحدث وحده.","يرى بعض اللغويين أن الأيمارا تضع الماضي أمام المتحدث والمستقبل خلفه، لأن الماضي معروف ومرئي أما المستقبل فمجهول. هذه الفكرة مبنية على دراسات الإيماءات وهي محل جدل، ولا تعني أن المتحدثين يعيشون الزمن بطريقة مختلفة.","تشترك الأيمارا والكيتشوا في مفردات كثيرة بفعل قرون من التواصل، لكنهما تنتميان إلى عائلتين لغويتين مختلفتين ولا يفهم متحدثوهما بعضهم بعضاً تلقائياً."]}],"de":[{"heading":"Ein Gruß eröffnet den Tag","paragraphs":["In den Bussen von El Alto und auf den Märkten von Puno beginnt das Gespräch mit Kamisaraki?, also wie geht es dir, und die Antwort lautet waliki, mir geht es gut. Dieser Alltagsgruß reicht über Bolivien und Peru hinaus und wird auch von Nachbarn im chilenischen Arica benutzt.","Aymara ist in Bolivien neben Spanisch und den anderen in der Verfassung von 2009 anerkannten indigenen Sprachen eine Amtssprache. Viele städtische Sprecher mischen Aymara und Spanisch jedoch innerhalb eines Satzes.","Der Gebrauch unterscheidet sich nach Region und Generation: Ältere eröffnen das Gespräch auf dem Markt oft auf Aymara, während Jüngere in den Städten kurz grüßen und dann zum Spanischen wechseln."]},{"heading":"Was das Verb über die Quelle verrät","paragraphs":["Wie das Quechua markiert Aymara am Verb, ob der Sprecher ein Ereignis gesehen, gehört oder erschlossen hat. Derselbe Satz verändert sich also je nach Wissensquelle, nicht nur je nach Ereignis.","Manche Linguisten argumentieren, Aymara lege die Vergangenheit vor den Sprecher und die Zukunft hinter ihn, weil die Vergangenheit bekannt und sichtbar ist, die Zukunft aber nicht. Diese Idee beruht auf Gestenstudien, ist umstritten und bedeutet nicht, dass Sprecher Zeit anders erleben.","Aymara und Quechua teilen durch jahrhundertelangen Kontakt viel Wortschatz, gehören aber zu verschiedenen Sprachfamilien und sind nicht gegenseitig verständlich."]}],"en":[{"heading":"A greeting that opens the day","paragraphs":["On El Alto buses and in Puno markets people start talking with Kamisaraki?, how are you, and the other person answers waliki, fine. The everyday greeting crosses the Bolivian and Peruvian altiplano and is also used by neighbours in Chilean Arica.","Aymara is an official language of Bolivia alongside Spanish and the other indigenous languages recognised in the 2009 constitution. Yet many urban speakers mix Aymara and Spanish inside a single sentence.","Usage shifts by region and generation: older people may open a market conversation in Aymara, while younger city dwellers offer a short greeting and then switch to Spanish."]},{"heading":"What the verb says about the source","paragraphs":["Like Quechua, Aymara marks evidentiality on the verb, so a speaker states whether an event was seen, heard or inferred. The same sentence changes with the source of knowledge, not only with the event.","Some linguists have argued that Aymara places the past in front of the speaker and the future behind, because the past is known and visible while the future is not. The claim rests on gesture studies and is debated; it does not mean speakers experience time differently.","Aymara and Quechua share vocabulary through centuries of contact, but they belong to different language families and are not mutually intelligible."]}]},"context":{"countries":["BO","PE","CL"],"region":"Altiplano (La Paz, Oruro, Puno, Arica)","continent":"south-america","languages":["ay","es"],"period":"contemporary"},"tags":["languages","Altiplano (La Paz, Oruro, Puno, Arica)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Aymara language","de":"Aymara language","en":"Aymara language"},"url":"https://en.wikipedia.org/wiki/Aymara_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Aymara people","de":"Aymara people","en":"Aymara people"},"url":"https://en.wikipedia.org/wiki/Aymara_people","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"سائق حافلة في إل ألتو يشير إلى الأمام وهو يتحدث عن قرية جده، وإلى الخلف وهو يتحدث عن خطط السنة القادمة، وتوافق إيماءته صيغ الفعل التي يستخدمها.","de":"Ein Busfahrer in El Alto zeigt nach vorn, wenn er vom Dorf seines Großvaters spricht, und nach hinten, wenn er die Pläne für nächstes Jahr erwähnt – die Geste passt zu den Verbformen, die er benutzt.","en":"An El Alto bus driver points forward when talking about his grandfather's village and backward when talking about next year's plans, and the gesture matches the verb forms he is using."},"misunderstanding":{"ar":"الخلط الشائع أن الأيمارا تعني أن أهلها لا يرون المستقبل، والحقيقة أن المسألة استعارة في الإيماءات والكلام لا اختلاف في الإحساس بالزمن.","de":"Häufig wird angenommen, Aymara-Sprecher sähen keine Zukunft. Tatsächlich handelt es sich um eine Metapher in Gestik und Rede, nicht um ein anderes Zeitempfinden.","en":"A common mix-up is to think Aymara means its speakers cannot picture the future. In fact it is a metaphor in gesture and speech, not a different sense of time."},"comparison":{"ar":"حيث تضع الإنجليزية الماضي خلف المتحدث في التصور الشائع، تضع الأيمارا المعلوم أمامه، فيصبح الاتجاه في الإيماءة جزءاً من المعنى.","de":"Wo das Englische die Vergangenheit im gängigen Bild hinter den Sprecher legt, stellt Aymara das Bekannte nach vorn – die Richtung der Geste wird Teil der Bedeutung.","en":"Where English conventionally puts the past behind the speaker, Aymara places what is known in front, so the direction of a gesture becomes part of the meaning."},"expression":{"original":"Kamisaraki?","language":"Aymar aru (Aymara)","gloss":{"ar":"كيف حالك؟","de":"wie geht es dir?","en":"how are you?"},"usage":{"ar":"تحية يومية تقال عند اللقاء في السوق أو الحافلة أو الشارع، ويجاب عليها عادة بـ واليكي.","de":"Alltagsgruß bei der Begegnung auf dem Markt, im Bus oder auf der Straße; die übliche Antwort ist waliki.","en":"An everyday greeting on meeting in the market, on the bus or in the street; the usual answer is waliki."},"transliteration":"kamisaraki?"}},{"id":"lng-081","version":2,"slug":"mba-eichapa-paraguayan-guarani-and-the-mixed-speech-that-holds-the-country-toget","contentType":"note","category":"languages","title":{"ar":"الغواراني في باراغواي: لغة تجمع البلد","de":"Guaraní in Paraguay: die Sprache, die das Land verbindet","en":"Mba'eichapa: the language that holds Paraguay together"},"deck":{"ar":"في باراغواي لغة أصلية يتحدثها أغلب الناس، وتختلط بالإسبانية في حديث يومي يسمّونه جوبارا.","de":"In Paraguay spricht die Mehrheit eine indigene Sprache, und in Asunción mischt sich Guaraní mit Spanisch zu Jopara.","en":"Most Paraguayans speak an indigenous language, and in Asunción it blends with Spanish into everyday Jopara."},"teaser":{"ar":"الغواراني لغة مشتركة رسمية مع الإسبانية، يتحدثها رؤساء وسائقو حافلات، وتتغير بين المدينة والريف.","de":"Guaraní ist neben Spanisch Amtssprache, Präsidenten und Busfahrer grüßen damit, und Stadt und Land klingen verschieden.","en":"Guaraní is co-official with Spanish, presidents and bus drivers greet with it, and its sound shifts between city and countryside."},"readingMinutes":1,"sections":{"ar":[{"heading":"لغة الشارع والرئاسة","paragraphs":["الغواراني لغة مشتركة رسمية مع الإسبانية في باراغواي، ويتحدثها أغلب السكان، بينهم كثيرون لا يعرّفون أنفسهم كسكان أصليين.","عبارة «مبايتشابا؟» هي السؤال العادي عن الحال، ويُجاب عليها «إيبورا»، ويستخدمها الرؤساء وسائقو الحافلات على حد سواء.","في البلد دستور 1992 جعل الغواراني رسمياً، وهي الحالة الوحيدة في الأمريكتين التي يتحدث فيها أغلبية السكان لغة أصلية."]},{"heading":"كيف يمتزج الكلام","paragraphs":["في أسونسيون يسمّون الكلام المخلوط «جوبارا»، حيث تدخل الأسماء والأفعال الإسبانية في قواعد الغواراني ونطقه.","الغواراني لغة تجميعية غنية بالحركات الأنفية، وتميّز بين «نحن» الشاملة و«نحن» الحصرية، وهو تمييز لا تعرفه الإسبانية.","يختلف الاستخدام بين الأجيال والمناطق: عائلات المدن المتوسطة قد تتحدث إسبانية أكثر في البيت، ومجتمعات الغواراني الأصلية لها لهجاتها الخاصة."]}],"de":[{"heading":"Sprache von Straße und Regierung","paragraphs":["Guaraní ist in Paraguay neben Spanisch Amtssprache, und die große Mehrheit der Bevölkerung spricht es, darunter viele, die sich nicht als indigen bezeichnen.","Mba'eichapa? ist das gewöhnliche Wie geht's, geantwortet wird ipora, und Präsidenten wie Busfahrer benutzen es gleichermaßen.","Die Verfassung von 1992 machte Guaraní offiziell; Paraguay ist das einzige Land Amerikas, in dem eine indigene Sprache von der Mehrheit gesprochen wird."]},{"heading":"Wie die Mischung klingt","paragraphs":["In Asunción heißt die gemischte Rede Jopara: spanische Nomen und Verben werden in guaranitische Grammatik und Aussprache eingepasst.","Guaraní ist agglutinierend und reich an Nasalvokalen; es unterscheidet ein inklusives und ein exklusives Wir, was dem Spanischen fehlt.","Der Gebrauch variiert regional und generationell: Mittelschichtsfamilien in der Stadt sprechen zu Hause oft mehr Spanisch, indigene Guaraní-Gemeinschaften haben eigene Varietäten."]}],"en":[{"heading":"A language of street and state","paragraphs":["Guaraní is co-official with Spanish in Paraguay, and a large majority of the population speaks it, including many people who do not identify as indigenous.","Mba'eichapa? is the ordinary how are you, answered ipora, and it is used by presidents and bus drivers alike.","Paraguay made Guaraní official in the 1992 constitution, and it is the only country in the Americas where an indigenous language is spoken by a majority."]},{"heading":"How the mixing works","paragraphs":["Jopara is the mixed Guarani-Spanish speech of Asunción, in which Spanish nouns and verbs are fitted into Guaraní grammar and pronunciation.","Guaraní is agglutinative and nasal-vowel rich, and it distinguishes inclusive and exclusive we, a distinction Spanish lacks.","Usage varies by region and generation: urban middle-class families may speak more Spanish at home, and indigenous Guaraní communities have their own varieties."]}]},"context":{"countries":["PY"],"region":"Nationwide, especially Asuncion and the countryside","continent":"south-america","languages":["gn","es"],"period":"contemporary"},"tags":["languages","Nationwide, especially Asuncion and the countryside"],"sources":[{"organization":"Wikipedia","title":{"ar":"Guarani language","de":"Guarani language","en":"Guarani language"},"url":"https://en.wikipedia.org/wiki/Guarani_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Jopara","de":"Jopara","en":"Jopara"},"url":"https://en.wikipedia.org/wiki/Jopara","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالبة في أسونسيون تشرح مشكلة هاتفها بالغواراني، تُدخل كلمة إسبانية بمعنى «إشارة» ثم تكمل بالغواراني، وأمها تفهم كل كلمة دون أن تلاحظ التحول.","de":"Eine Studentin in Asunción erklärt ein Handyproblem auf Guaraní, schiebt das spanische Wort für Signal ein und spricht auf Guaraní weiter; ihre Mutter versteht jedes Wort, ohne den Wechsel zu bemerken.","en":"A student in Asunción explains a phone problem in Guaraní, inserts the Spanish word for signal and continues in Guaraní, and her mother understands every word without noticing the switch."},"misunderstanding":{"ar":"الغواراني وجوبارا ليسا الشيء نفسه، ويحتجّ المتشددون على الخلط بينهما.","de":"Guaraní und Jopara sind nicht dasselbe, und Puristen stören sich an der Mischung.","en":"Guaraní and jopara are not the same thing, and purists object to the mixing."},"comparison":{"ar":"حيث تميّز الغواراني بين «نحن» الشاملة والحصرية، تكتفي الإسبانية بضمير واحد.","de":"Wo Guaraní ein inklusives und ein exklusives Wir trennt, kennt das Spanische nur ein Wir.","en":"Where Guaraní separates an inclusive and an exclusive we, Spanish has only one word for we."},"expression":{"original":"Mba'éichapa?","language":"Avañe'ẽ (Guaraní)","gloss":{"ar":"كيف حالك؟","de":"Wie geht es dir?","en":"how are you?"},"usage":{"ar":"تحية يومية عادية، يُجاب عليها «إيبورا» أي بخير.","de":"Alltägliche Begrüßung, üblich beantwortet mit ipora (gut).","en":"The ordinary everyday greeting, usually answered ipora (fine)."},"transliteration":"mba'eichapa?"}},{"id":"lng-082","version":2,"slug":"fa-waka-suriname-s-creole-that-most-of-the-country-actually-speaks","contentType":"language","category":"languages","title":{"ar":"فا واكا: لغة الشارع في سورينام","de":"Fa waka: Surinames Alltagssprache","en":"Fa waka: Suriname's Everyday Creole"},"deck":{"ar":"في باراماريبو يُحيّي الناس بعضهم بلغة الكريول الإنجليزية الأساس، ثم يتحوّلون إلى الهولندية عند ظهور ورقة مكتوبة.","de":"In Paramaribo grüßen sich Kollegen mit fa waka und sprechen Sranan weiter – bis ein Dokument auftaucht und alle ins Niederländische wechseln.","en":"In Paramaribo colleagues greet each other with fa waka and carry on in Sranan, then switch to Dutch the moment a written document appears."},"teaser":{"ar":"السورينامية التونغو هي لسان الحياة اليومية في سورينام، رغم أن الهولندية هي اللغة الرسمية في المدرسة والقانون.","de":"Sranan Tongo ist die eigentliche Verkehrssprache Surinames, obwohl Niederländisch offiziell bleibt und Schule wie Recht beherrscht.","en":"Sranan Tongo is the language most Surinamese actually speak day to day, even though Dutch stays official in school and law."},"readingMinutes":1,"sections":{"ar":[{"heading":"تحية الشارع","paragraphs":["في باراماريبو يبدأ اليوم بعبارة «فا واكا؟» أي كيف تسير الأمور، ويُجاب عليها بـ«مي دي» أو «بون». الضمائر بسيطة: مي، يو، أ، ويُجمع الاسم بـ«دن» كما في «دن سما» أي الناس.","هذه اللغة كريول إنجليزية الأساس نشأت في مزارع القرن السابع عشر، وامتزجت بالبرتغالية والهولندية ولغات غرب أفريقيا، وكلمة «بيكين» أي الطفل يُرجَّح أصلها برتغالي."]},{"heading":"لغة الحياة والورق","paragraphs":["تُستعمل السورينامية في الإذاعة والكنائس والسياسة، واعتُمد هجاؤها المعياري عام 1986، لكن الهولندية تبقى لغة المدرسة والقانون.","يختلف الاستعمال بين الأجيال والمناطق: شباب المدن يخلطونها كثيرًا بالهولندية، بينما تبقى في الريف أقرب إلى شكلها المحكي القديم."]}],"de":[{"heading":"Der Gruß auf der Straße","paragraphs":["In Paramaribo beginnt der Tag mit fa waka?, also „wie läuft's?“, und die Antwort lautet mi de oder bun. Die Pronomen sind einfach: mi, yu und a; Mehrzahl markiert den, wie in den sma, „die Leute“.","Die englischbasierte Kreolsprache entstand auf Plantagen des 17. Jahrhunderts aus Englisch, Portugiesisch, Niederländisch und westafrikanischen Einflüssen; pikin, „Kind“, stammt wohl aus dem Portugiesischen."]},{"heading":"Sprache des Lebens und des Papiers","paragraphs":["Sranan erklingt in Radio, Kirchen und Politik, und 1986 wurde eine Standardorthografie angenommen; Niederländisch bleibt jedoch die Sprache von Schule und Gesetz.","Der Gebrauch variiert regional und Generationen: Stadtjugend mischt viel Niederländisch hinein, auf dem Land bleibt das gesprochene Sranan näher an älteren Formen."]}],"en":[{"heading":"The greeting on the street","paragraphs":["In Paramaribo the day starts with fa waka?, literally 'how is it walking?', answered with mi de, 'I am here', or bun, 'good'. The pronouns are simple: mi, yu and a; plurals take den, as in den sma, 'the people'.","This English-based creole formed on seventeenth-century plantations from English with Portuguese, Dutch and West African input; pikin, 'child', probably comes from Portuguese."]},{"heading":"A language of life and paper","paragraphs":["Sranan is used in radio, churches and politics, and a standard orthography was adopted in 1986, though Dutch remains the language of school and law.","Usage shifts by region and generation: city young people mix in plenty of Dutch, while rural speech stays closer to older forms, and spelling still varies informally."]}]},"context":{"countries":["SR"],"region":"Suriname, especially Paramaribo","continent":"south-america","languages":["srn","nl","en"],"period":"contemporary"},"tags":["languages","Suriname, especially Paramaribo"],"sources":[{"organization":"Wikipedia","title":{"ar":"Sranan Tongo","de":"Sranan Tongo","en":"Sranan Tongo"},"url":"https://en.wikipedia.org/wiki/Sranan_Tongo","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Suriname","de":"Suriname","en":"Suriname"},"url":"https://en.wikipedia.org/wiki/Suriname","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يتحيّا زميلان في باراماريبو بـ«فا واكا» ويتابعان بالسورينامية، ثم ينتقلان إلى الهولندية فور ظهور وثيقة مكتوبة، لأن الورقة تنتمي إلى اللغة الأخرى.","de":"Zwei Kollegen in Paramaribo begrüßen sich mit fa waka und plaudern auf Sranan, wechseln aber ins Niederländische, sobald ein Schriftstück erscheint – das Papier gehört der anderen Sprache.","en":"Two colleagues in Paramaribo greet each other with fa waka and continue in Sranan, then switch to Dutch the moment a written document appears, because the paper belongs to the other language."},"misunderstanding":{"ar":"يظنّ البعض أن الكريول هولندية مشوّهة، لكن السورينامية التونغو قامت أساسًا على الإنجليزية، والهولندية طبقة لاحقة.","de":"Viele halten Kreol für verhunztes Niederländisch, doch Sranan Tongo ruht auf dem Englischen; Niederländisch kam erst später dazu.","en":"Many assume a creole is broken Dutch, but Sranan Tongo is built on English; Dutch was layered on later and never replaced it in daily talk."},"comparison":{"ar":"كما يتحدث المصريون عاميتهم ويكتبون بالفصحى، يتحدث السوريناميون السورينامية ويكتبون بالهولندية في الإدارة.","de":"Ähnlich wie Ägypter Alltagssprache sprechen und Hocharabisch schreiben, sprechen Surinamer Sranan und schreiben Niederländisch in der Verwaltung.","en":"Much like Egyptians chatting in dialect but writing in formal Arabic, Surinamese speak Sranan at home and write Dutch in administration."},"expression":{"original":"Fa waka?","language":"Sranan Tongo","gloss":{"ar":"كيف تسير الأمور؟","de":"Wie läuft's?","en":"how's it going?"},"usage":{"ar":"تحية يومية غير رسمية بين الأصدقاء والزملاء، يُجاب عليها بـ«مي دي» أو «بون».","de":"Alltäglicher, informeller Gruß unter Freunden und Kollegen; Antwort: mi de oder bun.","en":"An everyday, informal greeting between friends and colleagues; answered with mi de or bun."},"transliteration":"fa waka?"}},{"id":"lng-083","version":2,"slug":"kia-ora-the-maori-greeting-that-became-the-country-s-hello","contentType":"scene","category":"communication","title":{"ar":"كيا أورا: تحية الماوري التي أصبحت مرحبًا وطنيًا","de":"Kia ora: Der Māori-Gruß, der zum Landesgruß wurde","en":"Kia ora: the Māori greeting that became the national hello"},"deck":{"ar":"كلمة واحدة تعمل كتحية وشكر وخاتمة خطاب، ويتداولها النيوزيلنديون يوميًا في حديثهم بالإنجليزية.","de":"Ein Wort dient als Hallo, Dank und Redeschluss – und die meisten Neuseeländer nutzen es täglich im englischen Gespräch.","en":"One word works as hello, thanks and a speech closer, and most New Zealanders now use it in English conversation."},"teaser":{"ar":"من حافلات ويلينغتون إلى افتتاح الخطب، تحوّلت تحية الماوري إلى جزء من الحياة اليومية في نيوزيلندا.","de":"Ob im Bus von Wellington oder am Ende einer Rede: Der Māori-Gruß gehört längst zum Alltag in Neuseeland.","en":"From Wellington buses to the end of formal speeches, a Māori greeting has settled into everyday New Zealand life."},"readingMinutes":1,"sections":{"ar":[{"heading":"كلمة واحدة، وظائف كثيرة","paragraphs":["تعني «كيا أورا» كن بخير، وتُستخدم كتحية وكشكر وكخاتمة لخطاب في آن واحد. التحية الرسمية في الماوري تميّز بين «تينا كويه» لشخص واحد و«تينا كوتو» لثلاثة أشخاص أو أكثر.","اليوم يستخدمها معظم النيوزيلنديين داخل محادثاتهم بالإنجليزية، حتى من لا يعرفون كلمة ماوري أخرى. ويختلف الاستخدام بحسب المنطقة والجيل: فالشمال أقرب إلى الاستخدام اليومي، بينما يقتصر عند بعض الشباب على التحية العابرة."]},{"heading":"لغة أُحيت بعد عقوبات","paragraphs":["أصبحت لغة تي ريو ماوري لغة رسمية في نيوزيلندا عام 1987، بعد عقود عوقب فيها الأطفال على التحدث بها في المدرسة.","وفي عام 1982 بدأت حركة «كوهانغا ريو»، وهي رياض أطفال لغوية وضعت كبار السن الناطقين بالماوري مع الصغار، ويُنسب إليها وقف تراجع اللغة بين الأطفال.","طول الحركات الصائتة يغيّر المعنى: «ماوري» بلا علامة تعني عاديًا، و«ماوري» بالعلامة تعني الشعب، وهما كلمتان مختلفتان لا خطأ مطبعي."]}],"de":[{"heading":"Ein Wort, viele Aufgaben","paragraphs":["Kia ora bedeutet „sei wohl“ und funktioniert als Hallo, als Dank und als Abschluss einer Rede. Die formelle Māori-Begrüßung unterscheidet tēnā koe für eine Person und tēnā koutou für drei oder mehr.","Heute verwenden die meisten Neuseeländer kia ora in englischen Gesprächen, auch wer kein weiteres Māori-Wort kennt. Die Nutzung variiert regional und generationell: Auf der Nordinsel ist sie alltäglicher, bei manchen jüngeren Menschen bleibt sie ein flüchtiger Gruß."]},{"heading":"Eine Sprache, die zurückkam","paragraphs":["1987 wurde Te Reo Māori offizielle Sprache Neuseelands – nach Jahrzehnten, in denen Kinder in der Schule fürs Sprechen bestraft wurden.","1982 startete die Bewegung kōhanga reo: Sprachnester, in denen Māori sprechende Ältere mit Vorschulkindern arbeiteten. Ihnen wird zugeschrieben, den Rückgang der Sprache bei kleinen Kindern gestoppt zu haben.","Die Vokallänge zählt: māori mit Makron heißt „gewöhnlich“, Māori bezeichnet das Volk – zwei verschiedene Wörter, kein Tippfehler."]}],"en":[{"heading":"One word, several jobs","paragraphs":["Kia ora means be well and serves as hello, thank you and cheers. Formal Māori greeting separates tēnā koe for one person from tēnā koutou for three or more, and kia ora can close a speech as well as open one.","Most New Zealanders now use it inside English conversation, including people who know no other Māori word. Usage varies by region and generation: it is most routine in the North Island, while some younger speakers keep it to a passing hello."]},{"heading":"A language brought back","paragraphs":["Te reo Māori became an official language of New Zealand in 1987, after decades when children were punished for speaking it at school.","The kōhanga reo movement, started in 1982, placed Māori-speaking elders in preschools and is credited with halting the language's decline among young children.","Vowel length matters: māori with macrons means ordinary, while Māori means the people — different words, not a typo."]}]},"context":{"countries":["NZ"],"region":"Nationwide, strongest in the North Island","community":"Maori communities","continent":"oceania","languages":["mi","en"],"period":"contemporary"},"tags":["communication","Nationwide, strongest in the North Island"],"sources":[{"organization":"Wikipedia","title":{"ar":"Māori language","de":"Māori language","en":"Māori language"},"url":"https://en.wikipedia.org/wiki/M%C4%81ori_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Kia ora","de":"Kia ora","en":"Kia ora"},"url":"https://en.wikipedia.org/wiki/Kia_ora","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"سائق حافلة في ويلينغتون يقول «كيا أورا» لكل راكب، فيرد عليه نحو نصفهم بالتحية نفسها، بينهم من لا يعرف كلمة ماوري أخرى.","de":"Ein Busfahrer in Wellington sagt zu jedem Fahrgast kia ora und bekommt von etwa der Hälfte ein kia ora zurück, auch von Leuten ohne weitere Māori-Kenntnisse.","en":"A Wellington bus driver says kia ora to every passenger and gets a kia ora back from about half of them, including people who speak no other Māori word."},"misunderstanding":{"ar":"كثيرون يظنون أن العلامة فوق الحرف خطأ مطبعي، لكنها تغيّر معنى الكلمة تمامًا.","de":"Viele halten das Makron für einen Tippfehler, dabei verändert es die Bedeutung des Wortes.","en":"Many read the macron as a typo, but it changes which word is meant."},"comparison":{"ar":"مثل تحية «شالوم» التي تحمل معنى السلام وتُستخدم للفتح والختام، تعمل «كيا أورا» كتحية وشكر في الوقت نفسه.","de":"Ähnlich wie „Shalom“ als Gruß und Friedenswunsch zugleich dient kia ora als Begrüßung, Dank und Schlussformel.","en":"Like shalom, which greets and wishes peace at once, kia ora both opens and closes an exchange."},"expression":{"original":"Kia ora","language":"Te Reo Māori","gloss":{"ar":"مرحبًا / كن بخير","de":"Hallo / sei wohl","en":"hello / be well"},"usage":{"ar":"تحية يومية تُقال عند اللقاء والوداع، وتُستخدم أيضًا للشكر وخاتمة الخطاب.","de":"Alltagsgruß beim Kommen und Gehen, auch als Dank und zum Abschluss einer Rede.","en":"Everyday greeting on meeting and parting, also used for thanks and to close a speech."},"transliteration":"kia ora"}},{"id":"lng-084","version":2,"slug":"whakapapa-the-genealogy-that-is-recited-rather-than-researched","contentType":"note","category":"languages","title":{"ar":"شجرة النسب التي تُتلى لا تُبحث","de":"Die Ahnenreihe, die man rezitiert","en":"The genealogy you recite, not research"},"deck":{"ar":"الـ«فاكابابا» ليست أرشيفاً يُقرأ بل طبقات تُروى بصوت عالٍ لتحدد موقع الإنسان أمام الناس والأرض.","de":"Whakapapa ist kein Archiv zum Nachschlagen, sondern Schicht um Schicht, laut gesprochen vor Menschen und Land.","en":"Whakapapa is not an archive you open but layers you speak aloud, placing a person before people and land."},"teaser":{"ar":"في الماريه يُسمّي المتحدث أسلافه وجباله وأنهاره، فيعرف الحاضرون فوراً كيف يتصل بهم ومن أين جاء.","de":"Auf dem Marae nennt eine Sprecherin Vorfahren und Berge – und alle Anwesenden wissen sofort, wie sie mit ihnen verbunden ist.","en":"On the marae a speaker names ancestors and mountains, and the room instantly knows how the visitor is connected to those already seated."},"readingMinutes":1,"sections":{"ar":[{"heading":"طبقات تُروى بصوت عالٍ","paragraphs":["كلمة «فاكابابا» تعني وضع الشيء في طبقات، وهي تسمّي النسب وفعل تلاوته معاً. فهي لا تسرد عائلة فحسب، بل تربط الشخص بأسلافه وبالأرض والأنهار والجبال، وتؤسس حقوقاً وواجبات لا مجرد تاريخ.","تحدث التلاوة الرسمية في الماريه، حيث يذكر المتحدث الأسلاف والمعالم ليحدد موقع المجموعة الزائرة. ويختلف الإيقاع بين الأجيال والمناطق: من نشأ بعيداً عن ماريه عائلته قد يتعلم نسبه في سن متأخرة."]},{"heading":"من الماريه إلى الكلام اليومي","paragraphs":["تطول التلاوة أو تقصر بحسب المناسبة، فقد يعطي الشخص نفسه نسخة من دقيقتين أو من عشرين دقيقة، وهذا اختيار واعٍ لا نقص في الحفظ.","وقد انتقل المصطلح إلى الإنجليزية النيوزيلندية الواسعة، فيتحدث الناس عن «فاكابابا» سياسة أو بناء أو جين. لكن معرفة النسب تحتفظ بها عائلات بعينها وليست دائماً عامة، ويُنتقد استخدام الكلمة لنسب غير ماوري."]}],"de":[{"heading":"Schichten, laut gesprochen","paragraphs":["Whakapapa bedeutet, etwas in Schichten zu legen, und bezeichnet sowohl die Genealogie als auch das Rezitieren. Sie verbindet einen Menschen mit Vorfahren, Land, Flüssen und Bergen und begründet Rechte und Pflichten, nicht nur Familiengeschichte.","Die formelle Rezitation findet auf dem Marae statt, wo ein Sprecher Vorfahren und Landmarken nennt, um die besuchende Gruppe zu verorten. Je nach Region und Generation unterscheidet sich die Praxis: Wer fern vom Marae der Familie aufwuchs, lernt die eigene Whakapapa oft erst als Erwachsener."]},{"heading":"Vom Marae in den Alltag","paragraphs":["Die Rezitation wird je nach Anlass gekürzt oder erweitert; dieselbe Person gibt eine Zwei-Minuten- oder eine Zwanzig-Minuten-Version.","Der Begriff ist ins neuseeländische Englisch übergegangen, wo man von der Whakapapa einer Politik, eines Gebäudes oder Gens spricht. Doch Wissen um Whakapapa gehört bestimmten Familien und ist nicht immer öffentlich; die Nutzung für nicht-maorische Genealogie wird kritisiert."]}],"en":[{"heading":"Layers spoken aloud","paragraphs":["Whakapapa means to place in layers, and it names both a genealogy and the act of reciting it. It connects a person to ancestors, land, rivers and mountains, establishing rights and obligations rather than only family history.","Formal recitation happens on the marae, where a speaker names ancestors and landmarks to locate the visiting group. Practice varies by region and generation: urban Maori who grew up outside their marae may be learning their own whakapapa as adults."]},{"heading":"From the marae into everyday speech","paragraphs":["The recitation is shortened or expanded according to the occasion, so the same person may give a two-minute or a twenty-minute version.","The term has moved into wider New Zealand English, where people speak of the whakapapa of a policy, a building or a gene. But whakapapa knowledge is held by particular families and is not always public, and misuse of the term for non-Maori genealogy is criticised."]}]},"context":{"countries":["NZ"],"region":"Nationwide","community":"Maori communities","continent":"oceania","languages":["mi","en"],"period":"contemporary"},"tags":["languages","Nationwide"],"sources":[{"organization":"Wikipedia","title":{"ar":"Whakapapa","de":"Whakapapa","en":"Whakapapa"},"url":"https://en.wikipedia.org/wiki/Whakapapa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Māori language","de":"Māori language","en":"Māori language"},"url":"https://en.wikipedia.org/wiki/M%C4%81ori_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"باحثة ماورية شابة تعرّف بنفسها في لقاء، فتسمّي جبلها ونهرها وسلفها قبل جامعتها، فيعرف الحاضرون كيف تتصل بمن جلسوا قبلها.","de":"Eine junge maorische Forscherin stellt sich bei einem Hui vor und nennt zuerst Berg, Fluss und Vorfahren, dann ihre Universität – der Raum weiß nun, wie sie mit den Sitzenden verbunden ist.","en":"A young Maori researcher introducing herself at a hui names her mountain, river and ancestor before her university, and the room now knows how she is connected to the people already seated."},"misunderstanding":{"ar":"يظن البعض أن «فاكابابا» مجرد شجرة عائلة يمكن البحث عنها في السجلات، لكنها في الأصل تلاوة حيّة تحمل التزامات.","de":"Manche halten Whakapapa für einen Stammbaum, den man in Archiven erforscht, doch sie ist eine lebendige Rezitation mit Verpflichtungen.","en":"Some assume whakapapa is a family tree to be researched in records, but it is a living recitation that carries obligations."},"comparison":{"ar":"حيث تُحفظ الأنساب في وثائق تُفتح عند الحاجة، تُحفظ «فاكابابا» في الذاكرة والصوت وتُعاد في كل مناسبة.","de":"Wo Ahnenreihen in Dokumenten ruhen, bis man sie öffnet, lebt Whakapapa in Stimme und Gedächtnis und wird bei jeder Gelegenheit erneuert.","en":"Where genealogies sit in documents until opened, whakapapa lives in voice and memory and is renewed at each occasion."},"expression":{"original":"Whakapapa","language":"Te Reo Māori","gloss":{"ar":"نسب / أصل متطبق","de":"Genealogie / geschichtete Abstammung","en":"genealogy / layered descent"},"usage":{"ar":"تُقال عند التعريف بالنفس في الماريه أو اللقاءات، ولها استخدام واسع في النيوزيلندية.","de":"Wird bei der Selbstvorstellung auf dem Marae und in Treffen verwendet, auch im weiteren neuseeländischen Englisch.","en":"Used when introducing oneself on the marae and at gatherings, and widely in New Zealand English."},"transliteration":"whakapapa"}},{"id":"lng-085","version":2,"slug":"talofa-samoan-greeting-and-the-fa-a-samoa-obligations-behind-it","contentType":"note","category":"communication","title":{"ar":"تالوفا: تحية ساموية والتزامات الفآ ساموا","de":"Talofa: samoanische Begrüßung und die Pflichten der fa'a Samoa","en":"Talofa: a Samoan greeting and its fa'a Samoa duties"},"deck":{"ar":"كيف تنظّم تحية واحدة شبكة القرابة والاحترام والخدمة في المجتمع الساموي.","de":"Wie ein einziges Grußwort Verwandtschaft, Respekt und Dienst im samoanischen Alltag ordnet.","en":"How one everyday word ties together family, respect and service in Samoan life."},"teaser":{"ar":"تالوفا ليست مجرد كلمة مرحباً، بل بابٌ إلى نظام كامل من الاحترام والقرابة والخدمة.","de":"Talofa ist mehr als ein Hallo: Es öffnet die Tür zu einem Geflecht aus Respekt, Familie und gegenseitiger Verpflichtung.","en":"Talofa is more than hello: it opens the door to a whole system of respect, extended family and mutual obligation."},"readingMinutes":1,"sections":{"ar":[{"heading":"كلمة تفتح باباً","paragraphs":["تالوفا هي التحية الساموية العادية، وتقال تالوفا لافا عند مخاطبة جماعة. لكن هذه الكلمة البسيطة تفتح باباً إلى فآ ساموا، أي الطريقة الساموية، التي تنظم الحياة حول العائلة الممتدة (أيغا) ورئيسها الملقّب (ماتاي) وخدمة (تاوتوا) كليهما.","الاحترام محفور في اللغة نفسها: تُستخدم مفردات مستقلة للرؤساء وللخطابة الرسمية، وللكلمات العادية مقابلٌ خاص بالرؤساء."]},{"heading":"الاحترام من بعيد","paragraphs":["تُرسّخ مراسم الأفا اللقاءات بمشروب من جذر الكافا، ويعكس ترتيب التقديم مكانة كل شخص في القرية.","ومع الهجرة إلى نيوزيلندا والولايات المتحدة، يحافظ كثير من العائلات الساموية على فآ ساموا عبر الكنيسة والتحويلات المالية والتزامات القرية عن بُعد.","تختلف هذه الممارسة بين الأجيال والمدن: فالسامويون في المناطق الحضرية والمهاجرون والشباب يتفاوضون على معناها بطرق متباينة."]}],"de":[{"heading":"Ein Wort, das Türen öffnet","paragraphs":["Talofa ist die gewöhnliche samoanische Begrüßung, talofa lava richtet sich an eine Gruppe. Doch das schlichte Wort öffnet den Zugang zur fa'a Samoa, der samoanischen Lebensweise, die das Leben um die aiga (Großfamilie), den matai (Titelhäuptling) und den Dienst (tautua) an beiden ordnet.","Der Respekt ist in der Sprache selbst verankert: Für Häuptlinge und formelle Redekunst gilt ein eigener Wortschatz, und gewöhnliche Wörter haben häuptlingliche Entsprechungen."]},{"heading":"Respekt auf Distanz","paragraphs":["Die 'ava-Zeremonie besiegelt Begegnungen mit einem Getränk aus der Kava-Wurzel, und die Reihenfolge des Servierens spiegelt den Rang im Dorf.","Mit der Migration nach Neuseeland und in die USA halten viele samoanische Familien die fa'a Samoa über Kirche, Geldüberweisungen und Dorfpflichten aus der Ferne aufrecht.","Je nach Region und Generation wird sie unterschiedlich gelebt: Stadtbewohner, Migranten und Jüngere verhandeln ihren Sinn auf eigene Weise."]}],"en":[{"heading":"A word that opens a door","paragraphs":["Talofa is the ordinary Samoan greeting, and talofa lava is addressed to a group. Yet the simple word opens onto fa'a Samoa, the Samoan way, which organises life around the aiga (extended family), the matai (titled chief) and service (tautua) to both.","Respect is encoded in the language itself: a separate vocabulary is used for chiefs and for formal oratory, and ordinary words have chiefly equivalents."]},{"heading":"Respect from a distance","paragraphs":["The 'ava ceremony formalises meetings with a drink made from the kava root, and the order of serving mirrors rank within the village.","Migration to New Zealand and the United States means many Samoan families maintain fa'a Samoa through church, remittances and village obligations from a distance.","It is lived differently by region and generation: urban Samoans, migrants and younger people negotiate its meaning in their own ways."]}]},"context":{"countries":["WS"],"region":"Samoa, with communities in New Zealand, Australia and the US","community":"Samoan communities","continent":"oceania","languages":["sm","en"],"period":"contemporary"},"tags":["communication","Samoa, with communities in New Zealand, Australia and the US"],"sources":[{"organization":"Wikipedia","title":{"ar":"Samoan language","de":"Samoan language","en":"Samoan language"},"url":"https://en.wikipedia.org/wiki/Samoan_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Faʻa Sāmoa","de":"Faʻa Sāmoa","en":"Faʻa Sāmoa"},"url":"https://en.wikipedia.org/wiki/Fa%CA%BBa_S%C4%81moa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عائلة ساموية في أوكلاند ترسل مالاً وطعاماً معلّباً لجنازة في القرية، فيشكرها الماتاي بالاسم في خطاب يعامل الفرع المهاجر كأنه حاضر جسدياً.","de":"Eine samoanische Familie in Auckland schickt Geld und Konserven zu einem Begräbnis im Dorf, und der matai dankt ihnen namentlich in einer Rede, die den Zweig in Übersee wie körperlich anwesend behandelt.","en":"A Samoan family in Auckland sends money and tinned food for a village funeral, and the matai thanks them by name in a speech that treats the overseas branch as physically present."},"misunderstanding":{"ar":"يظن كثيرون أن تالوفا مجرد مجاملة عابرة، لكنها في سياقها الساموي إقرار بالعلاقة وما يترتب عليها من واجبات.","de":"Viele halten Talofa für eine flüchtige Höflichkeit, doch im samoanischen Kontext bestätigt es die Beziehung und die daraus folgenden Pflichten.","en":"Many take Talofa for a passing courtesy, but in Samoan settings it confirms a relationship and the duties that come with it."},"comparison":{"ar":"تشبه تالوفا التحيات العربية التي تحمل تمنيات وبركات، إذ تتجاوز الكلمة إلى تأكيد الرابطة الاجتماعية.","de":"Talofa ähnelt arabischen Grußformeln, die Segen und Verbundenheit tragen, und reicht über das Wort hinaus zur Bekräftigung der Gemeinschaft.","en":"Talofa resembles Arabic greetings that carry blessings and belonging, reaching beyond the word to affirm the social bond."},"expression":{"original":"Talofa","language":"Gagana Samoa (Samoan)","gloss":{"ar":"مرحباً","de":"hallo","en":"hello"},"usage":{"ar":"تحية يومية تُقال عند اللقاء، وتُستعمل تالوفا لافا لجماعة.","de":"Alltäglicher Gruß zur Begrüßung; talofa lava gilt einer Gruppe.","en":"Everyday greeting on meeting; talofa lava is used for a group."},"transliteration":"talofa"}},{"id":"lng-086","version":2,"slug":"malo-e-lelei-tongan-greeting-inside-a-language-of-rank","contentType":"note","category":"communication","title":{"ar":"مالو إي ليلي: تحية تونغا ولغة المراتب","de":"Malō e lelei: Tongas Gruß in einer Sprache der Ränge","en":"Malō e lelei: Tongan greeting inside a language of rank"},"deck":{"ar":"في تونغا، التحية ليست مجرد كلمة عابرة، بل تحمل في طياتها نظاماً اجتماعياً كاملاً يميز بين الزعماء والعامة.","de":"In Tonga ist ein Gruß mehr als eine flüchtige Formel: Er trägt ein ganzes soziales System aus Häuptlingen und Gemeinen in sich.","en":"In Tonga a greeting is never just a word: it carries a whole social order of chiefs and commoners in its choice of vocabulary."},"teaser":{"ar":"كيف تكشف تحية واحدة عن مجتمع منظم حول الزعماء والعامة، وكيف تختلف الكلمات باختلاف من تخاطبه؟","de":"Wie verrät ein einziger Gruß eine Gesellschaft, die um Häuptlinge und Gemeine organisiert ist, und warum ändern sich die Wörter je nach Gegenüber?","en":"How does one greeting reveal a society organised around chiefs and commoners, and why do the words change depending on whom you address?"},"readingMinutes":1,"sections":{"ar":[{"heading":"تحية تتجاوز الكلمات","paragraphs":["«مالو إي ليلي» هي التحية القياسية في تونغا، وكلمة «مالو» وحدها تعني أيضاً شكراً. لكن هذه البساطة تخفي نظاماً لغوياً دقيقاً يعكس تراتبية المجتمع.","تستخدم التونغية الرسمية سجلاً خاصاً بالزعماء بمفردات منفصلة لكثير من الكلمات اليومية، فخطاب موجه إلى النبلاء يختلف في اختيار الكلمات وليس في النبرة فقط."]},{"heading":"اللغة ترسم العلاقات","paragraphs":["تنتظم المجتمع حول «إيكي» (الزعماء) و«توا» (العامة)، واللغة تحدد هذه العلاقة عبر اختيار المفردات واستخدام أداة التعريف.","دائرة الكافا، بترتيب جلوسها وصيغ خطابها، هي المكان الذي يُؤدى فيه الخطاب الرسمي. وتختلف هذه الممارسات بين الأجيال والمناطق، إذ يميل الشتات إلى تبسيط السجل الزعيمي."]}],"de":[{"heading":"Ein Gruß, der mehr trägt","paragraphs":["„Malō e lelei“ ist der Standardgruß in Tonga, und „malo“ allein bedeutet auch danke. Doch diese Einfachheit verbirgt ein feines sprachliches System, das die Hierarchie der Gesellschaft widerspiegelt.","Das formelle Tongaische verwendet ein eigenes Häuptlingsregister mit getrennten Wörtern für viele Alltagsbegriffe, sodass sich eine Rede an Adlige nicht nur im Ton, sondern in der Wortwahl unterscheidet."]},{"heading":"Sprache zeichnet Beziehungen","paragraphs":["Die Gesellschaft ist um 'eiki (Häuptlinge) und tu'a (Gemeine) organisiert, und die Sprache markiert dieses Verhältnis durch Wortwahl und den Gebrauch des definiten Akzents.","Der Kava-Kreis mit seiner Sitzordnung und seinen Redeformeln ist der Ort, an dem formelle tongaische Redekunst aufgeführt wird. Regional und zwischen Generationen unterscheidet sich diese Praxis, und in der Diaspora wird das Häuptlingsregister oft vereinfacht."]}],"en":[{"heading":"A greeting that carries more","paragraphs":["Malō e lelei is the standard Tongan greeting, and malo alone also means thank you. Yet this simplicity hides a precise linguistic system that mirrors the hierarchy of society.","Formal Tongan uses a chiefly register with separate vocabulary for many everyday words, so a speech addressed to nobles differs in word choice and not only in tone."]},{"heading":"Language draws the relationships","paragraphs":["Society is organised around 'eiki (chiefs) and tu'a (commoners), and language marks the relationship in vocabulary choice and in the use of the definite accent.","The kava circle, with its own seating order and speech formulas, is where formal Tongan oratory is performed. Practice varies by region and generation, and diaspora Tongans often simplify the chiefly register."]}]},"context":{"countries":["TO"],"region":"Tonga, with diaspora in New Zealand, Australia and the US","community":"Tongan communities","continent":"oceania","languages":["to","en"],"period":"contemporary"},"tags":["communication","Tonga, with diaspora in New Zealand, Australia and the US"],"sources":[{"organization":"Wikipedia","title":{"ar":"Tongan language","de":"Tongan language","en":"Tongan language"},"url":"https://en.wikipedia.org/wiki/Tongan_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Tonga","de":"Tonga","en":"Tonga"},"url":"https://en.wikipedia.org/wiki/Tonga","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالب تونغي في أوكلاند يخاطب قريباً مسناً زائراً بمفردات زعيمية وكلمة مختلفة لـ«يأكل»، واختيار الكلمة يؤدي عملاً اجتماعياً أكبر من مضمون الجملة.","de":"Ein tongaischer Student in Auckland spricht einen älteren Besuch mit Häuptlingsvokabular und einem anderen Wort für „essen“ an, und die Wortwahl leistet mehr soziale Arbeit als der Inhalt des Satzes.","en":"A Tongan student in Auckland addresses an older visiting relative with chiefly vocabulary and a different word for eat, and the choice of word does more social work than the sentence's content."},"misunderstanding":{"ar":"يعتقد البعض أن التحية مجرد لفظ عابر، لكن اختيار السجل اللغوي في تونغا إشارة احترام واعتراف بالمرتبة الاجتماعية.","de":"Manche halten den Gruß für eine bloße Floskel, doch die Wahl des Registers ist in Tonga ein Zeichen von Respekt und Anerkennung des sozialen Rangs.","en":"Some treat the greeting as a mere formula, but in Tonga the choice of register signals respect and acknowledges social rank."},"comparison":{"ar":"في تونغا ترتبط التحية بمرتبة المخاطَب، بينما في لغات أخرى قد يقتصر الأمر على درجة الرسمية دون مفردات منفصلة.","de":"In Tonga ist der Gruß an den Rang des Gegenübers gebunden, während in anderen Sprachen oft nur der Grad der Förmlichkeit variiert, ohne getrennte Wörter.","en":"In Tonga the greeting is tied to the addressee's rank, whereas in many languages only the degree of formality shifts, without separate words."},"expression":{"original":"Mālō e lelei","language":"Lea faka-Tonga (Tongan)","gloss":{"ar":"مرحباً","de":"hallo","en":"hello"},"usage":{"ar":"تحية قياسية تقال عند اللقاء، وكلمة «مالو» وحدها تعني شكراً.","de":"Standardgruß zur Begrüßung; „malo“ allein bedeutet danke.","en":"Standard greeting on meeting; malo alone means thank you."},"transliteration":"malo e lelei"}},{"id":"lng-087","version":2,"slug":"bula-the-fijian-hello-that-is-a-wish-for-life","contentType":"note","category":"communication","title":{"ar":"بولا: تحية فيجية تعني الحياة","de":"Bula: Der fidschianische Gruß für das Leben","en":"Bula: The Fijian hello that wishes life"},"deck":{"ar":"كيف يعيش الناس في فيجي مع تحية تحمل تمنيًا بالحياة والصحة","de":"Wie Menschen in Fidschi mit einem Gruß leben, der Lebenswünsche trägt","en":"How people in Fiji live with a greeting that carries a wish for life and health"},"teaser":{"ar":"في فيجي، كلمة 'بولا' ليست مجرد مرحبًا، بل دعاء بالحياة. تعرف على كيفية استخدامها في الحياة اليومية.","de":"In Fidschi ist 'Bula' mehr als ein Hallo – es ist ein Wunsch für Leben und Gesundheit. Erfahren Sie, wie er den Alltag prägt.","en":"In Fiji, 'Bula' is more than hello—it's a wish for life. Discover how this greeting shapes everyday interactions."},"readingMinutes":1,"sections":{"ar":[{"heading":"تحية تحمل تمنيًا بالحياة","paragraphs":["تعني كلمة 'بولا' الحياة أو الصحة، وهي التحية القياسية بين الغرباء وأصحاب المتاجر والزملاء. وعندما تضيف 'بولا فيناكا'، فإنك تتمنى الخير. يسمعها الزوار من كل مدخل، وقد أصبحت جزءًا من الإنجليزية الفيجية كتحية قائمة بذاتها.","تستخدم اللغة الفيجية في جميع أنحاء البلاد، مع لهجات متعددة، وأصبحت لهجة باوان هي المعيار منذ القرن التاسع عشر. ويختلف الاستخدام بين المناطق والأجيال؛ ففي المدن قد تسمع مزيجًا من التحيات، بينما تظل 'بولا' الأكثر شيوعًا."]},{"heading":"الاحترام والتحية في المجتمع","paragraphs":["يُظهر الاحترام في فيجي باستخدام الألقاب وتجنب التناقض المباشر في اجتماعات القرية. وتحتفظ اللغة الإنجليزية كلغة عمل مع ترجمة إلى iTaukei والهندية.","ليست الفيجية اللغة الأم للهنود الفيجيين، الذين قد يستخدمون 'ناماستي' أو 'هيلو'. لكن 'بولا' تبقى جسرًا بين المجتمعات."]}],"de":[{"heading":"Ein Gruß, der Leben wünscht","paragraphs":["Bula bedeutet Leben oder Gesundheit und ist der Standardgruß zwischen Fremden, Ladenbesitzern und Kollegen. Bula vinaka fügt 'gut' hinzu. Besucher hören es aus jeder Tür, und es lebt im Fiji-Englisch als eigenständiger Gruß weiter.","Fidschianisch ist eine austronesische Sprache mit mehreren Dialekten; der Bauan-Dialekt wurde im 19. Jahrhundert durch Mission und Kolonialverwaltung zum Standard. Die Verwendung variiert regional und generationell – in Städten mischt sich Bula mit anderen Grüßen, bleibt aber allgegenwärtig."]},{"heading":"Respekt und Grußkultur","paragraphs":["Respekt zeigt sich in Fidschi durch Titel und das Vermeiden direkter Widersprüche in Dorfversammlungen. Englisch bleibt Arbeitssprache, mit Übersetzung ins iTaukei und Hindi.","Für Indo-Fidschianer ist Fidschianisch nicht die Muttersprache; sie grüßen mit Namaste oder Hello. Doch Bula bleibt eine Brücke zwischen den Gemeinschaften."]}],"en":[{"heading":"A greeting that wishes life","paragraphs":["Bula means life or health, and it is the standard hello between strangers, shopkeepers and colleagues; bula vinaka adds good. Visitors hear it from every doorway, and it survives in Fiji English as a greeting in its own right.","Fijian is an Austronesian language with several dialects, and the Bauan dialect became standard through nineteenth-century mission and colonial use. Usage varies by region and generation—in towns you may hear a mix, but bula remains the most common."]},{"heading":"Respect and greeting in society","paragraphs":["Respect in Fijian is shown through titles and avoiding direct contradiction in village meetings. English remains the working language, with translation into iTaukei and Hindi required.","Fijian is not the first language of Indo-Fijians, who may greet with namaste or hello. Yet bula remains a bridge across communities."]}]},"context":{"countries":["FJ"],"region":"Nationwide, strongest in Bau and the main islands","continent":"oceania","languages":["fj","en","hif"],"period":"contemporary"},"tags":["communication","Nationwide, strongest in Bau and the main islands"],"sources":[{"organization":"Wikipedia","title":{"ar":"Fijian language","de":"Fijian language","en":"Fijian language"},"url":"https://en.wikipedia.org/wiki/Fijian_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Fiji","de":"Fiji","en":"Fiji"},"url":"https://en.wikipedia.org/wiki/Fiji","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عندما يسير زائر في سوق سوفا، يستقبله كل بائع بـ 'بولا'، ويكفي أن يرد بـ 'بولا' ليُعتبر زبونًا لا غريبًا.","de":"Ein Besucher auf dem Markt in Suva wird von jedem Standbesitzer mit Bula begrüßt; ein Bula zurück genügt, um als Kunde statt als Fremder zu gelten.","en":"A visitor walking through a Suva market is greeted with bula by every stallholder in turn, and answering bula back is enough to be treated as a customer rather than a stranger."},"misunderstanding":{"ar":"قد يعتقد البعض أن 'بولا' مجرد كلمة عابرة، لكنها تحمل دعاءً بالحياة، وتكرارها يعكس دفء العلاقات.","de":"Manche halten Bula für ein flüchtiges Hallo, doch es ist ein Lebenswunsch, und seine Häufigkeit zeigt Herzlichkeit.","en":"Some think bula is just a casual hello, but it carries a wish for life, and its frequency reflects warmth."},"comparison":{"ar":"مثل تحية 'شالوم' العبرية التي تعني السلام، تحمل 'بولا' معنى أعمق من مجرد مرحبًا.","de":"Wie das hebräische Schalom, das Frieden bedeutet, trägt Bula eine tiefere Bedeutung als ein simples Hallo.","en":"Like the Hebrew shalom meaning peace, bula holds a deeper meaning than a simple hello."},"expression":{"original":"Bula","language":"Vosa Vakaviti (Fijian)","gloss":{"ar":"مرحبًا / حياة","de":"Hallo / Leben","en":"hello / life"},"usage":{"ar":"تحية قياسية بين الغرباء والأصدقاء، وتستخدم عند الدخول إلى متجر أو مقابلة زميل.","de":"Standardgruß zwischen Fremden und Freunden, beim Betreten eines Ladens oder Treffen von Kollegen.","en":"Standard greeting between strangers and friends, used when entering a shop or meeting a colleague."},"transliteration":"bula"}},{"id":"lng-089","version":2,"slug":"wantok-the-tok-pisin-word-that-turns-a-shared-language-into-a-duty","contentType":"note","category":"communication","title":{"ar":"وانتوك: كلمة تحوّل اللغة المشتركة إلى واجب","de":"Wantok: ein Wort macht gemeinsame Sprache zur Pflicht","en":"Wantok: one word turns shared language into duty"},"deck":{"ar":"في بابوا غينيا الجديدة، كلمة واحدة تربط بين اللغة والقرابة وتفرض مسؤوليات مالية واجتماعية على من يستخدمها.","de":"In Papua-Neuguinea verbindet ein einziges Wort Sprache und Verwandtschaft und verpflichtet Menschen zu Geld, Wohnung und Arbeit.","en":"In Papua New Guinea a single term links language and kinship, obliging people to share money, housing and jobs."},"teaser":{"ar":"أكثر من ثمانمائة لغة في بلد واحد جعلت التوكن بيسين جسراً بين الناس، لكن كلمة «وانتوك» تحوّلت من مجرد وصف إلى التزام يومي.","de":"Über achthundert Sprachen in einem Land machten Tok Pisin zur Brücke zwischen Menschen, doch „Wantok“ beschreibt längst nicht mehr nur gemeinsames Sprechen.","en":"More than eight hundred languages in one country made Tok Pisin a practical bridge, but “wantok” describes far more than speaking the same tongue."},"readingMinutes":1,"sections":{"ar":[{"heading":"كلمة من كلمتين","paragraphs":["تتكوّن كلمة «وانتوك» من «وانتايم» أي معاً، و«توك» أي الكلام أو اللغة، فتصف من يتحدث لغتك أو ينتمي إلى عشيرتك. ونظام وانتوك يُلزم الناس بمساعدة الأقارب بالمال والسكن والوظائف، ويعمل كضمان اجتماعي حيث تكون الدولة ضعيفة.","بدأ التوكن بيسين لغةَ مزارع في القرن التاسع عشر، ثم امتد إلى الإذاعة والبرلمان والصحف، وصار اليوم لغة رسمية."]},{"heading":"شبكة تُعين وتُتهم","paragraphs":["ينتقد بعضهم نظام وانتوك باعتباره باباً للمحاباة في التوظيف العام، بينما يرى المدافعون أن الشبكة نفسها هي ما يعتمد عليه الناس حين تفشل الخدمات الرسمية. ويختلف حجم هذه الالتزامات بين مجتمعات المرتفعات والساحل، وبين حياة المدينة والقرية، وتُستخدم الكلمة بحرارة وبلهجة اتهام في آن واحد."]},{"heading":"من يحق له أن ينادي؟","paragraphs":["ليست كل معرفة بلغة مشتركة تجعل المرء وانتوك، فالمصطلح يحمل شرطاً من القرابة أو الانتماء لا مجرد التفاهم اللغوي."]}],"de":[{"heading":"Zwei Wörter, ein Begriff","paragraphs":["Wantok verbindet wantaim, also zusammen, mit tok, also Sprache oder Reden, und bezeichnet jemanden, der dieselbe Sprache spricht oder zum selben Clan gehört. Das Wantok-System verpflichtet Menschen, Verwandten mit Geld, Wohnung und Arbeit zu helfen, und wirkt als soziale Absicherung, wo der Staat schwach ist.","Tok Pisin entstand im neunzehnten Jahrhundert als Plantagen-Pidgin und breitete sich in Radio, Parlament und Zeitungen aus; heute ist es eine Amtssprache."]},{"heading":"Ein Netz, das stützt und belastet","paragraphs":["Kritiker machen Wantok für Vetternwirtschaft bei öffentlichen Stellen verantwortlich, während Verteidiger betonen, dass genau dieses Netz trägt, wenn formale Dienste versagen. Wie stark die Verpflichtungen sind, unterscheidet sich zwischen Hochland und Küste sowie zwischen Stadt und Dorf, und das Wort wird ebenso herzlich wie anklagend gebraucht."]},{"heading":"Wer darf anklopfen?","paragraphs":["Nicht jede Bekanntschaft über eine gemeinsame Sprache macht jemanden zum Wantok; der Begriff verlangt Verwandtschaft oder Zugehörigkeit, nicht bloßes Verstehen."]}],"en":[{"heading":"Two words, one obligation","paragraphs":["Wantok combines wantaim, meaning together, with tok, meaning talk or language, and names someone who speaks the same language or belongs to the same clan. The wantok system obliges people to help relatives with money, housing and jobs, and it functions as social security where the state is weak.","Tok Pisin began as a plantation pidgin in the nineteenth century and expanded into radio, parliament and newspapers; it is now an official language."]},{"heading":"A network that helps and burdens","paragraphs":["Critics blame wantok for nepotism in public hiring, while defenders point out that the same network is what people rely on when formal services fail. Wantok obligations vary between highland and coastal societies and between urban and village life, and the term is used both warmly and accusingly."]},{"heading":"Who may call on you","paragraphs":["Not every shared-language acquaintance counts as a wantok; the word assumes kinship or belonging, not merely mutual understanding."]}]},"context":{"countries":["PG"],"region":"Nationwide, especially urban centres and the coast","continent":"oceania","languages":["tpi","en","ho"],"period":"contemporary"},"tags":["communication","Nationwide, especially urban centres and the coast"],"sources":[{"organization":"Wikipedia","title":{"ar":"Tok Pisin","de":"Tok Pisin","en":"Tok Pisin"},"url":"https://en.wikipedia.org/wiki/Tok_Pisin","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Languages of Papua New Guinea","de":"Languages of Papua New Guinea","en":"Languages of Papua New Guinea"},"url":"https://en.wikipedia.org/wiki/Languages_of_Papua_New_Guinea","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"ممرضة في بورت مورسبي تتلقى في شهر واحد ستة طلبات لرسوم مدرسية من «وانتوك»، فتدفع اثنتين، وهي تعرف أن رفض الستة جميعاً سيقطع عنها شبكة الدعم التي قد تحتاجها هي نفسها.","de":"Eine Krankenschwester in Port Moresby erhält in einem Monat sechs Bitten um Schulgebühren von Wantoks und bezahlt zwei, wohl wissend, dass eine Ablehnung aller sechs das Netz kappen würde, auf das sie selbst angewiesen sein könnte.","en":"A Port Moresby nurse receives six requests for school fees from wantoks in one month and pays two, knowing that refusing all six would end the support she may need herself."},"misunderstanding":{"ar":"يظن البعض أن «وانتوك» مجرد صديق يتحدث لغتك، لكنها في الاستخدام اليومي أقرب إلى صلة قرابة تفرض واجبات متبادلة.","de":"Viele halten Wantok für einen bloßen Freund mit derselben Sprache, doch im Alltag ist es eher eine Verwandtschaftsbeziehung mit gegenseitigen Pflichten.","en":"Many assume a wantok is simply a friend who speaks your language, but in daily use it is closer to a kinship relation that carries mutual duties."},"comparison":{"ar":"حيث تتحدث المجتمعات لغات كثيرة، تصبح لغة مشتركة جسراً عملياً، لكن وانتوك تضيف إلى الجسر التزاماً أخلاقياً لا يكتفي بالتفاهم.","de":"Wo viele Sprachen nebeneinander bestehen, wird eine gemeinsame Sprache zur praktischen Brücke; Wantok fügt dieser Brücke eine moralische Verpflichtung hinzu, die über Verständigung hinausgeht.","en":"Where many languages coexist, a shared tongue becomes a practical bridge; wantok adds a moral claim to that bridge, going beyond mere understanding."},"expression":{"original":"Wantok","language":"Tok Pisin","gloss":{"ar":"صديق أو قريب يتحدث لغتك","de":"gleichsprachiger Freund oder Verwandter","en":"same-language friend or kin"},"usage":{"ar":"تُقال للترحيب أو للمطالبة بمساعدة، وقد تحمل نبرة لوم عند الحديث عن المحاباة.","de":"Als Begrüßung oder Bitte um Hilfe gebraucht, kann aber auch vorwurfsvoll klingen, wenn von Vetternwirtschaft die Rede ist.","en":"Used in greeting or to ask for help, but it can also sound accusing when nepotism is discussed."},"transliteration":"wantok"}},{"id":"lng-090","version":2,"slug":"ngurra-the-warlpiri-word-for-country-that-also-names-who-you-are-related-to","contentType":"note","category":"languages","title":{"ar":"نغورا: الأرض التي تحدد من أنت","de":"Ngurra: das Land, das Verwandtschaft benennt","en":"Ngurra: the country that names your kin"},"deck":{"ar":"كلمة ولبريري واحدة تربط المكان بالقرابة والالتزام، فتصير الأرض علاقة لا منظراً.","de":"Ein Warlpiri-Wort verbindet Ort, Verwandtschaft und Verantwortung – Land wird zur Beziehung statt zur Kulisse.","en":"One Warlpiri word ties place to kinship and obligation, turning land into a relationship rather than scenery."},"teaser":{"ar":"في صحراء تانامي، تعني «نغورا» المخيم والوطن، وتحمل واجب رعاية المكان والناس المرتبطين به.","de":"In der Tanami-Wüste bedeutet „Ngurra“ Lager und Heimat und trägt die Pflicht, für Ort und Menschen zu sorgen.","en":"In the Tanami Desert, ngurra means camp and home country, and it carries duties to care for place and people."},"readingMinutes":1,"sections":{"ar":[{"heading":"المكان كقرابة","paragraphs":["كلمة «نغورا» في لغة ولبريري تعني المخيم أو البيت أو الوطن، لكنها لا تقف عند المعنى الجغرافي؛ فهي تحمل واجبات رعاية ذلك المكان والناس المرتبطين به. ولهذا يتباطأ رجل ولبريري عند حفرة ماء وهو يقود سيارته، دون أن يُطلب منه ذلك، لأن نغورا ليست مشهداً بل علاقة تستوجب التحية والاعتراف.","ينظّم نظام القرابة عند ولبريري الناس في فئات لكل منها سلوك متوقع، بما في ذلك علاقات تجنّب مع بعض الأصهار. وتختلف هذه الأعراف بين المناطق والأجيال، إذ يعيد الشباب في مدن مثل يوندومو ولاجامانو صياغة ما تعلّموه من كبارهم."]},{"heading":"لغة تُبنى بالحالات","paragraphs":["لغة ولبريري إرجاتية وترتيب كلماتها حر، فالنهايات الإعرابية لا موقع الكلمة هي التي تكشف من فعل ماذا بمن. وقد دُرّست ثنائياً في مدارس المقاطعة الشمالية، وأنتج مركز إنتاج أدب ولبريري في يوندومو كتباً وقواميس بهذه اللغة.","كثير من اللغات الأسترالية فقدت متحدثيها بسبب سياسات البعثات والاستيعاب، واليوم يجري إحياء ولبريري عبر مدارس ووسائل إعلام تديرها المجتمعات المحلية. وتتفاوت هذه الجهود من منطقة إلى أخرى ومن جيل إلى جيل."]}],"de":[{"heading":"Ort als Verwandtschaft","paragraphs":["Ngurra bedeutet im Warlpiri Lager, Zuhause oder Land, doch der Begriff trägt Verpflichtungen: für diesen Ort und die mit ihm verbundenen Menschen zu sorgen. Ein Warlpiri-Mann, der an einem Wasserloch vorbeifährt, wird langsamer, ohne dass es jemand verlangt, weil Ngurra keine Kulisse ist, sondern eine Beziehung, die Anerkennung verlangt.","Das Verwandtschaftssystem der Warlpiri teilt Menschen in Kategorien mit erwartetem Verhalten ein, darunter Meidungsbeziehungen zu bestimmten Schwiegereltern. Diese Regeln unterscheiden sich regional und zwischen Generationen; junge Leute in Orten wie Yuendumu und Lajamanu handeln neu aus, was sie von Älteren gelernt haben."]},{"heading":"Eine Sprache der Fälle","paragraphs":["Warlpiri ist ergativisch und hat freie Wortstellung, deshalb zeigen Kasusendungen und nicht die Position, wer wem was antut. Die Sprache wurde zweisprachig in Schulen des Northern Territory unterrichtet, und das Warlpiri Literature Production Centre in Yuendumu veröffentlichte Bücher und Wörterbücher.","Wie viele australische Sprachen verlor Warlpiri durch Missions- und Assimilationspolitik Sprecher; heute läuft die Revitalisierung über Schulen und Medien in Gemeindeträgerschaft. Wie stark das gelingt, schwankt je nach Region und Generation."]}],"en":[{"heading":"Place as kinship","paragraphs":["Ngurra means camp, home or country in Warlpiri, and it carries obligations to look after that place and the people connected to it. A Warlpiri man driving past a waterhole slows without being asked, because ngurra is not scenery but a relationship that requires acknowledgement.","Warlpiri kinship divides people into categories with expected behaviour, including avoidance relationships with certain in-laws. These protocols vary by region and generation, as younger people in places like Yuendumu and Lajamanu rework what they learned from elders."]},{"heading":"A language built on case","paragraphs":["Warlpiri is ergative and has free word order, so case endings rather than position show who did what to whom. It has been taught bilingually in Northern Territory schools, and the Warlpiri Literature Production Centre at Yuendumu produced books and dictionaries in the language.","Like many Australian languages, Warlpiri lost speakers through mission and assimilation policies, and revitalisation now runs through community-controlled schools and media. Such efforts vary unevenly between regions and generations."]}]},"context":{"countries":["AU"],"region":"Tanami Desert, Northern Territory (Yuendumu, Lajamanu)","community":"Warlpiri communities","continent":"oceania","languages":["wbp","en"],"period":"contemporary"},"tags":["languages","Tanami Desert, Northern Territory (Yuendumu, Lajamanu)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Warlpiri language","de":"Warlpiri language","en":"Warlpiri language"},"url":"https://en.wikipedia.org/wiki/Warlpiri_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Australian Aboriginal kinship systems","de":"Australian Aboriginal kinship systems","en":"Australian Aboriginal kinship systems"},"url":"https://en.wikipedia.org/wiki/Australian_Aboriginal_kinship_systems","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"رجل ولبريري يمرّ بحفرة ماء فيبطئ دون أن يُطلب منه، لأن نغورا ليست منظراً بل علاقة تستوجب الاعتراف.","de":"Ein Warlpiri-Mann verlangsamt am Wasserloch ungefragt, weil Ngurra keine Szenerie ist, sondern eine Beziehung, die Anerkennung verlangt.","en":"A Warlpiri man driving past a waterhole slows without being asked, because ngurra is not scenery but a relationship that requires acknowledgement."},"misunderstanding":{"ar":"يظن كثيرون أن «نغورا» مجرد كلمة للأرض أو الطبيعة، بينما هي في الحقيقة شبكة قرابة ومسؤولية.","de":"Viele halten Ngurra für ein bloßes Wort für Land oder Natur, dabei ist es ein Netz aus Verwandtschaft und Verantwortung.","en":"Many assume ngurra is simply a word for land or nature, when it is really a network of kinship and responsibility."},"comparison":{"ar":"حيث نسمّي نحن المكان «عقاراً» أو «منظراً»، تسمّيه ولبريري قرابة وواجباً.","de":"Wo wir Ort als „Immobilie“ oder „Landschaft“ benennen, nennt Warlpiri ihn Verwandtschaft und Pflicht.","en":"Where we might call a place property or landscape, Warlpiri names it kinship and duty."},"expression":{"original":"Ngurra","language":"Warlpiri","gloss":{"ar":"وطن/مخيم","de":"Heimatland / Lager","en":"home country / camp"},"usage":{"ar":"تُستخدم للدلالة على المكان الذي تنتمي إليه وترتبط به وبأهله.","de":"Bezeichnet den Ort, zu dem man gehört und mit dessen Menschen man verbunden ist.","en":"Used for the place you belong to and are related to, and the people connected with it."},"transliteration":"ngurra"}},{"id":"oce-001","version":2,"slug":"whakapapa-reciting-a-genealogy-that-is-also-a-map","contentType":"note","category":"family-and-friendship","title":{"ar":"الواكابابا: سرد النسب الذي هو خريطة","de":"Whakapapa: Ein Stammbaum, der auch eine Landkarte ist","en":"Whakapapa: reciting a genealogy that is also a map"},"deck":{"ar":"في ماري الماوري، لا يُعد النسب مجرد شجرة عائلة، بل هو خريطة حية تربط الناس بالأرض والأسلاف.","de":"Whakapapa ist keine einfache Ahnentafel, sondern eine vielschichtige Rezitation, die Menschen mit Vorfahren, Land und Stämmen verbindet.","en":"Whakapapa is not a simple family tree but a layered recitation linking people to ancestors, land and tribal groupings."},"teaser":{"ar":"الواكابابا هو سرد متعدد الطبقات يربط الشخص بأسلافه وأرضه، ويُستخدم في المناسبات للتعرف على القرابة.","de":"Whakapapa verbindet Menschen mit ihren Vorfahren, Bergen und Flüssen. Bei Treffen erkennen sich Gastgeber und Besucher oft innerhalb von Minuten als Verwandte.","en":"Whakapapa connects people to ancestors, mountains and rivers. At gatherings, hosts and visitors often discover a shared ancestor within minutes."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما هو الواكابابا؟","paragraphs":["الواكابابا ليس مجرد شجرة عائلة بسيطة: إنه سرد متعدد الطبقات يمكن أن يمتد عبر الأجيال وينتشر بين أبناء العم، ليربط الشخص بالأسلاف والأرض والمجموعات القبلية.","يربط الواكابابا حامله بجبال وأنهار وماراي وهابو معينة، لذا فإن تلاوته هي أيضًا بيان عن مكانة الشخص وانتمائه.","يُسمع الواكابابا في البوويري والتانغيهانغا والهوي، وهو الطريقة التي يكتشف بها المضيفون والزوار سلفًا مشتركًا في غضون دقائق من اللقاء."]},{"heading":"النسب كدليل وهوية","paragraphs":["تُستخدم خطوط النسب كدليل في معاهدات وايتانغي، حيث يجب على المجموعة إظهار ارتباطها بالمالكين الأصليين للأرض.","المعرفة محفوظة لدى عائلات وقبائل معينة، وليس في سجل وطني واحد، وتتبع كل إيوي خطوطًا من زوارق شراعية مختلفة.","يختلف التقليد بين الأجيال والمناطق: بعض العائلات تحفظ النسب شفهيًا، بينما يستخدم الشباب اليوم تسجيلات رقمية، لكن يظل الإذن من الشيوخ شرطًا للتلاوة."]}],"de":[{"heading":"Was ist Whakapapa?","paragraphs":["Whakapapa ist kein einfacher Stammbaum: Es ist eine vielschichtige Rezitation, die über Generationen und zwischen Cousins verlaufen kann und eine Person mit Vorfahren, Land und Stammesgruppen verbindet.","Eine Whakapapa bindet ihren Träger an bestimmte Berge, Flüsse, Marae und Hapū. Sie auszusprechen ist daher auch eine Aussage darüber, wohin jemand gehört und auf wen er sich berufen kann.","Whakapapa wird beim Pōwhiri, bei Tangihanga und Hui gehört. So entdecken Gastgeber und Besucher oft schon Minuten nach dem Treffen einen gemeinsamen Vorfahren."]},{"heading":"Ahnenlinien als Nachweis und Identität","paragraphs":["Abstammungslinien dienen als Beweis in Treaty-of-Waitangi-Verfahren, bei denen eine Gruppe ihre Verbindung zu den ursprünglichen Landbesitzern nachweisen muss.","Das Wissen wird von bestimmten Whānau und Hapū bewahrt, nicht in einem nationalen Register. Verschiedene Iwi führen ihre Linien auf unterschiedliche Waka zurück.","Die Tradition variiert regional und zwischen Generationen: Manche Familien geben Whakapapa mündlich weiter, während junge Leute heute digitale Aufzeichnungen nutzen – die Erlaubnis der Älteren bleibt jedoch Voraussetzung."]}],"en":[{"heading":"What whakapapa is","paragraphs":["Whakapapa is not a simple family tree: it is a layered recitation that can run down the generations and sideways between cousins, joining a person to ancestors, land and tribal groupings.","A whakapapa links its holder to particular mountains, rivers, marae and hapū, so reciting it is also a statement about where someone belongs and who they can call on.","It is heard at pōwhiri, tangihanga and hui, and it is how hosts and visitors discover a shared ancestor within minutes of meeting."]},{"heading":"Descent lines as evidence and identity","paragraphs":["Descent lines are used as evidence in Treaty of Waitangi claims, where a group must show its connection to the original owners of land.","Knowledge is held by particular whānau and hapū, not in one national record, and different iwi trace from different voyaging canoes.","Recitation conventions vary by region and generation: some families pass whakapapa on orally, while younger people now use digital recordings, though permission from elders remains essential."]}]},"context":{"countries":["NZ"],"region":"Aotearoa New Zealand","community":"Māori","continent":"oceania","languages":["mi","en"],"period":"contemporary"},"tags":["family-and-friendship","Aotearoa New Zealand"],"sources":[{"organization":"Wikipedia","title":{"ar":"Whakapapa","de":"Whakapapa","en":"Whakapapa"},"url":"https://en.wikipedia.org/wiki/Whakapapa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Māori culture","de":"Māori culture","en":"Māori culture"},"url":"https://en.wikipedia.org/wiki/M%C4%81ori_culture","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في تانغيهانغا، تبدأ متحدثة بذكر جبلها ونهرها؛ فيتعرف شيخ من الجانب الآخر على سلف مشترك، فتسترخي العائلتان في نفس الواكابابا.","de":"Bei einem Tangihanga beginnt eine Rednerin mit der Nennung ihres Maunga und Awa; ein Ältester der anderen Seite erkennt einen gemeinsamen Vorfahren, und die beiden Familien entspannen sich in derselben Whakapapa.","en":"At a tangihanga a speaker opens by naming her maunga and awa; an elder on the other side recognises a shared ancestor, and the two families relax into the same whakapapa."},"misunderstanding":{"ar":"يعتقد البعض أن الواكابابا مجرد شجرة عائلة عامة، لكنه في الواقع سرد مقيد بإذن العائلة والقبيلة، وبعض أجزائه لا يُشارك علنًا.","de":"Manche halten Whakapapa für einen öffentlichen Stammbaum. Tatsächlich ist es ein Wissen, das an die Erlaubnis von Whānau und Hapū gebunden ist, und einige Teile werden nicht öffentlich geteilt.","en":"Some assume whakapapa is a public family tree, but it is knowledge held with whānau and hapū permission, and some parts are not shared openly."},"comparison":{"ar":"بينما تُحفظ الأنساب في سجلات وطنية في مجتمعات أخرى، يحتفظ الماوري بالواكابابا ضمن العائلة والقبيلة، مما يعكس ارتباطًا جماعيًا بالأرض والهوية.","de":"Während andere Gesellschaften Ahnentafeln in nationalen Archiven führen, bleibt Whakapapa bei den Māori in der Obhut von Familie und Stamm – ein Ausdruck kollektiver Verbundenheit mit Land und Identität.","en":"While other societies keep genealogies in national archives, Māori whakapapa remains in the care of family and tribe, reflecting collective ties to land and identity."}},{"id":"oce-002","version":2,"slug":"powhiri-the-welcome-that-decides-whether-two-groups-can-meet","contentType":"note","category":"social-behaviour","title":{"ar":"البووهيري: ترحيب يقرر إن كان فريقان سيلتقيان","de":"Pōwhiri: die Begrüßung, die über Begegnung entscheidet","en":"Pōwhiri: the welcome that decides whether two groups can meet"},"deck":{"ar":"في الماريه، يبدأ الترحيب الرسمي بنداء الكارانغا، ثم خطب، ثم هونغي، مع كوهة توضع على الأرض.","de":"Auf dem Marae beginnt die formelle Begrüßung mit dem Karanga-Ruf, gefolgt von Reden, dem Hongi und einem Koha auf dem Boden.","en":"On the marae, a formal welcome begins with the karanga call, then speeches, then the hongi, with a koha laid on the ground."},"teaser":{"ar":"كيف يقرر تقليد الماوري أن مجموعتين يمكن أن تلتقيا؟ من الكارانغا إلى الهونغي، طقوس تحدد نوايا الزوار.","de":"Wie entscheidet eine Māori-Begrüßung, ob zwei Gruppen zusammenkommen? Vom Karanga bis zum Hongi – ein Ritual, das Absichten der Gäste liest.","en":"How does a Māori welcome decide whether two groups can meet? From karanga to hongi, a ritual that reads the visitors' intentions."},"readingMinutes":1,"sections":{"ar":[{"heading":"خطوات اللقاء على الماريه","paragraphs":["البووهيري هو ترحيب رسمي على الماريه يبدأ بالكارانغا، نداء متبادل بين نساء المجموعة المضيفة والزوار. ثم تأتي الخطب (فهايكورو)، وتُختتم كل خطبة عادةً بأغنية أو هاكا من مجموعة المتحدث نفسه.","بعد ذلك يتلامس الأنفان في الهونغي. كان الطقس قديماً يتيح لتانغاتا وهنوا قراءة نوايا المانهوهيري وتجنب الصراع؛ واليوم يشهد زيارات وحفلات تخرج وافتتاحات وتوقيع معاهدات."]},{"heading":"الكوهة والويرو: إشارات الثقة","paragraphs":["يُوضع الكوهة، وغالباً نقود في مظروف، على الأرض من قبل آخر متحدث من الزوار، ويلتقطه آخر متحدث من المضيفين. ولضيف مهم جداً، قد يضع محارب أولاً ويرو، تحدياً على الزائر رفعه قبل أن يستمر الترحيب. يختلف ترتيب الخطب ومن يتحدث أخيراً محلياً، وتُستخدم أشكال أقصر مثل الميهي وهكاتاو للمناسبات الأقل رسمية."]}],"de":[{"heading":"Die Schritte der Begegnung auf dem Marae","paragraphs":["Ein Pōwhiri ist eine formelle Begrüßung auf einem Marae und beginnt mit dem Karanga, einem Wechselruf zwischen Frauen der Gastgeber- und der Besuchergruppe. Es folgen Reden (Whaikōrero), jede meist mit einem Waiata oder Haka der eigenen Gruppe abgeschlossen.","Danach drücken Besucher und Gastgeber im Hongi die Nasen aneinander. Früher ließ das Ritual die Tangata Whenua die Absichten der Manuhiri erkennen und Konflikte vermeiden; heute markiert es Besuche, Abschlüsse, Eröffnungen und Vertragsunterzeichnungen."]},{"heading":"Koha und Wero: Zeichen des Vertrauens","paragraphs":["Ein Koha, oft Geld im Umschlag, wird vom letzten Redner der Gäste auf den Boden gelegt und vom letzten Gastgeber-Redner aufgehoben. Für besonders wichtige Gäste legt ein Krieger zuerst ein Wero nieder, eine Herausforderung, die der Besucher aufheben muss, bevor die Begrüßung weitergeht. Die Reihenfolge der Reden und wer zuletzt spricht, wird lokal ausgehandelt, und für weniger formelle Anlässe gibt es kürzere Formen wie das Mihi Whakatau."]}],"en":[{"heading":"The steps of encounter on the marae","paragraphs":["A pōwhiri is a formal welcome onto a marae, beginning with the karanga, a call exchanged between women of the host and visitor groups. Speeches (whaikōrero) follow, each usually closed with a waiata or haka by the speaker's own group.","Then visitors and hosts press noses in the hongi. The ritual once let tangata whenua read the intentions of manuhiri and avoid conflict; now it marks visits, graduations, openings and treaty signings."]},{"heading":"Koha and wero: signals of trust","paragraphs":["A koha, often money in an envelope, is placed on the ground by the final visiting speaker and picked up by the final host speaker. For an especially important guest, a warrior may first lay down a wero, a challenge the visitor must pick up before the welcome can proceed. The order of speeches and who speaks last is negotiated locally, and shorter forms such as the mihi whakatau are used for less formal occasions."]}]},"context":{"countries":["NZ"],"region":"Aotearoa New Zealand","community":"Māori","continent":"oceania","languages":["mi","en"],"period":"contemporary"},"tags":["social-behaviour","Aotearoa New Zealand"],"sources":[{"organization":"Wikipedia","title":{"ar":"Pōwhiri","de":"Pōwhiri","en":"Pōwhiri"},"url":"https://en.wikipedia.org/wiki/P%C5%8Dwhiri","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Marae","de":"Marae","en":"Marae"},"url":"https://en.wikipedia.org/wiki/Marae","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"ينتظر الزوار عند البوابة حتى يبدأ الكارانغا، ثم يدخلون ككتلة واحدة، ويجلسون خلف متحدثهم، وبعد الخطبة الأخيرة يُوضع الكوهة على الأرض.","de":"Die Besucher warten am Tor, bis das Karanga beginnt, gehen als Block hinein, setzen sich hinter ihren Redner, und nach der letzten Rede wird das Koha auf den Boden gelegt.","en":"Visitors wait at the gate until the karanga begins, walk in as a block, sit behind their speaker, and after the last speech the koha is laid on the ground."},"misunderstanding":{"ar":"ليس البووهيري مجرد ترحيب شكلي؛ إنه عملية تفاوض على الثقة، والويرو ليس عدواناً بل اختباراً لنوايا الزائر.","de":"Ein Pōwhiri ist keine bloße Höflichkeitsformel, sondern ein Aushandeln von Vertrauen; das Wero ist keine Aggression, sondern eine Prüfung der Absichten.","en":"A pōwhiri is not just a ceremonial greeting; it is a negotiation of trust, and the wero is not aggression but a test of the visitor's intentions."},"comparison":{"ar":"يشبه البووهيري بروتوكولاً دبلوماسياً، لكنه يُقام على أرض الماريه ويُشارك فيه المجتمع بأسره، لا الوفود فقط.","de":"Der Pōwhiri ähnelt einem diplomatischen Protokoll, findet aber auf dem Marae statt und bezieht die ganze Gemeinschaft ein, nicht nur Delegationen.","en":"A pōwhiri resembles a diplomatic protocol, but it takes place on the marae and involves the whole community, not just delegations."}},{"id":"oce-003","version":2,"slug":"kia-ora-how-one-maori-phrase-became-everyday-new-zealand-english","contentType":"language","category":"languages","title":{"ar":"كيا أورا: تحية الماوري في الحياة اليومية","de":"Kia ora: Ein Gruß wird Alltag in Neuseeland","en":"Kia ora: a Māori greeting in daily life"},"deck":{"ar":"كيف صارت تحية ماورية تعني الحياة والصحة جزءاً من الإنجليزية النيوزيلندية اليومية.","de":"Wie ein Māori-Wunsch nach Leben und Gesundheit zum festen Teil des neuseeländischen Englisch wurde.","en":"How a Māori wish for life and health became ordinary New Zealand English."},"teaser":{"ar":"كلمة تبدأ كتحية وتنتهي كاتفاق، وتتغيّر صيغتها بحسب عدد الأشخاص: حكاية عبارة صغيرة ذات أثر كبير.","de":"Ein Wort beginnt als Gruß und endet als Zustimmung, und es verändert sich je nach Zahl der Angesprochenen: die Geschichte einer kleinen, wirkungsvollen Wendung.","en":"A word that starts as a greeting and ends as agreement, shifting with the number of people addressed: the story of a small phrase with wide reach."},"readingMinutes":1,"sections":{"ar":[{"heading":"تحية تعني الحياة","paragraphs":["كيا أورا تعني حرفياً تمنّي الحياة والصحة: كلمة «كيا» تمنٍّ، وكلمة «أورا» حياة وصحة وحيوية، فيصير المعنى «كن بخير». وتُستخدم تحيةً ووداعاً وشكراً وموافقةً على كلام متحدث في اجتماع، والموقف هو الذي يحدد المعنى.","تتغير الصيغة بحسب العدد: كيا أورا كوي لشخص واحد، وكيا أورا كوروا لشخصين، وكيا أورا كوتو لثلاثة فأكثر. ويختلف الاستخدام والنطق والكتابة بحسب المنطقة والجيل، فليس كل نيوزيلندي يتحدث بلغة الماوري، وقد طال غياب علامات المدّ عن المطبوعات."]},{"heading":"من الهاتف إلى الطائرة","paragraphs":["في عام 1984 خُفِّضت رتبة عاملة الهاتف في أوكلاند نايدا غلافيش لأنها كانت تحيي المتصلين بعبارة «كيا أورا»؛ رفضت التوقف، ثم أُعيدت إلى منصبها بعد غضب شعبي.","اليوم العبارة مغروسة في الحياة الوطنية: مجلة الخطوط الجوية النيوزيلندية تحمل اسم كيا أورا، ولغة الماوري صارت لغة رسمية عام 1987."]}],"de":[{"heading":"Ein Gruß, der Leben wünscht","paragraphs":["Kia ora wünscht wörtlich Leben und Gesundheit: kia ist ein Wunsch, ora bedeutet Leben, Gesundheit und Vitalität, zusammen heißt es also „sei wohlauf“. Es dient als Hallo, Abschied, Dank und Zustimmung zu einer Aussage in einer Besprechung; die Situation entscheidet, welche Bedeutung gilt.","Die Form richtet sich nach der Zahl: kia ora koe für eine Person, kia ora kōrua für zwei, kia ora koutou für drei oder mehr. Gebrauch, Schreibweise und Aussprache variieren je nach Region und Generation; nicht jeder Neuseeländer spricht te reo, und Längenzeichen fehlten in gedruckten Texten lange."]},{"heading":"Vom Telefon ins Flugzeug","paragraphs":["1984 wurde die Telefonistin Naida Glavish in Auckland degradiert, weil sie Anrufer mit „kia ora“ begrüßte; sie weigerte sich aufzuhören und wurde nach öffentlichem Protest wieder eingesetzt.","Heute ist die Wendung im nationalen Leben verankert: Das Bordmagazin von Air New Zealand heißt Kia Ora, und te reo Māori wurde 1987 Amtssprache."]}],"en":[{"heading":"A greeting that wishes life","paragraphs":["Kia ora literally wishes life and health: kia is a wish, and ora is life, health and vitality, so the phrase means 'be well'. It works as hello, goodbye, thanks and agreement with a speaker at a meeting, and the situation decides which.","Number can be marked: kia ora koe for one person, kia ora kōrua for two, kia ora koutou for three or more. Usage, spelling and pronunciation vary by region and generation; not every New Zealander speaks te reo, and macrons were long omitted in print."]},{"heading":"From the phone line to the plane","paragraphs":["In 1984 Auckland telephone operator Naida Glavish was demoted for greeting callers with 'kia ora'; she refused to stop and was later reinstated after public outcry.","The phrase is embedded in national life: Air New Zealand's inflight magazine is called Kia Ora, and te reo Māori became an official language in 1987."]}]},"context":{"countries":["NZ"],"region":"Aotearoa New Zealand","community":"Māori","continent":"oceania","languages":["mi","en"],"period":"contemporary"},"tags":["languages","Aotearoa New Zealand"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kia ora","de":"Kia ora","en":"Kia ora"},"url":"https://en.wikipedia.org/wiki/Kia_ora","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Māori language","de":"Māori language","en":"Māori language"},"url":"https://en.wikipedia.org/wiki/M%C4%81ori_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يسلّم سائق حافلة على كل راكب بعبارة «كيا أورا»، ويفتتح زميل بريداً إلكترونياً بعبارة «كيا أورا كوتو» قبل الدخول في الموضوع.","de":"Ein Busfahrer begrüßt jeden Fahrgast mit „kia ora“, und eine Kollegin beginnt eine E-Mail mit „Kia ora koutou“, bevor sie zum Punkt kommt.","en":"A bus driver greets each passenger with 'kia ora', and a colleague opens an email with 'Kia ora koutou' before getting to the point."},"misunderstanding":{"ar":"يظن بعض الغرباء أنها مجرد تحية سياحية، لكنها تعمل أيضاً شكراً وموافقةً، وتتغير صيغتها بحسب عدد المخاطَبين.","de":"Manche Auswärtige halten sie für einen rein touristischen Gruß, doch sie dient auch als Dank und Zustimmung und ändert ihre Form je nach Zahl der Angesprochenen.","en":"Outsiders sometimes take it as a tourist-only hello, but it also serves as thanks and agreement, and its form changes with how many people are addressed."},"comparison":{"ar":"تشبه تحية صباحية عابرة في لغات أخرى، لكن الفارق أنها تحمل معنى الحياة والصحة وتُصرَّف بحسب العدد.","de":"Sie ähnelt einem flüchtigen Morgengruß in anderen Sprachen, trägt aber die Bedeutung von Leben und Gesundheit und wird nach Zahl gebeugt.","en":"It resembles a casual morning greeting elsewhere, yet it carries a wish for life and health and shifts with number."},"expression":{"original":"Kia ora","language":"te reo Māori","gloss":{"ar":"كن بخير — تُستخدم تحيةً ووداعاً وشكراً وموافقةً.","de":"Sei wohlauf — als Hallo, Abschied, Dank und Zustimmung verwendet.","en":"Be well — used as hello, goodbye, thank you and agreement."},"usage":{"ar":"تُقال عند اللقاء والافتراق وفي البريد الإلكتروني، وللجمع تُقال كيا أورا كوتو.","de":"Beim Treffen, beim Abschied und in E-Mails; für mehrere Personen sagt man kia ora koutou.","en":"Said at meetings and partings and in emails; for a group, kia ora koutou."},"transliteration":"KEE-ah O-rah"}},{"id":"oce-004","version":2,"slug":"pepeha-introducing-yourself-by-mountain-river-and-ancestor","contentType":"language","category":"communication","title":{"ar":"البِيبِيهَا: تقديم النفس بالجبل والنهر","de":"Pepeha: Sich vorstellen mit Berg und Fluss","en":"Pepeha: Introducing Yourself by Mountain and River"},"deck":{"ar":"في نيوزيلندا، يبدأ كثيرون تعريفهم بأنفسهم من الأرض: جبل، نهر، زورق، قبيلة، ثم الاسم.","de":"In Neuseeland beginnen viele ihre Selbstvorstellung mit dem Land: Berg, Fluss, Kanu, Stamm – und erst dann der Name.","en":"In Aotearoa New Zealand, many begin self-introduction with the land: mountain, river, canoe, iwi — and then the name."},"teaser":{"ar":"البِيبِيهَا صيغة تعريفية تربط الشخص بأرضه ومجتمعه، تُقال في اللقاءات وتُعلَّم في المدارس، فتصبح خريطة انتماء لا مجرد سيرة.","de":"Das Pepeha ist eine formelhafte Selbstvorstellung, die Menschen mit Land und Gemeinschaft verbindet. Es wird in Versammlungen gesprochen und in Schulen gelehrt.","en":"A pepeha is a formulaic self-introduction that ties a person to land and community. It is spoken at gatherings and taught in schools, making it a map of belonging."},"readingMinutes":1,"sections":{"ar":[{"heading":"من الأرض إلى الاسم","paragraphs":["البِيبِيهَا تعريف ذاتي صيغي يسرد صلات الإنسان بالأرض: الجبل، النهر، الزورق، القبيلة الكبرى، القبيلة الفرعية، الماراي (الساحة المجتمعية)، العائلة، ثم الاسم. يبدأ الشكل المعتاد بالأرض، مثل «Ko Kirimoko te maunga» أي «كيريموكو هو الجبل»، ثم «ko Waitati te awa» أي «وايتاتي هو النهر».","يمكن للشخص الواحد أن يكون له أكثر من بِيبِيهَا، إذا ارتبط بعدة قبائل أو بالمكان الذي نشأ فيه. يُقدَّم في اللقاءات الرسمية (hui) والتحيات (mihi)، ويُدرَّس في المدارس ليعرف الأطفال موقعهم من الأرض."]},{"heading":"انتماء لا سيرة فقط","paragraphs":["لأن البِيبِيهَا يربط الهوية بالإقليم، فهو ادعاء بالانتماء بقدر ما هو سيرة قصيرة. تختلف الصيغة باختلاف القبائل والأجيال، فبعضها يقدم الجبل قبل النهر وبعضها العكس، كما تتباين بين الأجيال في المدارس الحضرية والأرياف."]}],"de":[{"heading":"Vom Land zum Namen","paragraphs":["Ein Pepeha ist eine formelhafte Selbstvorstellung, die Verbindungen zum Land auflistet: Berg, Fluss, Kanu, Iwi, Hapū, Marae, Familie und Name. Die übliche Form beginnt mit dem Land, etwa „Ko Kirimoko te maunga“ („Kirimoko ist der Berg“) und dann „ko Waitati te awa“ („der Waitati ist der Fluss“).","Eine Person kann mehr als ein Pepeha haben, zum Beispiel bei Verbindungen zu mehreren Iwi oder zum Ort, an dem sie aufgewachsen ist. Es wird bei Hui und Mihi vorgetragen und in Schulen gelehrt, damit Kinder sich in Beziehung zum Land verorten können."]},{"heading":"Zugehörigkeit, nicht nur Biografie","paragraphs":["Weil das Pepeha Identität an Territorium bindet, ist es ebenso ein Anspruch auf Zugehörigkeit wie eine kurze Biografie. Die Form variiert regional und generationell: Manche Iwi nennen den Berg vor dem Fluss, andere umgekehrt, und städtische Schulen unterscheiden sich von ländlichen."]}],"en":[{"heading":"From Land to Name","paragraphs":["A pepeha is a formulaic self-introduction listing connections to land: mountain, river, canoe, iwi, hapū, marae, family and name. The standard shape starts with the land, as in 'Ko Kirimoko te maunga' ('Kirimoko is the mountain') and then 'ko Waitati te awa' ('the Waitati is the river').","One person can have more than one pepeha, for example when linked to several iwi or to the place they grew up. It is given at hui and mihi, and it is taught in schools so that children can place themselves in relation to the land."]},{"heading":"Belonging, Not Just Biography","paragraphs":["Because it ties identity to territory, a pepeha is a claim about belonging as much as a short biography. The form varies regionally and generationally: some iwi name the mountain before the river, others reverse it, and urban schools differ from rural ones."]}]},"context":{"countries":["NZ"],"region":"Aotearoa New Zealand","community":"Māori","continent":"oceania","languages":["mi","en"],"period":"contemporary"},"tags":["communication","Aotearoa New Zealand"],"sources":[{"organization":"Wikipedia","title":{"ar":"Pepeha","de":"Pepeha","en":"Pepeha"},"url":"https://en.wikipedia.org/wiki/Pepeha","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Whakapapa","de":"Whakapapa","en":"Whakapapa"},"url":"https://en.wikipedia.org/wiki/Whakapapa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في طابور الصباح، تقدم طالبة بِيبِيهَاها — الجبل، النهر، الزورق، القبيلة — فيعرف المعلم أي ماراي يجب مخاطبته لطلب الإذن.","de":"Bei der Schulversammlung gibt eine Schülerin ihr Pepeha – Berg, Fluss, Kanu, Iwi – und die Lehrkraft weiß nun, welches Marae für eine Genehmigung anzufragen ist.","en":"At assembly a student gives her pepeha — mountain, river, canoe, iwi — and the teacher now knows which marae to approach for permission."},"misunderstanding":{"ar":"لا يوجد بِيبِيهَا واحد معياري: تختلف القبائل في الترتيب والمحتوى، وبِيبِيهَا غير الماوريين تكيُّف حديث وليست تقليدًا قديمًا.","de":"Es gibt kein einheitliches Standard-Pepeha: Iwi unterscheiden sich in Reihenfolge und Inhalt, und Pepeha von Nicht-Māori sind eine neuere Anpassung, keine alte Tradition.","en":"There is no single standard pepeha: iwi differ in order and content, and pepeha by non-Māori are a recent adaptation rather than an old tradition."},"comparison":{"ar":"يشبه البِيبِيهَا بطاقة تعريف، لكنه يبدأ بالجغرافيا لا بالاسم، ويُقال أمام الجماعة لا يُقرأ في صمت.","de":"Ein Pepeha ähnelt einem Steckbrief, beginnt aber mit der Geografie statt mit dem Namen und wird vor der Gemeinschaft gesprochen, nicht still gelesen.","en":"A pepeha resembles a profile, but it starts with geography rather than name and is spoken before a group, not read silently."},"expression":{"original":"Ko Kirimoko te maunga, ko Waitati te awa","language":"te reo Māori","gloss":{"ar":"كيريموكو هو الجبل، وايتاتي هو النهر — مطلع بِيبِيهَا مسجل لقبيلة كاي تاهو.","de":"Kirimoko ist der Berg, Waitati ist der Fluss – die Anfangssätze eines überlieferten Pepeha der Kāi Tahu.","en":"Kirimoko is the mountain, Waitati is the river — the opening lines of a recorded Kāi Tahu pepeha."},"usage":{"ar":"تُقال في افتتاح التحية (mihi) أو التعريف بالنفس في اللقاءات.","de":"Wird zu Beginn einer Mihi oder Selbstvorstellung bei Zusammenkünften gesprochen.","en":"Spoken at the start of a mihi or self-introduction at gatherings."},"transliteration":"ko KEE-ree-mo-ko teh MAH-oo-nga, ko WY-tah-tee teh AH-wah"}},{"id":"oce-005","version":2,"slug":"kaitiakitanga-and-rahui-guardianship-as-a-working-restriction","contentType":"note","category":"nature-and-seasons","title":{"ar":"كاتياكيتانغا وراهوي: الوصاية كقيد عملي","de":"Kaitiakitanga und rāhui: Hüterschaft als praktische Einschränkung","en":"Kaitiakitanga and rāhui: guardianship as a working restriction"},"deck":{"ar":"الوصاية على البيئة في آوتياروا نيوزيلندا ليست شعارًا، بل واجب متجذر في النسب وممارسة يومية تفرض قيودًا مؤقتة.","de":"Umwelthüterschaft in Aotearoa Neuseeland ist keine bloße Parole, sondern eine aus Abstammung erwachsende Pflicht und alltägliche Praxis mit zeitweiligen Beschränkungen.","en":"Environmental guardianship in Aotearoa New Zealand is not a slogan but a duty rooted in whakapapa and a daily practice that imposes temporary limits."},"teaser":{"ar":"كاتياكيتانغا تعني الوصاية على الأرض والماء والكائنات، وراهوي قيد مؤقت يفرضه الحراس لحماية الناس والطبيعة.","de":"Kaitiakitanga bedeutet Hüterschaft über Land, Wasser und Arten; rāhui ist eine vorübergehende Einschränkung, die Hüter zum Schutz von Mensch und Natur verhängen.","en":"Kaitiakitanga means guardianship of land, water and species; a rāhui is a temporary restriction placed by guardians to protect people and nature."},"readingMinutes":1,"sections":{"ar":[{"heading":"واجب ينبع من النسب","paragraphs":["كاتياكيتانغا هي وصاية على البيئة؛ الكاتياكي هو الحارس، والواجب ينبع من روابط النسب بين الناس والأرض والماء والأنواع. دخلت المصطلح القانون النيوزيلندي عبر قانون إدارة الموارد لعام 1991، الذي يدرجها كمسألة ذات أهمية وطنية للمجالس.","وراهوي هو قيد مؤقت يضعه الحراس: قد يُطلب من الناس عدم السباحة أو الصيد أو جمع المحار من منطقة محددة. تُستخدم الراهوي بعد حالات الغرق، ولسلامة الغذاء، وللحفاظ على البيئة، وللسماح لمزرعة المحار بالتعافي، وقد تستمر أيامًا أو سنوات."]},{"heading":"سلطة متنازع عليها","paragraphs":["يسمح قانون المصايد لعام 1996 لوزارة الصناعات الأولية بفرض الراهوي، لكن الهابو يجادلون بأن السلطة لهم وليست للدولة. تختلف الممارسة عبر الأجيال والمناطق: بعض الشباب يتعلمون الراهوي عبر وسائل التواصل، بينما يتمسك كبار السن بالبروتوكولات التقليدية."]}],"de":[{"heading":"Eine Pflicht aus der Abstammung","paragraphs":["Kaitiakitanga ist die Hüterschaft der Umwelt; ein kaitiaki ist ein Hüter, und die Pflicht erwächst aus whakapapa-Bindungen zwischen Menschen und Land, Wasser und Arten. Der Begriff gelangte durch den Resource Management Act 1991 in neuseeländisches Recht, der Kaitiakitanga als Angelegenheit von nationaler Bedeutung für Räte auflistet.","Ein rāhui ist eine vorübergehende Beschränkung, die von Hütern verhängt wird: Menschen können gebeten werden, in einem bestimmten Gebiet nicht zu schwimmen, zu fischen oder Schalentiere zu sammeln. Rāhui werden nach Ertrinkungsunfällen, aus Lebensmittelsicherheit, zum Naturschutz und zur Erholung von Muschelbetten eingesetzt und können Tage oder Jahre dauern."]},{"heading":"Umstrittene Autorität","paragraphs":["Der Fisheries Act 1996 erlaubt dem Ministry for Primary Industries, rāhui zu verhängen, aber hapū argumentieren, dass die Autorität ihnen und nicht dem Staat gehört. Die Praxis variiert regional und Generationen: Manche Jüngere lernen rāhui über soziale Medien, während Ältere an traditionellen Protokollen festhalten."]}],"en":[{"heading":"A duty that grows from whakapapa","paragraphs":["Kaitiakitanga is guardianship of the environment; a kaitiaki is a guardian, and the duty grows out of whakapapa ties between people and land, water and species. It entered New Zealand law through the Resource Management Act 1991, which lists kaitiakitanga as a matter of national importance for councils.","A rāhui is a temporary restriction placed by kaitiaki: people may be asked not to swim, fish or take shellfish from a defined area. Rāhui are used after drownings, for food safety, for conservation and to let a shellfish bed recover, and they can last days or years."]},{"heading":"Authority that is contested","paragraphs":["The Fisheries Act 1996 allows the Ministry for Primary Industries to impose rāhui, but hapū argue that the authority belongs to them rather than the state. Practice varies by region and generation: some younger people learn about rāhui through social media, while elders hold to traditional protocols."]}]},"context":{"countries":["NZ"],"region":"Aotearoa New Zealand","community":"Māori","continent":"oceania","languages":["mi","en"],"period":"contemporary"},"tags":["nature-and-seasons","Aotearoa New Zealand"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kaitiakitanga","de":"Kaitiakitanga","en":"Kaitiakitanga"},"url":"https://en.wikipedia.org/wiki/Kaitiakitanga","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Rāhui","de":"Rāhui","en":"Rāhui"},"url":"https://en.wikipedia.org/wiki/R%C4%81hui","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"بعد حادث غرق، تفرض هابو راهوي على الخليج؛ تضع المجالس لافتات، ويخبر نادي ركوب الأمواج الزوار بعدم السباحة، ويُرفع القيد بعد مراسم.","de":"Nach einem Ertrinkungsunfall verhängt ein hapū ein rāhui über die Bucht; der Rat stellt Schilder auf, der Surfclub informiert Besucher, nicht zu schwimmen, und die Beschränkung wird nach einer Zeremonie aufgehoben.","en":"After a drowning, a hapū places a rāhui on the bay; the council puts up signs, the surf club tells visitors not to swim, and the restriction is lifted after a ceremony."},"misunderstanding":{"ar":"يُفهم راهوي أحيانًا كحظر دائم أو كإجراء حكومي، لكنه مؤقت وتقرره الجهة الحارسة المحلية.","de":"Rāhui wird manchmal als dauerhaftes Verbot oder staatliche Maßnahme missverstanden, ist aber vorübergehend und wird von lokalen Hütern beschlossen.","en":"Rāhui is sometimes mistaken for a permanent ban or a government measure, but it is temporary and decided by local guardians."},"comparison":{"ar":"يشبه راهوي إغلاقًا مؤقتًا لمنطقة طبيعية، لكنه يختلف في أنه ينبع من التزام أخلاقي وروحي وليس فقط من لوائح إدارية.","de":"Rāhui ähnelt einer temporären Sperrung eines Naturgebiets, unterscheidet sich aber durch seine ethische und spirituelle Verpflichtung, nicht nur durch Verwaltungsvorschriften.","en":"A rāhui resembles a temporary closure of a natural area, but it differs in arising from an ethical and spiritual obligation, not only administrative rules."}},{"id":"oce-006","version":2,"slug":"kapa-haka-why-the-songs-are-judged-like-speeches","contentType":"note","category":"music-and-dance","title":{"ar":"كابا هاكا: لماذا تُحكم الأغاني كالخطابات","de":"Kapa Haka: Warum Lieder wie Reden bewertet werden","en":"Kapa haka: why the songs are judged like speeches"},"deck":{"ar":"في مهرجان تي ماتاتيني، لا يقتصر التقييم على الحركة، بل تمتد الأحكام إلى الكلمات والتركيب والأداء ككل.","de":"Beim Te Matatini-Festival zählt nicht nur die Bewegung, sondern auch Text, Aufbau und Gesamtwirkung.","en":"At Te Matatini, judging goes beyond movement to words, composition and the building of a whole set."},"teaser":{"ar":"كابا هاكا يجمع بين الغناء والرقص، لكن الكلمات تحمل وزنًا كالخطابة، خاصة في المسابقات الوطنية حيث تُقاس الجودة على أساس التكوين والنطق والحركة.","de":"Kapa Haka verbindet Gesang und Tanz, doch die Worte haben rhetorisches Gewicht – besonders im Wettbewerb, wo Komposition, Diktion und Bewegung bewertet werden.","en":"Kapa haka blends song and dance, but the words carry rhetorical weight—especially in competition, where teams are judged on composition, diction and movement."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما وراء الرقص: معاني الكلمات","paragraphs":["كابا هاكا يعني حرفيًا 'مجموعة' (كابا) و'رقصة' (هاكا)، لكنه يشمل أغاني وايآتا-آ-رينغا ورقص البوي وهاكا وتراتيل موتيآتيا. الهاكا ليست رقصات حرب فقط، بل تُؤدى للترحيب والحزن والاحتفال والاحتجاج، والكلمات لا تقل أهمية عن الحركة.","في المسابقات الوطنية، تُقيَّم الفرق على التكوين والنطق والحركة وبناء مجموعة كاملة، لذا يجب تبرير الابتكار داخل التقاليد. هذا يجعل الأغنية أشبه بخطاب يُلقى ويُحكم عليه."]},{"heading":"منافسة ومجتمع: التعلم عبر الأجيال","paragraphs":["انطلقت المسابقة الوطنية عام 1972 وأصبحت الآن تي ماتاتيني، مهرجانًا يُقام كل عامين وتستضيفه قبيلة مختلفة في كل مرة. كما أن كابا هاكا نشاط مدرسي ومجتمعي، وللكثير من المتعلمين هو الطريق الرئيسي للعودة إلى لغة تي ريو موري.","يختلف الأسلوب واللهجات وقواعد المسابقة بين القبائل وتتغير بمرور الوقت؛ فليس كل الماوريين يمارسون كابا هاكا، وهناك جدل حول التسويق التجاري. يلاحظ المراقبون أن الأجيال الشابة تدمج عناصر جديدة، بينما يتمسك كبار السن بالأشكال التقليدية."]}],"de":[{"heading":"Mehr als Tanz: Die Bedeutung der Worte","paragraphs":["Kapa Haka bedeutet wörtlich 'Gruppe' (kapa) und 'Tanz' (haka), umfasst aber Waiata-ā-ringa, Poi, Haka und Mōteatea-Gesänge. Haka sind nicht nur Kriegstänze: Sie dienen der Begrüßung, Trauer, Feier und Protest, und die Worte zählen ebenso wie die Bewegung.","Bei nationalen Wettbewerben werden Teams nach Komposition, Diktion, Bewegung und dem Aufbau eines ganzen Sets bewertet. Innovation muss daher innerhalb der Tradition begründet werden – das Lied wird wie eine Rede beurteilt."]},{"heading":"Wettbewerb und Gemeinschaft: Lernen über Generationen","paragraphs":["Der nationale Wettbewerb läuft seit 1972 und heißt heute Te Matatini, ein zweijährliches Festival, das jeweils von einem anderen Iwi ausgerichtet wird. Kapa Haka ist auch Schul- und Gemeinschaftsaktivität und für viele Lernende der Hauptweg zurück zur Sprache Te Reo Māori.","Stile, Dialekte und Wettbewerbsregeln variieren zwischen Iwi und ändern sich im Laufe der Zeit; nicht alle Māori praktizieren Kapa Haka, und Kommerzialisierung ist umstritten. Beobachter bemerken, dass jüngere Generationen neue Elemente einbringen, während Ältere an traditionellen Formen festhalten."]}],"en":[{"heading":"Beyond the dance: the weight of words","paragraphs":["Kapa haka means 'group' (kapa) and 'dance' (haka), but the art covers waiata-ā-ringa action songs, poi, haka and mōteatea chants. Haka are not only war dances: they are performed for welcome, grief, celebration and protest, and the words matter as much as the movement.","In national competition, teams are judged on composition, diction, movement and the building of a whole set, so innovation has to be justified inside a tradition. That makes the song something like a speech, delivered and assessed."]},{"heading":"Competition and community: learning across generations","paragraphs":["The national competition has run since 1972 and is now Te Matatini, a biennial festival hosted by a different iwi each time. Kapa haka is also a school and community activity, and for many learners it is the main route back into te reo Māori.","Styles, dialects and competition rules vary between iwi and change over time; not all Māori perform kapa haka, and commercialisation is debated. Observers note that younger generations weave in new elements while elders hold to traditional forms."]}]},"context":{"countries":["NZ"],"region":"Aotearoa New Zealand","community":"Māori","continent":"oceania","languages":["mi","en"],"period":"contemporary"},"tags":["music-and-dance","Aotearoa New Zealand"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kapa haka","de":"Kapa haka","en":"Kapa haka"},"url":"https://en.wikipedia.org/wiki/Kapa_haka","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Te Matatini","de":"Te Matatini","en":"Te Matatini"},"url":"https://en.wikipedia.org/wiki/Te_Matatini","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في تي ماتاتيني، تنتقل فرقة من أربعين شخصًا من ترتيل بطيء إلى هاكا؛ ينهض الجمهور ويكتب الحكام طوال العرض الذي يستمر خمسًا وعشرين دقيقة.","de":"Bei Te Matatini geht ein Team von vierzig Personen von einem langsamen Gesang in einen Haka über; das Publikum erhebt sich und die Jury schreibt während des gesamten fünfundzwanzigminütigen Sets.","en":"At Te Matatini a team of forty moves from a slow chant into a haka; the crowd rises and the judges write through the entire twenty-five-minute set."},"misunderstanding":{"ar":"يُفهم الهاكا أحيانًا على أنه رقصة حرب فقط، لكنه يشمل الترحيب والحزن والاحتفال والاحتجاج، والكلمات فيه جوهرية.","de":"Haka wird manchmal nur als Kriegstanz verstanden, doch er umfasst Begrüßung, Trauer, Feier und Protest – die Worte sind wesentlich.","en":"Haka is sometimes seen only as a war dance, but it covers welcome, grief, celebration and protest—and the words are central."},"comparison":{"ar":"مثل الخطابة، تُحكم كابا هاكا على الوضوح والتركيب والتأثير، وليس فقط على الإيقاع.","de":"Wie eine Rede wird Kapa Haka nach Klarheit, Aufbau und Wirkung beurteilt, nicht nur nach Rhythmus.","en":"Like a speech, kapa haka is judged on clarity, structure and impact, not just rhythm."}},{"id":"oce-007","version":2,"slug":"ta-moko-reading-rank-and-kinship-on-the-skin","contentType":"note","category":"clothing-and-design","title":{"ar":"تاتو الماوري: نسب على الجلد","de":"Tā moko: Rang und Herkunft auf der Haut","en":"Tā moko: reading rank and kinship on the skin"},"deck":{"ar":"في نيوزيلندا، يحكي التاتو الماوري قصة العائلة والمكانة، ويُصنع بالإزميل لا بالإبرة.","de":"In Aotearoa Neuseeland erzählt Tā moko von Familie und Rang – gestochen mit dem Meißel, nicht mit der Nadel.","en":"In Aotearoa New Zealand, tā moko tells a family story through chiselled grooves, not just ink on skin."},"teaser":{"ar":"تاتو الماوري ليس زينة فقط؛ إنه سجل حيّ للنسب والمكانة، يعود بقوة منذ التسعينيات بقيادة فنانين ماوريين ونساء.","de":"Tā moko ist kein Schmuck allein: Es ist ein lebendiges Zeichen von Herkunft und Rang, seit den 1990ern von Māori-Künstlern und Frauen neu belebt.","en":"Tā moko is more than body art: it records genealogy and rank, and since the 1990s Māori artists and women have led a strong revival."},"readingMinutes":1,"sections":{"ar":[{"heading":"علامة تُنقش لا تُرسم","paragraphs":["في نيوزيلندا، يُصنع تاتو الماوري بالإزميل لا بالإبرة، فيبقى الجلد محفورًا قليلًا لا أملس. لهذا يبدو الأثر كأنه جزء من البشرة نفسها.","كانت التصاميم شخصية: تاتو كامل للوجه عند الرجال، وتاتو على الذقن والشفتين عند النساء، يدلّان على المكانة والنسب والدور. وهو تقليد من خمس تقاليد تاتو بولينيزية كبرى."]},{"heading":"عودة بعد صمت","paragraphs":["ضغط التبشير والقانون الاستعماري جعلا هذا التاتو نادرًا معظم القرن العشرين. لكن منذ التسعينيات قاد فنانو الماوري نهضة قوية، وأعادت نساء كثيرات تاتو الذقن.","يختلف الإقبال بين الأجيال والمناطق: بعض المدن تشهد طلبًا أكبر، بينما تبقى القرارات في القرى مرتبطة بمشورة العائلة.","نسخ تصميم شخص آخر يُعدّ انتهاكًا للنسب، لذا تُبنى الأنماط مع صاحبها وعائلته، لا من كتاب."]}],"de":[{"heading":"Eine Markierung, die geritzt wird","paragraphs":["In Aotearoa Neuseeland wird Tā moko mit Meißeln (uhiu) statt Nadeln gemacht, sodass die Haut leicht gerillt bleibt statt glatt.","Die Entwürfe waren persönlich: vollflächiges Gesichtsmoko für Männer, moko kauae an Kinn und Lippen für Frauen – Zeichen von Rang, Genealogie und Rolle. Es ist eine von fünf großen polynesischen Tattoo-Traditionen."]},{"heading":"Wiederbelebung nach langem Schweigen","paragraphs":["Missionarischer Druck und Kolonialgesetze machten moko im 20. Jahrhundert lange selten. Seit den 1990ern führen Māori-Künstlerinnen und -Künstler eine starke Wiederbelebung an, viele Frauen holen moko kauae zurück.","Die Nachfrage variiert regional und generationell: In Städten ist sie oft größer, auf dem Land bleiben Entscheidungen stärker an das Gespräch mit der Familie gebunden.","Fremde Entwürfe zu kopieren gilt als Verletzung der whakapapa, deshalb entstehen Muster gemeinsam mit der Person und ihrer Familie, nicht aus einem Katalog."]}],"en":[{"heading":"A mark cut, not drawn","paragraphs":["In Aotearoa New Zealand, tā moko is made with chisels (uhiu) rather than needles, so the skin stays slightly grooved instead of smooth.","Designs were personal: full-face moko for men, moko kauae on chin and lips for women, marking rank, genealogy and role. It is one of five main Polynesian tattoo traditions."]},{"heading":"Revival after a quiet century","paragraphs":["Missionary pressure and colonial law made moko rare for much of the twentieth century. Since the 1990s, Māori artists have led a strong revival, and many women have reclaimed moko kauae.","Interest varies by region and generation: demand is often higher in cities, while in smaller communities decisions stay closely tied to family discussion.","Copying someone else's design is considered a violation of whakapapa, so patterns are composed with the wearer and their family, never taken from a book."]}]},"context":{"countries":["NZ"],"region":"Aotearoa New Zealand","community":"Māori","continent":"oceania","languages":["mi","en"],"period":"contemporary"},"tags":["clothing-and-design","Aotearoa New Zealand"],"sources":[{"organization":"Wikipedia","title":{"ar":"Tā moko","de":"Tā moko","en":"Tā moko"},"url":"https://en.wikipedia.org/wiki/T%C4%81_moko","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Māori culture","de":"Māori culture","en":"Māori culture"},"url":"https://en.wikipedia.org/wiki/M%C4%81ori_culture","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"شابة تحصل على تاتو الذقن بعد أشهر من النقاش مع عائلتها؛ يرسم الفنان التصميم حول تاريخ عشيرتها لا من قائمة رموز.","de":"Eine junge Frau erhält moko kauae nach Monaten des Gesprächs mit ihrer whānau; die Künstlerin gestaltet das Muster um die Geschichte ihres hapū, nicht aus einer Symbolsammlung.","en":"A young woman receives moko kauae after months of discussion with her whānau; the artist builds the design around her hapū's history rather than a catalogue of symbols."},"misunderstanding":{"ar":"لا توجد قاموس للرموز؛ معاني التاتو شخصية ومرتبطة بنسب صاحبها تحديدًا، ونسخ تصميم يُعدّ ضررًا.","de":"Es gibt kein Wörterbuch der Symbole; Bedeutungen sind persönlich und whakapapa-spezifisch, und das Kopieren eines Entwurfs gilt als schädlich.","en":"There is no dictionary of symbols; moko meanings are personal and whakapapa-specific, and copying a design is considered harmful."},"comparison":{"ar":"مثل تقاليد التاتو في ساموا وهاواي وماركيزاس وتاهيتي، يحمل تاتو الماوري معنى عائليًا لا زخرفيًا.","de":"Wie die Tattoo-Traditionen Samoas, Hawaiis, der Marquesas und Tahitis trägt Tā moko familiäre, nicht dekorative Bedeutung.","en":"Like the tattoo traditions of Samoa, Hawai'i, the Marquesas and Tahiti, tā moko carries family meaning rather than decoration."}},{"id":"oce-008","version":2,"slug":"mana-and-tapu-two-words-that-organise-respect","contentType":"note","category":"beliefs-and-folklore","title":{"ar":"مانا وتابو: كلمتان تنظمان الاحترام","de":"Mana und Tapu: zwei Wörter ordnen Respekt","en":"Mana and tapu: two words that organise respect"},"deck":{"ar":"في الفكر البولينيزي، مانا قوة يمكن اكتسابها أو فقدانها، وتابو حالة حظر مقدس. معًا تحمي مانا الأماكن المقدسة.","de":"Mana ist eine Kraft, die vererbt, erworben oder verloren werden kann. Tapu bezeichnet eine heilige Einschränkung. Zusammen schützen sie Würde und Gemeinschaft.","en":"Mana is a force that can be inherited, earned or lost. Tapu names a state of sacred restriction. Together they protect dignity and community."},"teaser":{"ar":"مانا وتابو مفهومان يوجهان العلاقات والاحترام في مجتمعات بولينيزيا، حيث يرتبط المكانة بالعطاء والحظر بالقداسة.","de":"Mana und Tapu sind zwei Begriffe, die Beziehungen und Respekt in polynesischen Gesellschaften prägen – Status durch Großzügigkeit, Schutz durch heilige Regeln.","en":"Mana and tapu are two concepts that shape relationships and respect in Polynesian societies, where status is shown through generosity and protection through sacred rules."},"readingMinutes":1,"sections":{"ar":[{"heading":"مانا: قوة تُكتسب وتُفقد","paragraphs":["مانا قوة يمكن أن تُورث أو تُكتسب أو تُفقد، وفي الفكر البولينيزي والميلانيزي يمكن لأي شخص أو شيء أن يحملها. في الاستخدام الماوري، مانا هي المكانة والسلطة التي يجب إثباتها من خلال الكرم والرعاية بدلًا من مجرد ادعائها.","يختلف استخدام المصطلح بين المجتمعات البولينيزية وبين الأجيال، لكن الفكرة الأساسية تبقى: المكانة تُظهر في العلاقات اليومية."]},{"heading":"تابو: حظر مقدس يحمي","paragraphs":["تابو يسمي حالة حظر مقدس: الرأس، موقع الدفن، الزعيم أو المولود الجديد يمكن أن يكون تابو، ولا تنطبق هناك القواعد العادية. الاثنان يعملان معًا: مكان تابو يحمي مانا، وانتهاك تابو يضر الشخص والجماعة.","كلمة 'taboo' الإنجليزية جاءت من زيارة جيمس كوك عام 1777 إلى تونغا، حيث سجل tapu، وهي كلمة بولينيزية مستخدمة من هاواي إلى رابا نوي."]}],"de":[{"heading":"Mana: Kraft, die erworben wird","paragraphs":["Mana ist eine Kraft, die vererbt, erworben oder verloren werden kann, und im polynesischen und melanesischen Denken kann jeder oder jedes Ding sie tragen. Im Māori-Gebrauch ist Mana Prestige und Autorität, die durch Großzügigkeit und Fürsorge bewiesen werden muss, statt einfach beansprucht zu werden.","Die Verwendung unterscheidet sich zwischen polynesischen Gesellschaften und Generationen, doch der Kern bleibt: Status zeigt sich im Alltag."]},{"heading":"Tapu: heilige Einschränkung","paragraphs":["Tapu bezeichnet einen Zustand heiliger Einschränkung: Ein Kopf, eine Grabstätte, ein Häuptling oder ein Neugeborenes kann tapu sein, und gewöhnliche Regeln gelten dort nicht. Beide wirken zusammen: Ein tapu-Ort schützt Mana, und die Verletzung von Tapu schadet der Person und der Gruppe.","Das englische Wort 'taboo' stammt von James Cooks Besuch 1777 in Tonga, wo er tapu festhielt – ein polynesisches Wort, das von Hawaii bis Rapa Nui verbreitet ist."]}],"en":[{"heading":"Mana: force that is earned","paragraphs":["Mana is a force that can be inherited, earned or lost, and in Polynesian and Melanesian thought anyone or anything can carry it. In Māori usage mana is prestige and authority that has to be demonstrated through generosity and care rather than simply claimed.","Usage differs between Polynesian societies and between generations, but the core remains: status is shown in everyday relationships."]},{"heading":"Tapu: sacred restriction that protects","paragraphs":["Tapu names a state of sacred restriction: a head, a burial site, a chief or a newborn can be tapu, and ordinary rules do not apply there. The two work together: a tapu place protects mana, and breaching tapu damages both the person and the group.","The English word 'taboo' came from James Cook's 1777 visit to Tonga, where he recorded tapu, a Polynesian word already used from Hawaii to Rapa Nui."]}]},"context":{"countries":["NZ"],"region":"Aotearoa New Zealand","community":"Māori","continent":"oceania","languages":["mi","en"],"period":"contemporary"},"tags":["beliefs-and-folklore","Aotearoa New Zealand"],"sources":[{"organization":"Wikipedia","title":{"ar":"Mana (Oceanic cultures)","de":"Mana (Oceanic cultures)","en":"Mana (Oceanic cultures)"},"url":"https://en.wikipedia.org/wiki/Mana_(Oceanic_cultures)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Tapu (Polynesian culture)","de":"Tapu (Polynesian culture)","en":"Tapu (Polynesian culture)"},"url":"https://en.wikipedia.org/wiki/Tapu_(Polynesian_culture)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"أدوات النحات ورأس الزعيم تابو؛ يتجنب الناس لمسها، وطقس بالماء يرفع الحظر عند انتهاء العمل.","de":"Die Werkzeuge eines Schnitzers und der Kopf eines Häuptlings sind tapu; Menschen meiden die Berührung, und ein Ritual mit Wasser hebt die Einschränkung nach vollendeter Arbeit auf.","en":"A carver's tools and a chief's head are tapu; people avoid touching them, and a ritual with water lifts the restriction when the work is finished."},"misunderstanding":{"ar":"ترجمات مثل 'قوة' و'محظور' تسطح المفاهيم؛ فالاستخدام يختلف بين المجتمعات البولينيزية وبين الأجيال.","de":"Übersetzungen wie 'Macht' und 'Tabu' verflachen die Konzepte; der Gebrauch unterscheidet sich zwischen polynesischen Gesellschaften und Generationen.","en":"Translations such as 'power' and 'taboo' flatten the concepts; usage differs between Polynesian societies and between generations."},"comparison":{"ar":"بينما تشير 'مانا' إلى سلطة تُثبت بالكرم، تشير 'تابو' إلى حظر مقدس يحمي تلك السلطة والمجتمع.","de":"Während Mana eine durch Großzügigkeit bewiesene Autorität meint, bezeichnet Tapu eine heilige Einschränkung, die diese Autorität und die Gemeinschaft schützt.","en":"While mana refers to authority proven through generosity, tapu refers to a sacred restriction that protects that authority and the community."}},{"id":"oce-009","version":2,"slug":"hangi-the-earth-oven-that-feeds-a-hundred-people-at-once","contentType":"scene","category":"food-and-hospitality","title":{"ar":"الهانغي: فرن الأرض الذي يطعم مئة شخص","de":"Hāngī: der Erdo fen, der Hunderte satt macht","en":"Hāngī: the earth oven that feeds a crowd"},"deck":{"ar":"حجارة تُسخَّن بالنار ساعات، ثم تُنزل السلال فوقها وتُغطى بالتراب: طريقة طبخ عملية للجموع.","de":"Steine werden stundenlang über Feuer erhitzt, dann senkt man Körbe mit Essen darauf – und deckt die Grube mit Erde zu.","en":"Stones heat for hours over a big fire, baskets of food are lowered onto them, and earth seals the pit."},"teaser":{"ar":"في نيوزيلندا، يُحفر الفرن في الأرض لا يُبنى فوقها، ويُطهى فيه الطعام ببطء ليصل إلى مئات الضيوف في وقت واحد.","de":"In Neuseeland wird der Ofen in die Erde gegraben statt gebaut, und das Essen gart langsam für viele Gäste auf einmal.","en":"In Aotearoa New Zealand the oven is dug into the ground rather than built above it, cooking slowly for a hundred guests at once."},"readingMinutes":1,"sections":{"ar":[{"heading":"كيف يُبنى الفرن في التراب","paragraphs":["الهانغي فرن حفرة: تُسخَّن الحجارة بنار كبيرة لمدة ثلاث إلى أربع ساعات، ثم تُنزل سلال الطعام فوقها. يوضع اللحم في السلة السفلى والخضار فوقه والمأكولات البحرية في الأعلى، ثم تُغطى أكياس مبللة وأقمشة، ويُردم التراب على الحفرة.","يستغرق الطهي ساعتين إلى أربع، والطريقة عملية تحديدًا لأنها تُطعم جمعًا كبيرًا دون مطبخ تجاري. المكوّنات المعتادة لحم الضأن والخنزير والدجاج والكومارا والبطاطس والقرع والقلقاس."]},{"heading":"تقاليد تتغيّر بين الأجيال","paragraphs":["قبل السلال المعدنية، كان الطعام يُرصّ بين اللحاء وأوراق كبيرة، ثم انتشرت السلال السلكية في أوائل القرن التاسع عشر. الهانغي طريقة وليمة أكثر منه طبخًا يوميًا لمعظم العائلات، والمكوّنات والبروتوكولات تختلف من منطقة إلى أخرى، كما تختلف عادات الأجيال الشابة نحو طهي أسرع وأصغر."]}],"de":[{"heading":"Ein Ofen in der Erde","paragraphs":["Ein Hāngī ist ein Grubenofen: Steine werden drei bis vier Stunden lang über einem großen Feuer erhitzt, dann lässt man Essenskörbe darauf hinab. Fleisch kommt in den unteren Korb, Gemüse darüber, Meeresfrüchte ganz oben; nasse Säcke und Tücher bedecken das Essen, dann wird die Grube mit Erde zugedeckt.","Das Garen dauert zwei bis vier Stunden, und die Methode ist gerade deshalb praktisch, weil sie viele Menschen ohne Profiküche satt macht. Typische Zutaten sind Lamm, Schwein, Huhn, Kūmara, Kartoffeln, Kürbis und Taro."]},{"heading":"Trad ition zwischen Regionen und Generationen","paragraphs":["Vor Metall- und Drahtkörben lag das Essen zwischen Rinde und großen Blättern; Drahtkörbe verbreiteten sich im frühen 19. Jahrhundert. Für die meisten Familien ist Hāngī eher Festessen als Alltagsküche, und Zutaten und Abläufe unterscheiden sich je nach Region – jüngere Generationen kochen oft schneller und in kleineren Mengen."]}],"en":[{"heading":"Building the oven in the ground","paragraphs":["A hāngī is a pit oven: stones are heated by a large fire for three to four hours, then baskets of food are lowered onto them. Meat goes in the bottom basket, vegetables above and seafood on top; wet sacks and cloth go over the food and the pit is covered with earth.","Cooking takes two to four hours, and the method is practical precisely because it feeds a crowd without a commercial kitchen. Typical ingredients are lamb, pork, chicken, kūmara, potato, pumpkin and taro."]},{"heading":"Tradition that shifts by region and age","paragraphs":["Before metal and wire baskets, food was laid between bark and large leaves; wire baskets spread in the early nineteenth century. Hāngī is a feast method rather than daily cooking for most families, and ingredients and protocols vary by region, with younger generations often cooking faster and in smaller batches."]}]},"context":{"countries":["NZ"],"region":"Aotearoa New Zealand","community":"Māori","continent":"oceania","languages":["mi","en"],"period":"contemporary"},"tags":["food-and-hospitality","Aotearoa New Zealand"],"sources":[{"organization":"Wikipedia","title":{"ar":"Hāngī","de":"Hāngī","en":"Hāngī"},"url":"https://en.wikipedia.org/wiki/H%C4%81ng%C4%AB","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Earth oven","de":"Earth oven","en":"Earth oven"},"url":"https://en.wikipedia.org/wiki/Earth_oven","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"لجنة ماراي تعلن عن ٣٠٠ طبق هانغي لجمع التبرعات؛ يشعل المتطوعون النار قبل الفجر ويرفعون السلال بعد الظهر.","de":"Ein Marae-Komitee kündigt 300 Hāngī-Portionen für einen Spendenlauf an; Freiwillige entzünden das Feuer vor der Morgendämmerung und heben die Körbe am Nachmittag heraus.","en":"A marae committee advertises 300 hāngī plates for a fundraiser; volunteers light the fire before dawn and lift the baskets out in the afternoon."},"misunderstanding":{"ar":"يظن البعض أنه طبخ بدائي أو بطيء بلا فائدة، لكنه في الواقع حل عملي لتقديم الطعام لعدد كبير من الناس في وقت واحد.","de":"Manche halten es für primitives oder unnötig langsames Kochen, doch es ist eine praktische Lösung, um viele Menschen gleichzeitig zu bewirten.","en":"Some assume it is primitive or needlessly slow cooking, but it is a practical answer to feeding a large number of people at the same time."},"comparison":{"ar":"الطريقة نفسها تظهر باسم أومو في ساموا ولوفو في فيجي وإيمو في هاواي ومومو في بابوا غينيا الجديدة.","de":"Dieselbe Methode heißt umu in Samoa, lovo in Fidschi, imu in Hawaii und mumu in Papua-Neuguinea.","en":"The same method appears as the umu in Samoa, lovo in Fiji, imu in Hawaii and mumu in Papua New Guinea."}},{"id":"oce-010","version":2,"slug":"the-dreaming-is-not-the-past-law-land-and-story-in-aboriginal-australia","contentType":"note","category":"beliefs-and-folklore","title":{"ar":"الحلم ليس ماضياً في أستراليا","de":"Das Traumzeitalter ist nicht vergangen","en":"The Dreaming is not the past"},"deck":{"ar":"قوانين الأرض والحكايات عند الشعوب الأصلية","de":"Recht, Land und Erzählung bei Aboriginal Australians","en":"Law, land and story among Aboriginal Australians"},"teaser":{"ar":"عند الشعوب الأصلية في أستراليا، الحلم ليس ذكرى قديمة بل قانون حيّ يحفظه الناس في الأرض والطقوس.","de":"Für viele Aboriginal Australians ist das Traumzeitalter keine ferne Erinnerung, sondern lebendiges Recht, das in Land und Zeremonie präsent bleibt.","en":"For many Aboriginal Australians the Dreaming is not distant memory but living law, kept present in country through ceremony and story."},"readingMinutes":1,"sections":{"ar":[{"heading":"الحلم حاضر لا ماضٍ","paragraphs":["الحلم هو الاسم الإنجليزي الذي أطلقه علماء الأنثروبولوجيا على تصورات الشعوب الأصلية عن كائنات أسلافية شكّلت الأرض والبشر والحيوانات والقانون.","لكنه ليس ماضياً يُتذكَّر: الحلم يُفهم على أنه مستمر، والطقوس تجعله حاضراً في الأرض.","لكل جماعة لغوية حكاياتها وقانونها، فثمة مئات التقاليد المتميزة لا أسطورة واحدة."]},{"heading":"معرفة محمية بكلماتها","paragraphs":["المواقع المقدسة والأغاني والتصاميم تُعدّ عمل الأسلاف، ولهذا تُحفظ بعض المعرفة لدى أشخاص بعينهم.","الكلمة الإنجليزية تقريبية، وكثير من المجتمعات يستخدم مصطلحاته الخاصة مثل توكوربا، أو يرفض قراءة «زمن الحلم» كفولكلور.","تختلف هذه الممارسات بين المناطق والأجيال، إذ يحمل الشيوخ التفاصيل بينما يتعلم الشباب في سياقات حضرية."]}],"de":[{"heading":"Gegenwart statt Vergangenheit","paragraphs":["„The Dreaming“ ist die englische Bezeichnung, die Anthropologen den Kosmologien der Aboriginal Australians gaben: Ahnenwesen formten Land, Menschen, Tiere und Recht.","Es ist keine erinnerte Vergangenheit; das Traumzeitalter gilt als fortdauernd, und Zeremonien halten es im Land gegenwärtig.","Jede Sprachgruppe hat eigene Geschichten und eigenes Recht, daher gibt es hunderte Traditionen statt einer einzigen Mythologie."]},{"heading":"Wissen, das geschützt bleibt","paragraphs":["Heilige Orte, Lieder und Muster gelten als Werk der Ahnen, weshalb manches Wissen nur bestimmten Menschen zugänglich ist.","Das englische Wort ist eine Annäherung; viele Gemeinschaften nutzen eigene Begriffe wie Tjukurpa oder lehnen es ab, „Dreamtime“ als Folklore zu lesen.","Je nach Region und Generation unterscheidet sich die Praxis: Ältere tragen Einzelheiten, Jüngere lernen oft in städtischen Zusammenhängen."]}],"en":[{"heading":"A continuing present","paragraphs":["The Dreaming is the English label anthropologists gave to Aboriginal cosmologies in which ancestral beings shaped land, people, animals and law.","It is not a remembered past: the Dreaming is understood as continuing, and ceremony keeps it present in country.","Each language group has its own stories and law, so there are hundreds of distinct traditions rather than one mythology."]},{"heading":"Knowledge that stays restricted","paragraphs":["Sacred sites, songs and designs are treated as the ancestors' work, which is why some knowledge is restricted to particular people.","The English word is an approximation, and many communities use their own terms, such as Tjukurpa, or object to Dreamtime being read as folklore.","Practice varies by region and generation, with elders holding details while younger people often learn in urban settings."]}]},"context":{"countries":["AU"],"region":"Australia","community":"Aboriginal Australians","continent":"oceania","languages":["en"],"period":"contemporary"},"tags":["beliefs-and-folklore","Australia"],"sources":[{"organization":"Wikipedia","title":{"ar":"The Dreaming","de":"The Dreaming","en":"The Dreaming"},"url":"https://en.wikipedia.org/wiki/The_Dreaming","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Australian Aboriginal religion and mythology","de":"Australian Aboriginal religion and mythology","en":"Australian Aboriginal religion and mythology"},"url":"https://en.wikipedia.org/wiki/Australian_Aboriginal_religion_and_mythology","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يشير أحد الشيوخ إلى حفرة ماء ويقول إن السلف توقف هنا؛ والحكاية نفسها تحدد مواقع يجب تجنبها وأغنية تُنشد في الطريق.","de":"Ein Ältester zeigt auf ein Wasserloch und sagt, dort habe der Ahne angehalten; dieselbe Geschichte nennt Orte, die man meidet, und ein Lied für den Weg.","en":"An elder points to a waterhole and says it is where the ancestor stopped; the same story also says which sites to avoid and which song to sing on the way."},"misunderstanding":{"ar":"يظن كثيرون أن الحلم أسطورة موحدة عن الماضي، لكنه قانون حيّ ومتعدد بقدر الجماعات اللغوية.","de":"Viele halten das Traumzeitalter für eine einheitliche Vergangenheitsmythe, doch es ist lebendiges, vielfaches Recht.","en":"Many assume the Dreaming is one uniform myth about the past, but it is living law, as plural as the language groups themselves."},"comparison":{"ar":"حيث تُروى القصص الشعبية للتسلية، تُروى هنا لتنظيم العلاقة بالأرض والمسؤوليات.","de":"Wo Volkserzählungen unterhalten, regeln diese Geschichten den Umgang mit Land und Verantwortung.","en":"Where folk tales entertain, these stories govern obligations to land and to one another."}},{"id":"oce-013","version":2,"slug":"avoidance-relationships-when-respect-means-not-speaking","contentType":"note","category":"social-behaviour","title":{"ar":"علاقات التجنب: عندما يعني الاحترام عدم التحدث","de":"Vermeidungsbeziehungen: Wenn Respekt bedeutet, nicht zu sprechen","en":"Avoidance relationships: when respect means not speaking"},"deck":{"ar":"في بعض مجتمعات السكان الأصليين في أستراليا، يُعبَّر عن الاحترام من خلال تجنب التواصل المباشر مع أقارب معينين، وخاصة بين الشخص وحماته.","de":"In einigen australischen Ureinwohnergesellschaften wird Respekt durch die Vermeidung direkter Kommunikation mit bestimmten Verwandten ausgedrückt, insbesondere zwischen einer Person und ihrer Schwiegermutter.","en":"In some Australian Indigenous societies, respect is expressed by avoiding direct communication with certain relatives, especially between a person and their mother-in-law."},"teaser":{"ar":"تجنب الكلام ليس عداءً، بل شكل من أشكال الاحترام. تعرف على كيفية تطبيق هذه العلاقات في الحياة اليومية.","de":"Vermeidung von Gesprächen ist keine Feindseligkeit, sondern eine Form des Respekts. Erfahren Sie, wie diese Beziehungen im Alltag gelebt werden.","en":"Avoiding speech is not hostility but a form of respect. Learn how these relationships are practiced in daily life."},"readingMinutes":1,"sections":{"ar":[{"heading":"من يتجنب من؟","paragraphs":["أقوى أشكال التجنب شيوعًا هو بين الشخص وحماته. في العديد من المجموعات، لا يجوز لهما التحدث مباشرة أو حتى الاجتماع.","يمتد التجنب أيضًا إلى أقارب آخرين، حيث يجلسون منفصلين ويأكلون بعيدًا عن بعضهم البعض، ويمررون الرسائل عبر شخص ثالث."]},{"heading":"كيف يُمارَس التجنب؟","paragraphs":["يُعد التجنب علامة على الاحترام وليس العداء. تشمل بعض البروتوكولات خفض البصر مع أقارب معينين وعدم ذكر اسم شخص متوفى.","تحتفظ بعض المجموعات بمفردات تجنب خاصة للتحدث مع الأقارب المحظورين، بحيث لا تُستخدم اللغة اليومية على الإطلاق. تختلف هذه الممارسات في درجة نشاطها، وتتفاوض العائلات في المدن والبلدات على القواعد التي تحتفظ بها."]}],"de":[{"heading":"Wer vermeidet wen?","paragraphs":["Die stärkste Form der Vermeidung besteht zwischen einer Person und ihrer Schwiegermutter. In vielen Gruppen dürfen sie nicht direkt miteinander sprechen oder sich sogar treffen.","Die Vermeidung erstreckt sich auch auf andere Verwandte, die getrennt sitzen, getrennt essen und Nachrichten über Dritte weitergeben."]},{"heading":"Wie wird Vermeidung praktiziert?","paragraphs":["Vermeidung ist ein Zeichen von Respekt, nicht von Feindseligkeit. Zu den Protokollen gehören das Senken des Blicks bei bestimmten Verwandten und das Nichtaussprechen des Namens eines Verstorbenen.","Einige Gruppen bewahren ein spezielles Vermeidungsvokabular für die Kommunikation mit tabuisierten Verwandten, sodass die Alltagssprache gar nicht verwendet wird. Die Praktiken sind unterschiedlich stark aktiv, und Familien in Städten verhandeln, welche Regeln sie beibehalten."]}],"en":[{"heading":"Who avoids whom?","paragraphs":["The strongest common avoidance is between a person and their mother-in-law. In many groups, they may not speak directly or even meet.","Avoidance extends to other relatives, who sit separately, eat apart, and pass messages through a third person."]},{"heading":"How is avoidance practiced?","paragraphs":["Avoidance is a mark of respect, not hostility. Some protocols include lowering the gaze with certain kin and not speaking the name of a person who has died.","Some groups keep a special avoidance vocabulary for talking to restricted relatives, so the everyday language is not used at all. The practices remain active to varying degrees, and families in towns and cities negotiate which rules they keep."]}]},"context":{"countries":["AU"],"region":"Australia","community":"Aboriginal Australians","continent":"oceania","languages":["en"],"period":"contemporary"},"tags":["social-behaviour","Australia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Australian Aboriginal avoidance practices","de":"Australian Aboriginal avoidance practices","en":"Australian Aboriginal avoidance practices"},"url":"https://en.wikipedia.org/wiki/Australian_Aboriginal_avoidance_practices","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Australian Aboriginal kinship systems","de":"Australian Aboriginal kinship systems","en":"Australian Aboriginal kinship systems"},"url":"https://en.wikipedia.org/wiki/Australian_Aboriginal_kinship_systems","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"رجل وحماته يجلسان على جانبين متقابلين في تجمع عائلي ويمرران الرسائل عبر طفل؛ المسافة مجاملة وليست خصامًا.","de":"Ein Mann und seine Schwiegermutter sitzen bei einem Familientreffen auf gegenüberliegenden Seiten und übermitteln Nachrichten durch ein Kind; die Distanz ist Höflichkeit, kein Streit.","en":"A man and his mother-in-law sit on opposite sides of a family gathering and pass messages through a child; the distance is a courtesy, not a quarrel."},"misunderstanding":{"ar":"قد يفسر الغرباء التجنب على أنه عداء أو رفض، لكنه في الواقع تعبير عن الاحترام العميق.","de":"Außenstehende könnten Vermeidung als Feindseligkeit oder Ablehnung interpretieren, aber sie ist tatsächlich ein Ausdruck tiefen Respekts.","en":"Outsiders might interpret avoidance as hostility or rejection, but it is actually an expression of deep respect."},"comparison":{"ar":"بينما تتجنب بعض الثقافات مناقشة مواضيع معينة، فإن التجنب هنا يتعلق بعدم التحدث المباشر مع أشخاص محددين.","de":"Während einige Kulturen bestimmte Gesprächsthemen vermeiden, geht es hier um die Vermeidung direkter Gespräche mit bestimmten Personen.","en":"While some cultures avoid discussing certain topics, here avoidance is about not speaking directly to specific people."}},{"id":"oce-014","version":2,"slug":"reading-country-by-fire-and-season","contentType":"note","category":"nature-and-seasons","title":{"ar":"قراءة الأرض بالنار والفصول","de":"Land lesen mit Feuer und Jahreszeit","en":"Reading country by fire and season"},"deck":{"ar":"كيف يستخدم الناس في أستراليا النار الباردة لقراءة الفصول ورعاية الأرض","de":"Wie Menschen in Australien mit kühlem Feuer Jahreszeiten lesen und Land pflegen","en":"How people in Australia use cool fire to read the seasons and care for land"},"teaser":{"ar":"حرائق صغيرة باردة تُشعل في أوقات محددة بعلامات طبيعية، لا بتواريخ، لتحمي الأرض وتفتح مرعى جديداً.","de":"Kleine, kühle Feuer werden nach natürlichen Zeichen entzündet, nicht nach Daten – zum Schutz des Landes und für neues Grün.","en":"Small, cool fires lit by natural signs rather than dates protect ground and bring fresh green pick for animals."},"readingMinutes":1,"sections":{"ar":[{"heading":"نار تُقرأ قبل أن تُشعل","paragraphs":["يحرق السكان الأصليون في أستراليا الأرض عمداً منذ آلاف السنين: نيران باردة متفرقة تقلّل الوقود وتفتح الأرض للصيد وتنشّط نباتات نافعة.","التوقيت يتبع علامات لا تواريخ: تفتّح الأكاسيا، وجفاف العشب، وحركة النمل، والريح، كلها تخبر من يشعل متى يوقد.","يختلف هذا الإيقاع بين منطقة وأخرى وبين جيل وآخر، فبعض المجموعات تحتفظ بالتقويم الموسيقي شفهياً وبعضها يوثّقه مع الوكالات."]},{"heading":"إحياء بعد الانقطاع","paragraphs":["عطّلت الاستعمار هذه الممارسة، لكن مجموعات حرّاس السكان الأصليين والوكالات تعيد إحياءها، خصوصاً بعد موسم حرائق 2019-2020.","يسمّى الأسلوب الآن \"الحرق الثقافي\"، وقد صاغ عالم الآثار ريس جونز مصطلح \"الزراعة بالعصا النارية\" عام 1969.","تنشر هيئة الأرصاد الجوية الأسترالية اليوم عدة تقاويم موسمية أصلية بالتعاون مع المجتمعات المعنية."]}],"de":[{"heading":"Feuer, das vor dem Anzünden gelesen wird","paragraphs":["Aboriginale Menschen in Australien brennen das Land seit Jahrtausenden bewusst: kühle, fleckige Feuer verringern Brennmaterial, öffnen Flächen für die Jagd und fördern nützliche Pflanzen.","Der Zeitpunkt folgt Zeichen statt Daten: blühende Akazien, trocknendes Gras, Ameisenbewegung und Wind sagen, wann gezündet wird.","Dieser Rhythmus unterscheidet sich regional und zwischen Generationen; manche Gruppen geben den ökologischen Kalender mündlich weiter, andere dokumentieren ihn mit Behörden."]},{"heading":"Wiederbelebung nach dem Bruch","paragraphs":["Die Kolonisierung unterbrach diese Praxis; indigene Ranger-Gruppen und Behörden beleben sie wieder, besonders nach der Brandsaison 2019–20.","Die Technik heißt heute „cultural burning“; den Begriff „fire-stick farming“ prägte der Archäologe Rhys Jones 1969.","Das australische Wetteramt veröffentlicht heute mehrere indigene Jahreszeitenkalender gemeinsam mit den betreffenden Gemeinschaften."]}],"en":[{"heading":"Fire read before it is lit","paragraphs":["Aboriginal people in Australia have burned country deliberately for thousands of years: cool, patchy fires cut fuel, clear ground for hunting and promote useful plants.","Timing follows signs rather than dates: flowering wattle, curing grass, ant activity and wind tell a burner when to light.","That rhythm shifts between regions and generations; some groups keep their seasonal calendar orally, while others record it with agencies."]},{"heading":"Revival after the break","paragraphs":["Colonisation disrupted cultural burning, and Indigenous ranger groups and agencies are reviving it, especially after the 2019-20 fire season.","The technique is now called cultural burning; the term 'fire-stick farming' was coined by archaeologist Rhys Jones in 1969.","The Bureau of Meteorology now publishes several Indigenous seasonal calendars with the communities concerned."]}]},"context":{"countries":["AU"],"region":"Australia","community":"Aboriginal Australians","continent":"oceania","languages":["en"],"period":"contemporary"},"tags":["nature-and-seasons","Australia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Fire-stick farming","de":"Fire-stick farming","en":"Fire-stick farming"},"url":"https://en.wikipedia.org/wiki/Fire-stick_farming","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Indigenous Australian seasons","de":"Indigenous Australian seasons","en":"Indigenous Australian seasons"},"url":"https://en.wikipedia.org/wiki/Indigenous_Australian_seasons","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"ينتظر حارس أن يجفّ العشب، ثم يشعل حرقاً بطيئاً متقطعاً عند الغسق؛ فالنار الباردة تحمي شجرة الباندان وتجلب مرعى أخضر للكنغر.","de":"Ein Ranger wartet, bis das Gras trocken ist, und zündet in der Dämmerung ein langsames Flickwerkfeuer; das kühle Feuer schützt die Pandanus und bringt grünes Futter für Kängurus.","en":"A ranger waits for the grass to cure, then lights a slow patchwork burn at dusk; the cool fire protects the pandanus and brings green pick for kangaroo."},"misunderstanding":{"ar":"الحرق الثقافي ليس حلاً تقنياً عاماً يُنقل كما هو، بل ممارسة يقودها السكان الأصليون وتختلف باختلاف البلد والمجموعة.","de":"Cultural burning ist keine allgemeine technische Lösung, die sich einfach übertragen lässt, sondern eine von Indigenen geführte Praxis, die sich je nach Land und Gruppe unterscheidet.","en":"Cultural burning is Indigenous-led and not a universal technical fix; fire practice and seasonal calendars differ by country and group."},"comparison":{"ar":"حيث تُضبط الحرائق عادةً بالتواريخ والتقارير، تُضبط هنا بالإشارات البيئية الحيّة التي يقرأها الناس من الأرض.","de":"Wo Feuer sonst nach Daten und Berichten gesteuert wird, richtet es sich hier nach lebendigen ökologischen Zeichen, die Menschen vom Land ablesen.","en":"Where fire is usually managed by dates and reports, here it is managed by living ecological signs that people read from the land."}},{"id":"oce-016","version":2,"slug":"stolen-generations-and-sorry-day-the-long-aftermath-of-removal","contentType":"note","category":"migration-and-identity","title":{"ar":"الأجيال المسروقة ويوم الاعتذار","de":"Gestohlene Generationen und der Sorry Day","en":"Stolen Generations and the Long Shadow of Removal"},"deck":{"ar":"من 1905 إلى 1967، أُخذ أطفال السكان الأصليين من عائلاتهم. اليوم، يحمل الناجون ذكرى ثقيلة ويطالبون بالعدالة.","de":"Von 1905 bis 1967 wurden Aboriginal-Kinder ihren Familien entrissen. Heute tragen Überlebende schwer an der Erinnerung und fordern Gerechtigkeit.","en":"From 1905 to 1967, Aboriginal children were taken from their families. Today survivors carry the weight of memory and continue to demand justice."},"teaser":{"ar":"سياسات إزالة أطفال السكان الأصليين في أستراليا تركت جراحًا عميقة. يوم الاعتذار الوطني يحيي ذكراهم، والناجون يواصلون الكفاح.","de":"Australiens Politik der Kindesentziehung hinterließ tiefe Wunden. Der National Sorry Day erinnert an die Betroffenen, doch Überlebende kämpfen weiter.","en":"Australia's removal policies left deep wounds. National Sorry Day honours those affected, while survivors keep campaigning for compensation and an end to ongoing removals."},"readingMinutes":1,"sections":{"ar":[{"heading":"سياسات الإزالة وتأثيرها","paragraphs":["من حوالي 1905 إلى 1967، وفي بعض المناطق حتى السبعينيات، أُخذ أطفال السكان الأصليين وسكان جزر مضيق توريس من عائلاتهم بموجب قوانين الرعاية والحماية. استهدفت الإزالات بشكل خاص ما يسمى أطفال 'الهجناء'، وغالبًا ما فُصل الأشقاء بين المؤسسات والعائلات البيضاء.","سجل تقرير 'إحضارهم إلى الوطن' لعام 1997 شهادات الناجين، وقدر أن ما بين طفل من كل عشرة وطفل من كل ثلاثة أُخذوا في بعض المناطق بين 1910 و1970. تختلف السياسات وتأثيراتها حسب الولاية والفترة، و'الأجيال المسروقة' تصف نمطًا وليس حدثًا واحدًا."]},{"heading":"يوم الاعتذار والمطالبة بالتعويض","paragraphs":["يُحيى يوم الاعتذار الوطني في 26 مايو منذ عام 1998، وهو الذكرى الأولى لذلك التقرير. في عام 2008، قدم رئيس الوزراء كيفن رود الاعتذار الوطني في البرلمان، بينما يواصل الناجون الحملة من أجل التعويض وإنهاء عمليات الإزالة المستمرة. يختلف إحياء الذكرى بين الأجيال والمناطق، إذ يجمع بعض الشباب بين شهادات الأجداد والدعوات المعاصرة للعدالة."]}],"de":[{"heading":"Die Entziehungspolitik und ihre Folgen","paragraphs":["Etwa von 1905 bis 1967, an manchen Orten bis in die 1970er-Jahre, wurden Kinder der Aboriginal und Torres-Strait-Islander aufgrund von Fürsorge- und Schutzgesetzen aus ihren Familien geholt. Die Entziehungen zielten besonders auf sogenannte 'Halbblut'-Kinder, und Geschwister wurden oft zwischen Institutionen und weißen Familien aufgeteilt.","Der Bericht 'Bringing Them Home' von 1997 dokumentierte Zeugnisse von Überlebenden und schätzte, dass in einigen Regionen zwischen 1910 und 1970 jedes zehnte bis jedes dritte Kind weggenommen wurde. Die Politik und ihre Auswirkungen variierten je nach Bundesstaat und Zeitraum; 'Gestohlene Generationen' beschreibt ein Muster, kein Einzelereignis."]},{"heading":"Sorry Day und der Kampf um Entschädigung","paragraphs":["Seit 1998 wird am 26. Mai der National Sorry Day begangen, der erste Jahrestag jenes Berichts. 2008 sprach Premierminister Kevin Rudd im Parlament die nationale Entschuldigung aus, während Überlebende weiter für Entschädigung und ein Ende fortgesetzter Entziehungen kämpfen. Das Gedenken unterscheidet sich je nach Generation und Region – manche junge Menschen verbinden die Zeugnisse ihrer Großeltern mit aktuellen Forderungen nach Gerechtigkeit."]}],"en":[{"heading":"The removal policies and their impact","paragraphs":["From about 1905 to 1967, and in places into the 1970s, Aboriginal and Torres Strait Islander children were removed from their families under welfare and protection laws. The removals targeted so-called 'half-caste' children in particular, and siblings were often split between institutions and white families.","The 1997 Bringing Them Home report recorded survivors' testimony and estimated that between one in ten and one in three children were taken in some regions between 1910 and 1970. Removal policies and their effects varied by state and period, and 'Stolen Generations' describes a pattern rather than a single event."]},{"heading":"Sorry Day and the fight for compensation","paragraphs":["National Sorry Day has been held on 26 May since 1998, the first anniversary of that report. In 2008, Prime Minister Kevin Rudd delivered the national apology in Parliament, while survivors continue to campaign for compensation and for an end to ongoing removals. Commemoration varies across regions and generations, with some young people linking their grandparents' testimony to contemporary calls for justice."]}]},"context":{"countries":["AU"],"region":"Australia","community":"Aboriginal and Torres Strait Islander peoples","continent":"oceania","languages":["en"],"period":"contemporary"},"tags":["migration-and-identity","Australia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Stolen Generations","de":"Stolen Generations","en":"Stolen Generations"},"url":"https://en.wikipedia.org/wiki/Stolen_Generations","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"National Sorry Day","de":"National Sorry Day","en":"National Sorry Day"},"url":"https://en.wikipedia.org/wiki/National_Sorry_Day","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في 26 مايو، تقرأ مدرسة من تقرير 'إحضارهم إلى الوطن'؛ أحد الأجداد في الحضور أُخذ طفلًا ولم يرَ الملف الذي يسجل ذلك.","de":"Am 26. Mai liest eine Schule aus 'Bringing Them Home' vor; ein Großelternteil im Publikum wurde als Kind weggenommen und hat die Akte, die dies festhält, nie gesehen.","en":"On 26 May a school reads from Bringing Them Home; a grandparent in the audience was taken as a child and has never seen the file that records it."},"misunderstanding":{"ar":"يعتقد البعض أن 'الأجيال المسروقة' تشير إلى حدث واحد، لكنها تصف نمطًا من الإزالة استمر عقودًا وتنوع حسب الولاية والفترة.","de":"Manche glauben, 'Gestohlene Generationen' bezeichne ein einzelnes Ereignis, doch der Begriff beschreibt ein jahrzehntelanges Muster von Entziehungen, das je nach Bundesstaat und Zeitraum variierte.","en":"Some think 'Stolen Generations' refers to a single event, but it describes a decades-long pattern of removal that varied by state and period."},"comparison":{"ar":"بينما تعتذر الحكومات وتحيي الذكرى، يرى الناجون أن الاعتذار وحده لا يكفي دون تعويض ومعالجة عمليات الإزالة المستمرة.","de":"Während Regierungen sich entschuldigen und gedenken, sehen Überlebende allein in der Entschuldigung ohne Entschädigung und ohne Ende fortgesetzter Entziehungen keine ausreichende Wiedergutmachung.","en":"While governments apologise and commemorate, survivors argue that apology alone is not enough without compensation and an end to ongoing removals."}},{"id":"oce-017","version":2,"slug":"uluru-statement-from-the-heart-voice-treaty-truth","contentType":"note","category":"cultural-change","title":{"ar":"صوتٌ ومعاهدةٌ وحقيقةٌ من أولورو","de":"Stimme, Vertrag und Wahrheit aus Uluru","en":"Voice, Treaty, Truth from Uluru"},"deck":{"ar":"نصٌّ من صفحةٍ واحدة خرج من اتفاقيةٍ دستوريةٍ في قلب أستراليا، يطلب صوتًا للسكان الأصليين ومعاهدةً وسردًا للحقيقة.","de":"Ein einseitiger Text aus einer Verfassungsversammlung im Herzen Australiens fordert eine Stimme der First Nations, einen Vertrag und Wahreit.","en":"A one-page statement from a constitutional convention in the heart of Australia asks for a First Nations Voice, a treaty process and truth-telling."},"teaser":{"ar":"بعد حواراتٍ إقليميةٍ وأكثر من ألفٍ ومئتي مندوب، خرج نصٌّ قصيرٌ يطلب صوتًا دستوريًا ومعاهدةً وحقيقةً، ثم رفضه استفتاء ٢٠٢٣.","de":"Nach dreizehn regionalen Dialogen und über 1.200 Delegierten entstand ein kurzer Text, der Stimme, Vertrag und Wahrheit fordert – 2023 im Referendum abgelehnt.","en":"After thirteen regional dialogues and more than 1,200 delegates, a short text asked for Voice, Treaty, Truth — and was put to a 2023 referendum that rejected it."},"readingMinutes":1,"sections":{"ar":[{"heading":"نصٌّ قصيرٌ وطلبٌ كبير","paragraphs":["خرج بيان من القلب في أولورو عام ٢٠١٧ من اتفاقيةٍ دستوريةٍ وطنيةٍ للسكان الأصليين، بعد ثلاثة عشر حوارًا إقليميًا وأكثر من ألفٍ ومئتي مندوب.","يطلب البيان أمرين: صوتًا للسكان الأصليين مُكرَّسًا في الدستور، ولجنة ماكاراتا تشرف على إبرام الاتفاقيات وسرد الحقيقة.","والاختصار هو صوت ومعاهدة وحقيقة، والنص نفسه لا يزيد على صفحة، ويُختم بدعوةٍ لبقية الأستراليين للسير معًا."]},{"heading":"استفتاءٌ لم يُنهِ الجدل","paragraphs":["عُرض الصوت في استفتاءٍ في أكتوبر ٢٠٢٣، فرُفض بأغلبية الناخبين وأغلبية الولايات.","احتجّ المعارضون بأنه سيقسم الأستراليين أو يفتقر إلى التفاصيل، وأراد بعض قادة السكان الأصليين معاهدةً أولًا، فليس البيان نصًا توافقيًا.","ويختلف الموقف منه بين الأجيال والمناطق؛ فالشباب في المدن قد ينظرون إليه كخطوةٍ رمزية، بينما يشدّد كثيرون في المجتمعات النائية على المعاهدة أولًا."]}],"de":[{"heading":"Ein kurzer Text, eine große Bitte","paragraphs":["Die Uluru-Erklärung entstand 2017 aus der Nationalen Verfassungsversammlung der First Nations in Uluru, nach dreizehn regionalen Dialogen und mehr als 1.200 Delegierten.","Sie fordert zwei Dinge: eine in der Verfassung verankerte Stimme der First Nations und eine Makarrata-Kommission, die Vereinbarungen und Wahrheitserzählung begleitet.","Die Kurzformel lautet Stimme, Vertrag, Wahrheit; das Dokument selbst ist etwa eine Seite lang und endet mit einer Einladung an andere Australier, gemeinsam zu gehen."]},{"heading":"Ein Referendum, das den Streit nicht beendet","paragraphs":["Die Stimme wurde im Oktober 2023 in einem Referendum vorgelegt und von einer Mehrheit der Wähler und der Bundesstaaten abgelehnt.","Gegner argumentierten, sie spalte die Australier oder sei zu unkonkret, und manche Indigene Führungspersönlichkeiten wollten zuerst einen Vertrag – die Erklärung ist kein Konsensdokument.","Die Haltung dazu variiert regional und zwischen Generationen; jüngere Stadtbewohner sehen darin oft einen symbolischen Schritt, während viele in abgelegenen Gemeinschaften auf den Vertrag zuerst pochen."]}],"en":[{"heading":"A short text, a large ask","paragraphs":["The Uluru Statement from the Heart came out of the First Nations National Constitutional Convention at Uluru in 2017, after thirteen regional dialogues and more than 1,200 delegates.","It asks for two things: a First Nations Voice enshrined in the Constitution, and a Makarrata Commission to oversee agreement-making and truth-telling.","The shorthand is Voice, Treaty, Truth, and the document itself is about a page long, closing with an invitation to other Australians to walk together."]},{"heading":"A vote that did not settle it","paragraphs":["The Voice was put to a referendum in October 2023 and rejected by a majority of voters and a majority of states.","Opponents argued it would divide Australians or lacked detail, and some Indigenous leaders wanted a treaty first, so the statement is not a consensus document.","Attitudes vary by region and generation; younger city dwellers often read it as a symbolic step, while many in remote communities insist on treaty first."]}]},"context":{"countries":["AU"],"region":"Australia","community":"Aboriginal and Torres Strait Islander peoples","continent":"oceania","languages":["en"],"period":"contemporary"},"tags":["cultural-change","Australia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Uluru Statement from the Heart","de":"Uluru Statement from the Heart","en":"Uluru Statement from the Heart"},"url":"https://en.wikipedia.org/wiki/Uluru_Statement_from_the_Heart","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Indigenous Australians","de":"Indigenous Australians","en":"Indigenous Australians"},"url":"https://en.wikipedia.org/wiki/Indigenous_Australians","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تقرأ مجموعةٌ محلية البيان بصوتٍ عالٍ في اجتماع، ثم تتجادل حوله؛ بعضهم يريد المعاهدة أولًا، وصوت ٢٠٢٣ لم يحسم الجدل.","de":"Eine lokale Gruppe liest die Erklärung in einer Versammlung laut vor und streitet danach darüber; einige wollen zuerst den Vertrag, und die Abstimmung von 2023 hat den Streit nicht geklärt.","en":"A community group reads the statement aloud at a meeting and then argues about it; some want treaty first, and the 2023 vote did not settle the argument."},"misunderstanding":{"ar":"يُفهم أحيانًا أن البيان يمثل كل السكان الأصليين بإجماع، لكن الآراء لم تكن موحدة، وبعض القادة طالبوا بمعاهدةٍ قبل الصوت.","de":"Manchmal wird angenommen, die Erklärung vertrete alle Indigenen einstimmig, doch die Meinungen waren nicht einig, und einige Führungspersönlichkeiten forderten einen Vertrag vor der Stimme.","en":"It is sometimes assumed the statement speaks for all Indigenous people unanimously, but opinion was not unanimous and some leaders wanted a treaty before the Voice."},"comparison":{"ar":"يشبه هذا النقاش تجارب دولٍ تعالج فيها مجتمعاتٌ أصليةٌ علاقتها بالدولة عبر معاهداتٍ أو تمثيلٍ دستوري، لكن لكل سياقٍ مساره.","de":"Ähnlich wie in anderen Ländern ringen indigene Gemeinschaften um Verträge oder verfassungsrechtliche Vertretung, doch jeder Kontext hat seinen eigenen Weg.","en":"It resembles debates elsewhere where Indigenous peoples negotiate treaties or constitutional representation with the state, though each context follows its own path."}},{"id":"oce-018","version":2,"slug":"ailan-kastom-the-torres-strait-as-a-separate-people","contentType":"note","category":"traditions","title":{"ar":"أيلان كاستوم: شعب تورس سترايت المستقل","de":"Ailan Kastom: die Torres Strait als eigenes Volk","en":"Ailan Kastom: a people of the strait"},"deck":{"ar":"سكان جزر مضيق تورس شعب ميلانيزي ذو ثقافة مستقلة، تربطه بالبحر علاقة عميقة تمتد عبر الأجيال.","de":"Die Bewohner der Torres Strait sind ein melanesisches Volk mit eigener Kultur, dessen Alltag eng mit dem Meer verbunden bleibt.","en":"Torres Strait Islanders are a Melanesian people with a culture distinct from Aboriginal Australia, shaped by sea, language and annual remembrance."},"teaser":{"ar":"في مضيق تورس يعيش شعب ميلانيزي مستقل ثقافياً عن الأستراليين الأصليين، وتشكّل البحر واللغات والاحتفالات السنوية هويته اليومية.","de":"In der Torres Strait lebt ein melanesisches Volk, kulturell verschieden von den Aborigines, geprägt von Meer, drei Sprachen und dem jährlichen Fest des Lichts.","en":"In the Torres Strait a Melanesian people lives apart culturally from Aboriginal Australians, with the sea, three languages and a July festival shaping everyday identity."},"readingMinutes":1,"sections":{"ar":[{"heading":"شعب بحري بلغات ثلاث","paragraphs":["سكان جزر مضيق تورس شعب ميلانيزي، يختلف ثقافياً عن الأستراليين الأصليين، وتُعرف داخل المضيق خمس مجموعات جزرية واسعة.","لغتاهما الأصليتان الرئيستان هما كالاو لاغاو يا في الغرب وميريام مير في الشرق، بينما يُستخدم يومبلاتوك، وهو كريول إنجليزي الأساس، كلغة تواصل مشتركة.","البحر محور الحياة: كان السكان بحّارة ومزارعين، وما زال الصيد والإبحار يشكّلان الهوية والطعام."]},{"heading":"الإرسالية والميراث","paragraphs":["وصلت جمعية لندن التبشيرية عام 1871، وما زال «مجيء النور» في الأول من يوليو يُحتفل به سنوياً في الجزر.","كان إيدي كويكي مابو من مير أحد المدّعين في قرار المحكمة العليا عام 1992 الذي ألغى مبدأ الأرض المباحة وأقرّ حق الملكية الأصلية.","يعيش اليوم من سكان تورس سترايت في البر الأسترالي الرئيسي أكثر ممن يعيشون في الجزر، وأغلبهم في مدن كوينزلاند.","تختلف مظاهر الاحتفال بين الجزر وبين الأجيال، إذ يمزج الشباب في المدن التقاليد بحياتهم الحضرية."]}],"de":[{"heading":"Ein Volk der See mit drei Sprachen","paragraphs":["Die Bewohner der Torres Strait sind ein melanesisches Volk, kulturell deutlich verschieden von den Aborigines Australiens; innerhalb der Meerenge gelten fünf breite Inselgruppen.","Ihre beiden Hauptsprachen sind Kalaw Lagaw Ya im Westen und Meriam Mir im Osten, während Yumplatok, ein englischbasiertes Kreol, als gemeinsame Verkehrssprache dient.","Das Meer steht im Zentrum: Die Inselbewohner waren Seefahrer und Gärtner, und Fischerei und Seereisen prägen bis heute Identität und Essen."]},{"heading":"Mission und Vermächtnis","paragraphs":["1871 kam die London Missionary Society an, und der „Coming of the Light“ am 1. Juli wird bis heute jährlich auf den Inseln begangen.","Eddie Koiki Mabo von Mer war einer der Kläger im Urteil des High Court von 1992, das terra nullius aufhob und native title anerkannte.","Heute leben mehr Torres-Strait-Insulaner auf dem australischen Festland als auf den Inseln, überwiegend in den Städten Queenslands.","Wie das Fest begangen wird, unterscheidet sich regional und zwischen den Generationen; jüngere Stadtbewohner verbinden Tradition mit urbanem Alltag."]}],"en":[{"heading":"A seafaring people, three languages","paragraphs":["Torres Strait Islanders are a Melanesian people, culturally distinct from Aboriginal Australians, and five broad island groups are recognised within the strait.","Their two main Indigenous languages are Kalaw Lagaw Ya in the west and Meriam Mir in the east, while Yumplatok, an English-based creole, is the common lingua franca.","The sea is central: islanders were seafarers and gardeners, and fishing and voyaging still shape identity and food."]},{"heading":"Mission, land and a July festival","paragraphs":["The London Missionary Society arrived in 1871, and the Coming of the Light on 1 July is still marked annually across the islands.","Eddie Koiki Mabo from Mer was one of the plaintiffs in the 1992 High Court decision that overturned terra nullius and recognised native title.","More Torres Strait Islanders now live on mainland Australia than on the islands, mostly in Queensland cities.","How the day is kept varies by island and generation, and younger mainland families often blend church traditions with city life."]}]},"context":{"countries":["AU"],"region":"Torres Strait, Queensland","community":"Torres Strait Islander peoples","continent":"oceania","languages":["en"],"period":"contemporary"},"tags":["traditions","Torres Strait, Queensland"],"sources":[{"organization":"Wikipedia","title":{"ar":"Torres Strait Islanders","de":"Torres Strait Islanders","en":"Torres Strait Islanders"},"url":"https://en.wikipedia.org/wiki/Torres_Strait_Islanders","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Torres Strait Creole","de":"Torres Strait Creole","en":"Torres Strait Creole"},"url":"https://en.wikipedia.org/wiki/Torres_Strait_Creole","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في الأول من يوليو تقيم العائلات في جزيرة ثيرسدي آيلاند وفي كيرنز صلوات وولائم احتفاءً بمجيء النور، واللغة الكريولية المتحدثة أمام الميكروفون هي يومبلاتوك.","de":"Am 1. Juli feiern Familien auf Thursday Island und in Cairns mit Gottesdiensten und Festessen den Coming of the Light, und die Sprache am Mikrofon ist Yumplatok.","en":"On 1 July, families on Thursday Island and in Cairns hold church services and feasts for the Coming of the Light, and the creole spoken at the microphone is Yumplatok."},"misunderstanding":{"ar":"مضيق تورس ليس جزءاً من أستراليا الأصلية، ومجتمعات الجزر تختلف فيما بينها؛ ويومبلاتوك ليست إنجليزية فصيحة.","de":"Die Torres Strait gehört nicht zum Aboriginal Australia, und die Inselgemeinschaften unterscheiden sich voneinander; Yumplatok ist kein Standardenglisch.","en":"The Torres Strait is not part of Aboriginal Australia, and island communities differ among themselves; Yumplatok is not standard English."},"comparison":{"ar":"بينما يعيش كثير من سكان الجزر اليوم في مدن كوينزلاند، تبقى الجزر مرجع الهوية والاحتفال السنوي.","de":"Während viele Inselbewohner heute in Queenslander Städten leben, bleiben die Inseln Bezugspunkt für Identität und Jahresfest.","en":"While many islanders now live in Queensland cities, the islands remain the reference point for identity and the annual festival."}},{"id":"oce-019","version":2,"slug":"slip-slop-slap-how-sun-safety-became-australian-routine","contentType":"detail","category":"everyday-life","title":{"ar":"قبعة أو لا لعب: الشمس في الروتين الأسترالي","de":"Hut oder kein Spiel: Sonnenschutz als Alltag","en":"No Hat, No Play: Sun Safety as Routine"},"deck":{"ar":"كيف تحوّلت حماية الجلد من خيار شخصي إلى قاعدة يومية في المدارس الأسترالية.","de":"Wie aus einer Fernsehkampagne eine feste Regel im australischen Schulalltag wurde.","en":"How a simple television campaign turned sun protection into a fixed part of the Australian school day."},"teaser":{"ar":"حملة تلفزيونية بسيطة غيّرت عادات الأسر، وجعلت الوقاية من الشمس جزءاً من يوم الطفل الدراسي.","de":"Ein einfacher Werbespot veränderte Familiengewohnheiten und machte Sonnenschutz zu einem selbstverständlichen Teil des Schultags.","en":"A catchy jingle changed family habits and made sun protection an ordinary rule of childhood, not a private choice."},"readingMinutes":1,"sections":{"ar":[{"heading":"بداية من التبرعات","paragraphs":["بدأت الحملة عام 1981 بتمويل من تبرعات الناس، وأدارها مجلس السرطان في ولاية فيكتوريا لمحاولة إبطاء نسب سرطان الجلد المرتفعة في أستراليا.","كان طائر النورس سيد يغنّي على التلفزيون: ارتدِ قميصاً، وادهن واقياً، وضع قبعة. انتشرت الحملة في أستراليا ونيوزيلندا، ووصلت إلى وعي شبه كامل لدى الناس خلال سنوات قليلة.","تختلف الالتزامات بين المناطق والأجيال: فبعض الأسر تتبنّاها بحزم، وأخرى تكتفي ببعضها، وهو ما يظهر بوضوح في المدن الكبرى والمناطق الريفية على حد سواء."]},{"heading":"من الرسالة إلى القاعدة","paragraphs":["في 2010 أُضيف شعار جديد: ابحث عن الظل، وضع النظارات الشمسية، فأصبحت الرسالة تُعرف باسم SunSmart.","حوّلت المدارس الأسترالية الرسالة إلى قواعد مثل «لا قبعة، لا لعب»، فصارت حماية الجلد جزءاً من اليوم الدراسي لا قراراً فردياً.","تبقى العادات الوقائية غير متساوية، ونسب الميلانوما مرتفعة؛ فالأغنية حملة توعية لا وصف لسلوك الجميع."]}],"de":[{"heading":"Ein Anfang mit Spenden","paragraphs":["Die Kampagne begann 1981, finanziert durch öffentliche Spenden und organisiert vom Cancer Council Victoria, um Australiens hohe Hautkrebsraten zu senken.","Die Möwe Sid sang im Fernsehen: Hemd anziehen, Sonnencreme auftragen, Hut aufsetzen. Die Kampagne lief in Australien und Neuseeland und erreichte binnen weniger Jahre fast die gesamte Bevölkerung.","Regionale und generationelle Unterschiede sind deutlich: Manche Familien halten sich streng daran, andere nur teilweise, ob in großen Städten oder auf dem Land."]},{"heading":"Von der Botschaft zur Regel","paragraphs":["2010 kam eine Neuauflage mit „Seek and Slide“ hinzu – Schatten suchen und Sonnenbrille aufsetzen – und wurde zur SunSmart-Botschaft.","Australische Schulen machten daraus Regeln wie „no hat, no play“, sodass Sonnenschutz Teil des Schultags wurde und nicht der persönlichen Entscheidung überlassen blieb.","Die Gewohnheiten bleiben ungleich, und die Melanomraten sind weiterhin hoch; der Werbespot ist eine Kampagne, keine Beschreibung des Verhaltens aller."]}],"en":[{"heading":"Starting with Donations","paragraphs":["The campaign began in 1981, funded by public donations and run by Cancer Council Victoria to slow Australia's high skin-cancer rates.","Sid the Seagull sang on television: slip on a shirt, slop on sunscreen, slap on a hat. It ran in Australia and New Zealand and reached near-total public awareness within a few years.","Regional and generational differences are visible: some families follow the habits closely, others only partly, in big cities and country towns alike."]},{"heading":"From Message to Rule","paragraphs":["A 2010 revival added 'Seek and Slide' — seek shade and slide on sunglasses — and became the SunSmart message.","Australian schools turned it into rules such as 'no hat, no play', so sun protection became part of the school day rather than a personal choice.","Sun-safe habits are unevenly followed and melanoma rates remain high; the jingle is a campaign, not a description of everyone's behaviour."]}]},"context":{"countries":["AU"],"region":"Australia and New Zealand","continent":"oceania","languages":["en"],"period":"contemporary"},"tags":["everyday-life","Australia and New Zealand"],"sources":[{"organization":"Wikipedia","title":{"ar":"Slip-Slop-Slap","de":"Slip-Slop-Slap","en":"Slip-Slop-Slap"},"url":"https://en.wikipedia.org/wiki/Slip-Slop-Slap","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"SunSmart","de":"SunSmart","en":"SunSmart"},"url":"https://en.wikipedia.org/wiki/SunSmart","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تطبّق مدرسة ابتدائية قاعدة «لا قبعة، لا لعب»، ويحتفظ الأطفال بواقي الشمس قرب باب الصف، ولا يزال الناس يتعرّفون على الأغنية بعد أربعين عاماً من بثها الأول.","de":"Eine Grundschule setzt „no hat, no play“ durch; die Kinder bewahren Sonnencreme neben der Klassentür auf, und der Werbesong ist noch vierzig Jahre nach der ersten Ausstrahlung bekannt.","en":"A primary school enforces 'no hat, no play'; children keep sunscreen by the classroom door, and the jingle is still recognised forty years after it first aired."},"misunderstanding":{"ar":"يعتقد بعضهم أن الحملة تعني أن الجميع يلتزمون دائماً، لكن الالتزام يتباين، وأرقام سرطان الجلد ما زالت مرتفعة.","de":"Manche glauben, die Kampagne bedeute, dass sich alle immer daran halten, doch die Befolgung schwankt und die Hautkrebszahlen bleiben hoch.","en":"Some assume the campaign means everyone always complies, but adherence varies and skin-cancer rates remain high."},"comparison":{"ar":"في بلدان كثيرة تُترك الوقاية من الشمس للاختيار الشخصي، أما في أستراليا فدخلت في قواعد المدرسة واليوم الدراسي.","de":"In vielen Ländern bleibt Sonnenschutz persönliche Wahl, in Australien wurde er Teil der Schulregeln und des Schulalltags.","en":"In many countries sun protection stays a personal choice; in Australia it entered school rules and the daily timetable."}},{"id":"oce-020","version":2,"slug":"bogan-a-class-joke-australians-and-new-zealanders-keep-telling","contentType":"note","category":"regional-humour","title":{"ar":"بوغان: نكتة طبقية يكررها الأستراليون والنيوزيلنديون","de":"Bogan: ein Klassenwitz, den Australier und Neuseeländer immer wieder erzählen","en":"Bogan: a class joke Australians and New Zealanders keep telling"},"deck":{"ar":"كلمة عامية تصف من تُعتبر أذواقهم أو ملابسهم غير مهذبة، لكنها قد تصبح شارة هوية.","de":"Ein Slangwort für Menschen mit als unfein geltenden Manieren – mal Beleidigung, mal Identitätsabzeichen.","en":"A slang label for people seen as unrefined, often working-class – sometimes an insult, sometimes a badge of identity."},"teaser":{"ar":"من هم 'البوغان'؟ كلمة تتراوح بين الإهانة والفكاهة، وتعكس مواقف طبقية في أستراليا ونيوزيلندا.","de":"Was ist ein 'Bogan'? Ein Wort zwischen Spott und Stolz, das Klassenvorurteile in Australien und Neuseeland spiegelt.","en":"What is a bogan? A word that shifts between mockery and pride, reflecting class attitudes in Australia and New Zealand."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما تعنيه الكلمة","paragraphs":["كلمة 'بوغان' في العامية الأسترالية والنيوزيلندية تصف شخصًا يُنظر إلى كلامه أو ملابسه أو أذواقه على أنها غير مهذبة، وغالبًا ما تحمل مسحة من الطبقة العاملة. يمكن أن تكون إهانة أو شارة هوية: فبعض الناس يصفون أنفسهم بـ'بوغان' بمحبة بينما يسخرون من اللقب.","ظهرت كثقافة فرعية مميزة في الثمانينيات، حيث أصبحت قصات الشعر الطويلة من الخلف (mullets) والقمصان الصوفية وأحذية Ugg والسيارات الصاخبة علامات مختصرة. وحتى قاموس ماكواري يعطي أصل الكلمة على أنه غير معروف، وهو ما يناسب لقبًا يتغير مع الموضة."]},{"heading":"الفكاهة والاختلاف","paragraphs":["في حفلة شواء، يُنعت أحدهم بـ'بوغان' بسبب قصة شعره وسيارته؛ فيضحك ويصف ذلك بأنه أسلوب حياة. النكتة تعتمد كليًا على من قالها. الكلمة تحمل طابعًا طبقيًا وقد تجرح، ومعناها يتغير حسب الولاية والعمر والمتحدث."]}],"de":[{"heading":"Was das Wort bedeutet","paragraphs":["'Bogan' ist australischer und neuseeländischer Slang für eine Person, deren Sprache, Kleidung oder Geschmack als unfein gelten, oft mit einem Hauch von Arbeiterklasse. Es kann eine Beleidigung oder ein Identitätsabzeichen sein: Manche nennen sich liebevoll selbst 'Bogan', während sie das Etikett verspotten.","In den 1980er Jahren entstand eine erkennbare Subkultur, mit Vokuhila, Flanellhemden, Ugg-Boots und lauten Autos als Kurzformeln. Selbst das Macquarie Dictionary gibt die Herkunft als unbekannt an – passend für ein Label, das sich mit der Mode wandelt."]},{"heading":"Humor und Unterschiede","paragraphs":["Bei einem Barbecue wird jemand wegen seines Vokuhilas und seines Autos 'Bogan' genannt; er lacht und nennt es einen Lebensstil. Der Witz hängt ganz davon ab, wer ihn macht. 'Bogan' ist ein klassenmarkiertes Wort, das verletzen kann, und seine Bedeutung ändert sich je nach Bundesstaat, Alter und Sprecher."]}],"en":[{"heading":"What the word means","paragraphs":["'Bogan' is Australian and New Zealand slang for a person whose speech, clothes or tastes are seen as unrefined, often with a working-class edge. It can be an insult or a badge of identity: people call themselves bogans affectionately while mocking the label.","It emerged as a recognisable subculture in the 1980s, with mullets, flannel, Ugg boots and loud cars as shorthand. Even the Macquarie Dictionary gives the origin as unknown, which suits a label that shifts with fashion."]},{"heading":"Humour and variation","paragraphs":["At a barbecue someone is called a bogan for his mullet and his car; he laughs and calls it a lifestyle, and the joke depends entirely on who said it. Bogan is a class-marked word that can wound, and its meaning shifts by state, age and who is speaking."]}]},"context":{"countries":["AU","NZ"],"region":"Australia and New Zealand","continent":"oceania","languages":["en"],"period":"contemporary"},"tags":["regional-humour","Australia and New Zealand"],"sources":[{"organization":"Wikipedia","title":{"ar":"Bogan","de":"Bogan","en":"Bogan"},"url":"https://en.wikipedia.org/wiki/Bogan","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Ocker","de":"Ocker","en":"Ocker"},"url":"https://en.wikipedia.org/wiki/Ocker","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في حفلة شواء، يُنعت أحدهم بـ'بوغان' بسبب قصة شعره وسيارته؛ فيضحك ويصف ذلك بأنه أسلوب حياة، والنكتة تعتمد كليًا على من قالها.","de":"Bei einem Barbecue wird jemand wegen seines Vokuhilas und seines Autos 'Bogan' genannt; er lacht und nennt es einen Lebensstil, und der Witz hängt ganz davon ab, wer ihn macht.","en":"At a barbecue someone is called a bogan for his mullet and his car; he laughs and calls it a lifestyle, and the joke depends entirely on who said it."},"misunderstanding":{"ar":"يعتقد البعض أن الكلمة مجرد إهانة، لكنها قد تكون أيضًا تعبيرًا عن الفخر والانتماء.","de":"Manche halten das Wort für eine reine Beleidigung, doch es kann auch Ausdruck von Stolz und Zugehörigkeit sein.","en":"Some assume the word is only an insult, but it can also express pride and belonging."},"comparison":{"ar":"لها أبناء عمومة أقدم: 'الأوكر' و'اللاريكين' في أستراليا، وأسماء محلية مثل 'ويستي' في نيوزيلندا.","de":"Es hat ältere Vettern: den 'Ocker' und den 'Larrikin' in Australien sowie lokale Namen wie 'Westie' in Neuseeland.","en":"It has older cousins: the ocker and the larrikin in Australia, and local names such as westie in New Zealand."}},{"id":"oce-021","version":2,"slug":"fa-amatai-how-samoan-families-choose-who-speaks-for-them","contentType":"note","category":"social-behaviour","title":{"ar":"فاماتاي: كيف تختار العائلات الساموية من يتحدث باسمها","de":"Faʻamatai: Wie samoanische Familien ihren Sprecher wählen","en":"Faʻamatai: how Samoan families choose who speaks for them"},"deck":{"ar":"نظام الزعامة في ساموا يمنح العائلة الموسعة سلطة اختيار ممثلها في المجالس والقضاء العرفي.","de":"Das Häuptlingstitelsystem Samoas gibt der Großfamilie die Macht, ihren Vertreter in Räten und customary law zu bestimmen.","en":"Samoa’s chiefly title system gives the extended family the power to pick its representative in councils and customary law."},"teaser":{"ar":"في ساموا، اللقب ليس ملكاً فردياً بل أمانة عائلية؛ تختار العائلة من يحمله بعد نقاش طويل.","de":"In Samoa ist ein Titel kein persönliches Eigentum, sondern ein Familienauftrag; die Großfamilie entscheidet nach langer Debatte, wer ihn trägt.","en":"In Samoa a title is not personal property but a family trust; the extended family decides after long debate who will hold it."},"readingMinutes":1,"sections":{"ar":[{"heading":"اللقب ملك للعائلة","paragraphs":["في ساموا، يحمل لقب matai الزعيم العائلي، لكن اللقب نفسه ملك للعائلة الموسعة (ʻāiga) التي تقرر من سيشغله. لا يمكن لأحد أن يطالب به منفرداً؛ فالموافقة العائلية شرط أساسي.","تُصنف الألقاب بين رؤساء كبار (aliʻi) وخطباء (tulafale) يتحدثون باسم العائلة في المجالس. ويُمنح اللقب في حفل saofaʻi بعد توافق العائلة، وأي نزاع يُحال إلى محكمة الأراضي والألقاب لا إلى المحاكم العادية."]},{"heading":"من العائلة إلى البرلمان","paragraphs":["يوجد في ساموا نحو 360 مجلس قرية (fono o matai) تتعامل مع المسائل المدنية والجنائية وفق القانون العرفي، وقد عزز قانون مجالس القرى لعام 1990 دورها. ويصل النظام إلى السياسة الوطنية: أعضاء البرلمان الساموي من الـ matai، ومجلس شيوخ ساموا الأمريكية يختاره مجالس المقاطعات من بين الـ matai."]}],"de":[{"heading":"Der Titel gehört der Familie","paragraphs":["In Samoa tragen matai den Häuptlingstitel einer Familie, doch der Titel gehört der Großfamilie (ʻāiga), die entscheidet, wer ihn innehat. Niemand kann ihn allein beanspruchen; familiärer Konsens ist Voraussetzung.","Titel sind rangmäßig zwischen hohen Häuptlingen (aliʻi) und Rednern (tulafale) aufgeteilt, die in Räten für die Familie sprechen. Verliehen wird ein Titel bei einer saofaʻi-Zeremonie erst nach Familienkonsens; Streitigkeiten gehen an das Land and Titles Court, nicht an ordentliche Gerichte."]},{"heading":"Von der Familie ins Parlament","paragraphs":["Samoa hat rund 360 Dorfräte (fono o matai), die zivile und strafrechtliche Angelegenheiten nach customary law behandeln; der Village Fono Law von 1990 stärkte ihre Rolle. Das System reicht in die nationale Politik: Samoas Parlamentsmitglieder sind matai, und der Senat Amerikanisch-Samoas wird von Distriktsräten aus den matai gewählt."]}],"en":[{"heading":"The title belongs to the family","paragraphs":["In Samoa, matai hold family chief titles, but the title belongs to the extended family (ʻāiga), which chooses who will hold it. No one can claim it alone; family consensus is required.","Titles are ranked and divided between high chiefs (aliʻi) and orators (tulafale), who speak for the family in councils. A title is conferred at a saofaʻi ceremony only after family consensus, and disputes go to the Land and Titles Court rather than the ordinary courts."]},{"heading":"From family to parliament","paragraphs":["Samoa has around 360 village councils (fono o matai) handling civil and criminal matters under customary law; the 1990 Village Fono Law strengthened their role. The system reaches national politics: members of Samoa’s parliament are matai, and American Samoa’s Senate is chosen by district councils from among matai."]}]},"context":{"countries":["WS"],"region":"Samoa","community":"Samoan","continent":"oceania","languages":["sm","en"],"period":"contemporary"},"tags":["social-behaviour","Samoa"],"sources":[{"organization":"Wikipedia","title":{"ar":"Faʻamatai","de":"Faʻamatai","en":"Faʻamatai"},"url":"https://en.wikipedia.org/wiki/Fa%CA%BBamatai","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Faʻa Sāmoa","de":"Faʻa Sāmoa","en":"Faʻa Sāmoa"},"url":"https://en.wikipedia.org/wiki/Fa%CA%BBa_S%C4%81moa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تجتمع عائلة لأسابيع قبل اختيار matai جديد؛ وفي حفل saofaʻi يُمنح اللقب، ثم يتحدث الـ matai الجديد باسم العائلة في مجلس القرية.","de":"Eine Familie tagt wochenlang, bevor sie einen neuen matai wählt; bei der saofaʻi wird der Titel verliehen, und der neue matai spricht dann für die Familie im Dorf-fono.","en":"A family meets for weeks before choosing a new matai; at the saofaʻi the title is conferred, and the new matai then speaks for the family at the village fono."},"misunderstanding":{"ar":"ليس كل ساموي يحمل لقب matai، والنظام محل جدل بقدر ما هو محل احترام.","de":"Nicht jeder Samoaner trägt einen matai-Titel, und das System ist ebenso umstritten wie respektiert.","en":"Not every Samoan holds a matai title, and the system is contested as well as respected."},"comparison":{"ar":"بينما تعتمد بعض المجتمعات على الانتخاب الفردي، يمنح نظام فاماتاي العائلة سلطة اختيار ممثلها الجماعي.","de":"Während manche Gesellschaften auf individuelle Wahl setzen, gibt Faʻamatai der Familie die Macht, ihren kollektiven Vertreter zu bestimmen.","en":"While some societies rely on individual election, faʻamatai gives the family the power to choose its collective representative."}}];

export default { version: 2, items };
